static std::string normalizeVideoPackagingMode_(const std::string& value)
{
    const std::string normalized = lowerAsciiCopy_(trimAscii(value));
    if (normalized == "frame_sequence" ||
        normalized == "frame-sequence" ||
        normalized == "full_frame" ||
        normalized == "full-frame" ||
        normalized == "frames" ||
        normalized == "high_resolution" ||
        normalized == "high-resolution" ||
        normalized == "high resolution")
    {
        return "frame_sequence";
    }
    if (normalized == "mosaic_2x2" ||
        normalized == "mosaic-2x2" ||
        normalized == "2x2" ||
        normalized == "standard_resolution" ||
        normalized == "standard-resolution" ||
        normalized == "standard resolution")
    {
        return "mosaic_2x2";
    }
    if (normalized == "mosaic" ||
        normalized == "mosaic_3x3" ||
        normalized == "mosaic-3x3" ||
        normalized == "3x3" ||
        normalized == "compact_resolution" ||
        normalized == "compact-resolution" ||
        normalized == "compact resolution")
    {
        // Deprecated: 3x3 mosaics compress temporal/detail evidence too aggressively.
        return "frame_sequence";
    }
    return "frame_sequence";
}


static bool extractTimestampFromFrameStem(const std::string& stem,
    std::string& outTs)
{
    std::vector<std::string> parts;
    std::stringstream ss(stem);
    std::string token;

    while (std::getline(ss, token, '_')) {
        parts.push_back(token);
    }

    // Expect at least: [cameraId, YYYYMMDD, HHMMSS, frameId]
    if (parts.size() < 3) {
        return false;
    }

    // Build "YYYYMMDD_HHMMSS"
    outTs = parts[1] + "_" + parts[2];
    return true;
}


