struct PromptVideoFrame {
    int frameIndex = -1;
    std::string timestampName;
    std::string frameTimestampInSegment;
    std::string jpegBase64;
    bool hasAbsoluteTimestamp = false;
    std::chrono::system_clock::time_point absoluteTimestamp{};
};

static std::string buildPromptVideoFrameMetaText_(const PromptVideoFrame& frame)
{
    nlohmann::json meta = {
        { "frame_index", frame.frameIndex },
        { "frame_timestamp_in_segment", frame.frameTimestampInSegment }
    };
    return std::string("FRAME_META_JSON: ") + meta.dump();
}

static constexpr int kPromptVideoMosaicWidth_ = 1920;
static constexpr int kPromptVideoMosaicHeight_ = 1080;

struct PromptVideoMosaicProfile_ {
    // Legacy defaults retained only for explicit deprecated 3x3 profile construction.
    const char* videoPackagingMode = "mosaic_3x3";
    const char* layoutId = "openai_video_mosaic_3x3_v1";
    int columns = 3;
    int rows = 3;
    int maxFramesPerMosaic = 9;
};

static constexpr PromptVideoMosaicProfile_ kPromptVideoMosaicProfile2x2_ = {
    "mosaic_2x2",
    "openai_video_mosaic_2x2_v1",
    2,
    2,
    4
};

// Deprecated legacy profile. Keep only for backward compatibility with stored
// configs and historical log decoding; chat video search/upload no longer use it.
