static std::string formatChatCameraLabelList_(
    const std::vector<std::string>& labels)
{
    if (labels.empty()) {
        return std::string();
    }
    if (labels.size() == 1) {
        return labels.front();
    }

    std::ostringstream oss;
    for (std::size_t i = 0; i < labels.size(); ++i) {
        if (i > 0) {
            oss << ", ";
        }
        oss << labels[i];
    }
    return oss.str();
}

