    static void buildFallbackIdentityAttributesFromText_(
        const std::string& focusText,
        const std::string& rawEntityType,
        nlohmann::json& outSignatureTraits,
        nlohmann::json& outFeatureCandidates)
    {
        const std::string normalizedText = normalizeTemporalCueText_(focusText);
        if (normalizedText.empty()) return;

        const std::string entityType = normalizeFallbackEntityType_(rawEntityType);
        const std::string colorCue = detectColorCueForIdentityText_(normalizedText);
        const std::string hairColorCue = detectHairColorCueForIdentityText_(normalizedText);
        const std::string skinToneCue = detectSkinToneCueForIdentityText_(normalizedText);
        const std::string bodyBuildCue = detectBodyBuildCueForIdentityText_(normalizedText);

        auto hasCue = [&](std::initializer_list<const char*> cues) {
            for (const char* cue : cues) {
                if (cue == nullptr || *cue == '\0') continue;
                if (normalizedText.find(cue) != std::string::npos) return true;
            }
            return false;
        };

        auto appendIdentityCue = [&](const std::string& text,
                                     const char* category,
                                     const char* relation) {
            const std::string trimmed = trimAscii(text);
            if (trimmed.empty()) return;
            appendUniqueTrimmedStringsToJsonArray_(outSignatureTraits, trimmed);
            nlohmann::json item = nlohmann::json::object({
                { "text", trimmed },
                { "category", category == nullptr ? std::string() : std::string(category) },
                { "relation_to_target", relation == nullptr ? std::string() : std::string(relation) }
            });
            appendUniqueIdentityFeatureCandidatesToJsonArray_(
                outFeatureCandidates,
                nlohmann::json::array({ item }));
        };

        if (entityType == "person") {
            if (!skinToneCue.empty()) {
                appendIdentityCue(skinToneCue, "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "cabelo curto", "short hair" })) {
                appendIdentityCue("short hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({
                    "cabelo raspado",
                    "cabelos raspados",
                    "raspado",
                    "raspados",
                    "buzz cut",
                    "shaved head",
                    "very short hair",
                    "cabelo muito curto",
                    "muito curtos"
                }))
            {
                appendIdentityCue("very short hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "cabelo comprido", "cabelo longo", "long hair" })) {
                appendIdentityCue("long hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({
                    "cabelo preso",
                    "cabelos presos",
                    "hair tied back",
                    "tied back hair",
                    "tied-back hair",
                    "ponytail",
                    "rabo de cavalo"
                }))
            {
                appendIdentityCue("hair tied back", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "cabelo cacheado", "curly hair" })) {
                appendIdentityCue("curly hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "cabelo liso", "straight hair" })) {
                appendIdentityCue("straight hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "cabelo ondulado", "wavy hair" })) {
                appendIdentityCue("wavy hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "cabelo crespo", "coily hair" })) {
                appendIdentityCue("coily hair", "physical_trait", "intrinsic_body");
            }
            if (!hairColorCue.empty() && hasCue({ "cabelo", "hair" })) {
                appendIdentityCue(hairColorCue + " hair", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "barba baixa", "barba curta", "barba por fazer", "stubble", "short beard", "light beard" })) {
                appendIdentityCue("short beard", "physical_trait", "intrinsic_body");
            }
            else if (hasCue({ "barba", "beard" })) {
                appendIdentityCue("beard", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "bigode", "mustache", "moustache" })) {
                appendIdentityCue("mustache", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "careca", "calvo", "bald" })) {
                appendIdentityCue("bald", "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "tatuagem", "tattoo" })) {
                appendIdentityCue("tattoo", "body_marking", "intrinsic_body");
            }
            if (hasCue({ "cicatriz", "scar" })) {
                appendIdentityCue("scar", "body_marking", "intrinsic_body");
            }
            if (!bodyBuildCue.empty()) {
                appendIdentityCue(bodyBuildCue, "physical_trait", "intrinsic_body");
            }
            if (hasCue({ "oculos", "glasses" })) {
                appendIdentityCue("glasses", "accessory", "worn_on_target");
            }
            if ((!outSignatureTraits.is_array() || outSignatureTraits.empty()) &&
                hasCue({ "camisa", "camiseta", "shirt" }))
            {
                appendIdentityCue(
                    colorCue.empty() ? "shirt" : colorCue + " shirt",
                    "clothing",
                    "worn_on_target");
            }
            if ((!outSignatureTraits.is_array() || outSignatureTraits.empty()) &&
                hasCue({ "jaqueta", "jacket" }))
            {
                appendIdentityCue(
                    colorCue.empty() ? "jacket" : colorCue + " jacket",
                    "clothing",
                    "worn_on_target");
            }
            if ((!outSignatureTraits.is_array() || outSignatureTraits.empty()) &&
                hasCue({ "bone", "chapeu", "hat", "cap" }))
            {
                appendIdentityCue(
                    colorCue.empty() ? "hat" : colorCue + " hat",
                    "accessory",
                    "worn_on_target");
            }
            if ((!outSignatureTraits.is_array() || outSignatureTraits.empty()) &&
                hasCue({ "mochila", "backpack" }))
            {
                appendIdentityCue(
                    colorCue.empty() ? "backpack" : colorCue + " backpack",
                    "accessory",
                    "carried_by_target");
            }
            if ((!outSignatureTraits.is_array() || outSignatureTraits.empty()) &&
                hasCue({ "bolsa", "bag" }))
            {
                appendIdentityCue(
                    colorCue.empty() ? "bag" : colorCue + " bag",
                    "accessory",
                    "carried_by_target");
            }
        }
        else if (entityType == "vehicle") {
            if (!colorCue.empty()) {
                appendIdentityCue(
                    colorCue + " vehicle",
                    "vehicle_detail",
                    "vehicle_body");
            }
        }
        else if (entityType == "animal") {
            if (!colorCue.empty()) {
                appendIdentityCue(
                    colorCue + " animal",
                    "physical_trait",
                    "intrinsic_body");
            }
        }
        else {
            const std::string objectCue = detectSpecificObjectCueForIdentityText_(normalizedText);
            if (!objectCue.empty()) {
                appendIdentityCue(
                    colorCue.empty() ? objectCue : colorCue + " " + objectCue,
                    "object_detail",
                    "intrinsic_body");
            }
            else if (!colorCue.empty()) {
                appendIdentityCue(
                    colorCue + " object",
                    "object_detail",
                    "intrinsic_body");
            }
        }
    }

    static std::string selectIdentityPatchFallbackText_(
        const nlohmann::json& patch)
    {
        if (!patch.is_object()) return std::string();
        const std::string description =
            trimAscii(patch.value("description", std::string()));
        if (!description.empty()) return description;
        const std::string shortDescription =
            trimAscii(patch.value("short_description", std::string()));
        if (!shortDescription.empty()) return shortDescription;
        return trimAscii(patch.value("identity_signature_summary", std::string()));
    }

    static void normalizeIdentityPatchItemForMemory_(
        nlohmann::json& item)
    {
        if (!item.is_object()) return;

        const std::string entityType =
            normalizeFallbackEntityType_(item.value("entity_type", std::string()));
        const nlohmann::json explicitSignatureTraits =
            item.contains("identity_signature_traits")
                ? temporal::parseTraitsValue(item["identity_signature_traits"])
                : nlohmann::json::array();
        nlohmann::json signatureTraits =
            explicitSignatureTraits;
        nlohmann::json featureCandidates =
            item.contains("identity_feature_candidates")
                ? item["identity_feature_candidates"]
                : nlohmann::json::array();
        featureCandidates =
            temporal::filterIdentityFeatureCandidatesForMemory(entityType, featureCandidates);

        const nlohmann::json stableTraits =
            temporal::extractStableTraitsFromNode(item, entityType);
        const nlohmann::json contextTraits =
            temporal::extractContextTraitsFromNode(item, entityType);
        signatureTraits =
            temporal::curateIdentitySignatureTraits(
                entityType,
                stableTraits,
                contextTraits,
                signatureTraits);
        appendUniqueIdentityFeatureCandidatesToJsonArray_(
            featureCandidates,
            buildManualIdentityFeatureCandidatesFromTraits_(signatureTraits));
        featureCandidates =
            temporal::filterIdentityFeatureCandidatesForMemory(entityType, featureCandidates);

        const bool explicitTraitsAlreadyRich =
            entityType == "person" &&
            explicitSignatureTraits.is_array() &&
            explicitSignatureTraits.size() >= 2 &&
            signatureTraits.is_array() &&
            signatureTraits.size() >= 2;

        const bool needsPersonReinforcement =
            entityType == "person" &&
            !explicitTraitsAlreadyRich &&
            (
                !signatureTraits.is_array() ||
                signatureTraits.size() < 3 ||
                !featureCandidates.is_array() ||
                featureCandidates.size() < 3
            );

        if ((!signatureTraits.is_array() || signatureTraits.empty()) ||
            (!featureCandidates.is_array() || featureCandidates.empty()) ||
            needsPersonReinforcement)
        {
            const std::string fallbackText = selectIdentityPatchFallbackText_(item);
            nlohmann::json fallbackTraits = nlohmann::json::array();
            nlohmann::json fallbackFeatureCandidates = nlohmann::json::array();
            buildFallbackIdentityAttributesFromText_(
                fallbackText,
                entityType,
                fallbackTraits,
                fallbackFeatureCandidates);
            appendUniqueTrimmedStringsToJsonArray_(signatureTraits, fallbackTraits);
            appendUniqueIdentityFeatureCandidatesToJsonArray_(
                featureCandidates,
                fallbackFeatureCandidates);
            featureCandidates =
                temporal::filterIdentityFeatureCandidatesForMemory(entityType, featureCandidates);
            signatureTraits =
                temporal::curateIdentitySignatureTraits(
                    entityType,
                    stableTraits,
                    contextTraits,
                    signatureTraits);
        }

        if (signatureTraits.is_array() && !signatureTraits.empty()) {
            item["identity_signature_traits"] = signatureTraits;
        }
        else {
            item.erase("identity_signature_traits");
        }

        if (featureCandidates.is_array() && !featureCandidates.empty()) {
            item["identity_feature_candidates"] = featureCandidates;
        }
        else {
            item.erase("identity_feature_candidates");
        }
    }

    static void normalizeIdentityPatchArrayForMemory_(
        nlohmann::json& identityPatch,
        const std::string& logStreamId = std::string(),
        const std::string& scopeTag = std::string())
    {
        if (!identityPatch.is_array()) return;

        int enrichedItems = 0;
        for (auto& item : identityPatch) {
            if (!item.is_object()) continue;
            const std::size_t beforeCount =
                item.contains("identity_signature_traits") &&
                item["identity_signature_traits"].is_array()
                    ? item["identity_signature_traits"].size()
                    : 0;
            normalizeIdentityPatchItemForMemory_(item);
            const std::size_t afterCount =
                item.contains("identity_signature_traits") &&
                item["identity_signature_traits"].is_array()
                    ? item["identity_signature_traits"].size()
                    : 0;
            if (afterCount > beforeCount) {
                ++enrichedItems;
            }
        }

        if (enrichedItems > 0 &&
            !logStreamId.empty() &&
            !scopeTag.empty())
        {
            Logger::instance().logDebug(
                logStreamId,
                scopeTag + ": normalized identity_patch traits enriched_items=" +
                    std::to_string(enrichedItems));
        }
    }

    static void mergeFallbackIdentityTraitsIntoPositivePatch_(
        VideoHit& hit,
        const std::string& logStreamId = std::string(),
        const std::string& scopeTag = std::string())
    {
        if (!hit.identityPatch.is_array() || hit.identityPatch.empty()) return;

        const nlohmann::json fallbackPatch =
            buildFallbackIdentityPatchForPositiveHit_(hit, nlohmann::json::object(), true);
        if (!fallbackPatch.is_object() || fallbackPatch.empty()) return;

        bool mergedAny = false;
        for (auto& item : hit.identityPatch) {
            if (!item.is_object() || !temporalIdentityPatchCarriesPositiveEntity_(item)) continue;

            const bool missingSignatureTraits =
                !item.contains("identity_signature_traits") ||
                !item["identity_signature_traits"].is_array() ||
                item["identity_signature_traits"].empty();
            const bool missingFeatureCandidates =
                !item.contains("identity_feature_candidates") ||
                !item["identity_feature_candidates"].is_array() ||
                item["identity_feature_candidates"].empty();

            if (missingSignatureTraits &&
                fallbackPatch.contains("identity_signature_traits") &&
                fallbackPatch["identity_signature_traits"].is_array() &&
                !fallbackPatch["identity_signature_traits"].empty())
            {
                item["identity_signature_traits"] = fallbackPatch["identity_signature_traits"];
                mergedAny = true;
            }
            if (missingFeatureCandidates &&
                fallbackPatch.contains("identity_feature_candidates") &&
                fallbackPatch["identity_feature_candidates"].is_array() &&
                !fallbackPatch["identity_feature_candidates"].empty())
            {
                item["identity_feature_candidates"] = fallbackPatch["identity_feature_candidates"];
                mergedAny = true;
            }

            normalizeIdentityPatchItemForMemory_(item);
            break;
        }

        if (mergedAny &&
            !logStreamId.empty() &&
            !scopeTag.empty())
        {
            Logger::instance().logDebug(
                logStreamId,
                scopeTag + ": merged fallback identity traits into positive identity_patch");
        }
    }

    static FallbackChatIdentityDescriptor_ inferFallbackIdentityDescriptorFromText_(
        const std::string& rawPrompt,
        const std::string& answerText)
    {
        FallbackChatIdentityDescriptor_ descriptor;
        const std::string normalizedText =
            normalizeTemporalCueText_(rawPrompt + " " + answerText);
        if (normalizedText.empty()) return descriptor;

        const bool looksLikePerson =
            normalizedText.find("pessoa") != std::string::npos ||
            normalizedText.find("person") != std::string::npos ||
            normalizedText.find("people") != std::string::npos ||
            normalizedText.find("human") != std::string::npos ||
            normalizedText.find("homem") != std::string::npos ||
            normalizedText.find("mulher") != std::string::npos ||
            normalizedText.find("shirt") != std::string::npos ||
            normalizedText.find("camisa") != std::string::npos;
        const bool looksLikeVehicle =
            normalizedText.find("vehicle") != std::string::npos ||
            normalizedText.find("veiculo") != std::string::npos ||
            normalizedText.find("carro") != std::string::npos ||
            normalizedText.find("car ") != std::string::npos ||
            normalizedText.rfind("car", 0) == 0;
        const bool looksLikeAnimal =
            normalizedText.find("animal") != std::string::npos ||
            normalizedText.find("dog") != std::string::npos ||
            normalizedText.find("cachorro") != std::string::npos ||
            normalizedText.find("cat") != std::string::npos ||
            normalizedText.find("gato") != std::string::npos;

        if (looksLikePerson) descriptor.entityType = "person";
        else if (looksLikeVehicle) descriptor.entityType = "vehicle";
        else if (looksLikeAnimal) descriptor.entityType = "animal";
        else descriptor.entityType = "object";

        const std::string colorCue = detectColorCueForIdentityText_(normalizedText);
        if (descriptor.entityType == "person") {
            const std::string traitCue = detectPersonTraitCueForIdentityText_(normalizedText);
            if (!colorCue.empty() && !traitCue.empty()) {
                descriptor.entityHint = temporal::sanitizeToken(
                    "person_" + colorCue + "_" + traitCue,
                    "person");
            }
            else if (!traitCue.empty()) {
                descriptor.entityHint = temporal::sanitizeToken(
                    "person_" + traitCue,
                    "person");
            }
            else if (!colorCue.empty()) {
                descriptor.entityHint = temporal::sanitizeToken(
                    "person_" + colorCue,
                    "person");
            }
            else {
                descriptor.entityHint = "person";
            }
        }
        else if (descriptor.entityType == "vehicle") {
            descriptor.entityHint = colorCue.empty()
                ? std::string("vehicle")
                : temporal::sanitizeToken("vehicle_" + colorCue, "vehicle");
        }
        else if (descriptor.entityType == "animal") {
            descriptor.entityHint = "animal";
        }
        else {
            const std::string objectCue = detectSpecificObjectCueForIdentityText_(normalizedText);
            if (!objectCue.empty() && !colorCue.empty()) {
                descriptor.entityHint = temporal::sanitizeToken(objectCue + "_" + colorCue, objectCue);
            }
            else if (!objectCue.empty()) {
                descriptor.entityHint = temporal::sanitizeToken(objectCue, "object");
            }
            else {
                descriptor.entityHint = colorCue.empty()
                    ? std::string("object")
                    : temporal::sanitizeToken("object_" + colorCue, "object");
            }
        }

        return descriptor;
    }

    static FallbackChatIdentityDescriptor_ deriveFallbackChatIdentityDescriptor_(
        const std::string& rawPrompt,
        const std::string& basePrompt,
        const std::string& temporalStaticJson,
        const std::string& temporalRuntimeJson,
        const std::string& answerText)
    {
        FallbackChatIdentityDescriptor_ descriptor;
        const std::string focusText =
            buildFallbackIdentityFocusText_(rawPrompt, basePrompt, answerText);

        const nlohmann::json directIdentityPromptJson =
            extractJsonObjectAfterMarkerFromPrompt_(
                rawPrompt,
                "DIRECT_CHAT_IDENTITY_MEMORY_JSON:");
        if (directIdentityPromptJson.is_object() &&
            directIdentityPromptJson.contains("identity_memory"))
        {
            applyIdentityDescriptorFromMemoryRows_(
                directIdentityPromptJson["identity_memory"],
                focusText,
                descriptor);
        }

        const nlohmann::json staticPromptJson =
            nlohmann::json::parse(temporalStaticJson, nullptr, false);
        if (staticPromptJson.is_object()) {
            const nlohmann::json entitiesContract =
                staticPromptJson.contains("entities_contract") && staticPromptJson["entities_contract"].is_array()
                    ? staticPromptJson["entities_contract"]
                    : (staticPromptJson.contains("entities") && staticPromptJson["entities"].is_array()
                        ? staticPromptJson["entities"]
                        : nlohmann::json::array());
            for (const auto& item : entitiesContract) {
                if (!item.is_object()) continue;
                const bool trackIdentity = item.value("track_identity", false);
                const std::string entityKey = trimAscii(item.value("entity_key", std::string()));
                const std::string entityType = trimAscii(item.value("entity_type", item.value("type", std::string())));
                if (descriptor.entityHint.empty() && !entityKey.empty() && trackIdentity) {
                    descriptor.entityHint = entityKey;
                }
                if (descriptor.entityType.empty() && !entityType.empty() && trackIdentity) {
                    descriptor.entityType = entityType;
                }
                if (!descriptor.entityHint.empty() && !descriptor.entityType.empty()) break;
            }
        }

        const nlohmann::json runtimePromptJson =
            nlohmann::json::parse(temporalRuntimeJson, nullptr, false);
        if (runtimePromptJson.is_object() &&
            runtimePromptJson.contains("identity_memory"))
        {
            applyIdentityDescriptorFromMemoryRows_(
                runtimePromptJson["identity_memory"],
                focusText,
                descriptor);
        }

        if (descriptor.entityHint.empty() || descriptor.entityType.empty()) {
            const FallbackChatIdentityDescriptor_ inferred =
                inferFallbackIdentityDescriptorFromText_(
                    focusText,
                    std::string());
            if (descriptor.entityHint.empty()) descriptor.entityHint = inferred.entityHint;
            if (descriptor.entityType.empty()) descriptor.entityType = inferred.entityType;
        }

        descriptor.entityHint = temporal::sanitizeToken(
            descriptor.entityHint.empty() ? descriptor.entityType : descriptor.entityHint,
            "entity");
        descriptor.entityType = normalizeFallbackEntityType_(descriptor.entityType);
        return descriptor;
    }

    static void appendFallbackDetectionTimeForChatHit_(
        VideoHit& hit,
        const PromptVideoFrame& representativeFrame)
    {
        if (!hit.detectionTimeInVideo.empty()) return;
        std::string fallbackTime = trimAscii(representativeFrame.frameTimestampInSegment);
        if (fallbackTime.empty()) return;
        if (!addOneSecondToMMSS(fallbackTime)) return;
        hit.detectionTimeInVideo.push_back(std::move(fallbackTime));
    }

    static void ensureFallbackIdentityPortraitCandidatesForChatHit_(
        VideoHit& hit,
        const std::string& rawPrompt,
        const std::string& basePrompt,
        const std::string& temporalStaticJson,
        const std::string& temporalRuntimeJson,
        const std::vector<PromptVideoFrame>* frameCatalog,
        const std::string& videoPackagingMode,
        const std::string& logStreamId = std::string(),
        const std::string& scopeTag = std::string())
    {
        const bool positiveAnswerFallback = answerSupportsPositiveChatIdentityFallback_(hit.answer);
        if (!hit.hasMatch && !positiveAnswerFallback) return;

        const bool hasExistingPortraitCandidates =
            hit.identityPortraitCandidates.is_array() && !hit.identityPortraitCandidates.empty();
        if (!hasExistingPortraitCandidates && (frameCatalog == nullptr || frameCatalog->empty())) return;

        const PromptVideoFrame* representativeFrame =
            (frameCatalog != nullptr && !frameCatalog->empty())
                ? selectRepresentativePromptVideoFrameForHit_(hit, frameCatalog, videoPackagingMode)
                : nullptr;
        const std::string focusText =
            buildFallbackIdentityFocusText_(rawPrompt, basePrompt, hit.answer);
        const FallbackChatIdentityDescriptor_ descriptor =
            deriveFallbackChatIdentityDescriptor_(
                rawPrompt,
                basePrompt,
                temporalStaticJson,
                temporalRuntimeJson,
                hit.answer);

        if (positiveAnswerFallback && representativeFrame != nullptr) {
            appendFallbackDetectionTimeForChatHit_(hit, *representativeFrame);
        }

        auto enrichPortraitCandidate = [&](nlohmann::json& candidate) {
            if (!candidate.is_object()) return;

            const auto missingStringField = [&](const char* key) {
                return !candidate.contains(key) ||
                    !candidate[key].is_string() ||
                    trimAscii(candidate[key].get<std::string>()).empty();
            };

            if (!descriptor.entityId.empty() && missingStringField("candidate_entity_id")) {
                candidate["candidate_entity_id"] = descriptor.entityId;
            }
            if (!descriptor.entityHint.empty() && missingStringField("candidate_entity_hint")) {
                candidate["candidate_entity_hint"] = descriptor.entityHint;
            }
            if (!descriptor.entityHint.empty() && missingStringField("entity_key")) {
                candidate["entity_key"] = descriptor.entityHint;
            }
            if (!descriptor.entityType.empty() && missingStringField("entity_type")) {
                candidate["entity_type"] = descriptor.entityType;
            }
            if (!trimAscii(hit.answer).empty() && missingStringField("description")) {
                candidate["description"] = trimAscii(hit.answer);
            }

            if (representativeFrame != nullptr) {
                if (representativeFrame->frameIndex >= 0 && !candidate.contains("frame_index")) {
                    candidate["frame_index"] = representativeFrame->frameIndex;
                }
                if (!representativeFrame->frameTimestampInSegment.empty() &&
                    missingStringField("frame_timestamp_in_segment"))
                {
                    candidate["frame_timestamp_in_segment"] = representativeFrame->frameTimestampInSegment;
                }
                if (!representativeFrame->timestampName.empty() &&
                    missingStringField("timestamp_name"))
                {
                    candidate["timestamp_name"] = representativeFrame->timestampName;
                }
                if (representativeFrame->hasAbsoluteTimestamp && missingStringField("timestamp_utc_iso")) {
                    candidate["timestamp_utc_iso"] =
                        formatTimePointToIsoUtcZ_(representativeFrame->absoluteTimestamp);
                }
            }

            if (missingStringField("last_seen_ts_utc") &&
                candidate.contains("timestamp_utc_iso") &&
                candidate["timestamp_utc_iso"].is_string())
            {
                const std::string timestampUtcIso =
                    trimAscii(candidate["timestamp_utc_iso"].get<std::string>());
                if (!timestampUtcIso.empty()) {
                    candidate["last_seen_ts_utc"] = timestampUtcIso;
                }
            }

            nlohmann::json signatureTraits =
                candidate.contains("identity_signature_traits")
                    ? candidate["identity_signature_traits"]
                    : nlohmann::json::array();
            nlohmann::json featureCandidates =
                candidate.contains("identity_feature_candidates")
                    ? candidate["identity_feature_candidates"]
                    : nlohmann::json::array();
            buildFallbackIdentityAttributesFromText_(
                focusText,
                descriptor.entityType.empty()
                    ? candidate.value("entity_type", std::string())
                    : descriptor.entityType,
                signatureTraits,
                featureCandidates);
            if (signatureTraits.is_array() && !signatureTraits.empty()) {
                candidate["identity_signature_traits"] = signatureTraits;
            }
            if (featureCandidates.is_array() && !featureCandidates.empty()) {
                candidate["identity_feature_candidates"] = featureCandidates;
            }
        };

        if (hasExistingPortraitCandidates) {
            for (auto& portraitCandidate : hit.identityPortraitCandidates) {
                enrichPortraitCandidate(portraitCandidate);
            }
            return;
        }

        if (!logStreamId.empty() && !scopeTag.empty()) {
            Logger::instance().logDebug(
                logStreamId,
                scopeTag +
                    ": no explicit LLM portrait bbox available; synthetic portrait fallback disabled" +
                    " entity_hint=" + descriptor.entityHint +
                    " entity_type=" + normalizeFallbackEntityType_(descriptor.entityType));
        }
    }

    static bool parseStartConditionStepIdField(
        const nlohmann::json& scid,
        int& outStepId);

    static bool structuredVisionNodeUsesTemporalDeltaContract_(const nlohmann::json& node)
    {
        if (!node.is_object()) return false;
        return node.contains("local_alert_update") ||
            node.contains("start_condition_update") ||
            node.contains("identity_updates") ||
            node.contains("visibility_updates") ||
            node.contains("event_updates") ||
            node.contains("watchlist_updates");
    }

    static bool temporalDeltaVisibilityStateSuggestsPositive_(const std::string& rawState)
    {
        const std::string state = temporal::normalizeEvidenceToken(rawState);
        return state.empty() ||
            state == "visible" ||
            state == "present" ||
            state == "currently_visible" ||
            state == "visible_this_batch" ||
            state == "visible_this_segment" ||
            state == "visible_in_segment" ||
            state == "entity_visible" ||
            state == "target_visible" ||
            state == "person_visible" ||
            state == "in_view" ||
            state == "on_screen";
    }

    static bool temporalDeltaVisibilityStateSuggestsUncertain_(const std::string& rawState)
    {
        const std::string state = temporal::normalizeEvidenceToken(rawState);
        return state == "uncertain" ||
            state == "uncertain_visibility" ||
            state == "ambiguous" ||
            state == "ambiguous_visibility" ||
            state == "unclear" ||
            state == "occluded" ||
            state == "partially_occluded" ||
            state == "partial_occlusion" ||
            state == "blocked" ||
            state == "low_confidence";
    }

    static nlohmann::json buildStructuredVisionCompatNodeFromTemporalDelta_(
        const nlohmann::json& node)
    {
        if (!node.is_object() || !structuredVisionNodeUsesTemporalDeltaContract_(node)) {
            return node;
        }

        nlohmann::json normalized = node;
        nlohmann::json identityPatch =
            node.contains("identity_patch") && node["identity_patch"].is_array()
                ? node["identity_patch"]
                : nlohmann::json::array();
        nlohmann::json observations =
            node.contains("observations") && node["observations"].is_array()
                ? node["observations"]
                : nlohmann::json::array();
        nlohmann::json unknownReasons = nlohmann::json::array();
        nlohmann::json watchlistMatches =
            node.contains("cross_camera_watchlist_matches") &&
            node["cross_camera_watchlist_matches"].is_array()
                ? node["cross_camera_watchlist_matches"]
                : nlohmann::json::array();

        auto appendObject = [](nlohmann::json& target, nlohmann::json item) {
            if (!target.is_array()) target = nlohmann::json::array();
            if (!item.is_object() || item.empty()) return;
            target.push_back(std::move(item));
        };

        auto mergeAlertRegionIds = [&](const nlohmann::json& source) {
            const std::vector<std::string> parsed = parseAlertRegionIdsFromJson_(source);
            if (parsed.empty()) return;

            std::vector<std::string> merged;
            std::unordered_set<std::string> seen;
            for (const auto& value : parseAlertRegionIdsFromJson_(normalized)) {
                const std::string trimmed = trimAscii(value);
                if (trimmed.empty() || !seen.insert(trimmed).second) continue;
                merged.push_back(trimmed);
            }

            for (const auto& value : parsed) {
                const std::string trimmed = trimAscii(value);
                if (trimmed.empty() || !seen.insert(trimmed).second) continue;
                merged.push_back(trimmed);
            }

            if (merged.empty()) {
                normalized.erase("alert_region_ids");
                return;
            }

            normalized["alert_region_ids"] = nlohmann::json::array();
            for (const auto& value : merged) {
                normalized["alert_region_ids"].push_back(value);
            }
        };

        auto copyCommonTemporalFields = [&](const nlohmann::json& source, nlohmann::json& target) {
            if (!source.is_object()) return;

            const std::string entityId =
                readTemporalNodeStringAlias_(source, { "entity_id", "matched_entity_id" });
            if (!entityId.empty()) target["entity_id"] = entityId;

            const std::string entityKey =
                readTemporalNodeStringAlias_(
                    source,
                    { "entity_key", "entity_ref", "entity", "subject", "target_entity", "matched_entity" });
            if (!entityKey.empty()) target["entity_key"] = entityKey;

            const std::string entityType =
                readTemporalNodeStringAlias_(source, { "entity_type", "matched_entity_type" });
            if (!entityType.empty()) target["entity_type"] = entityType;

            const std::string reason =
                readTemporalNodeStringAlias_(
                    source,
                    { "reason", "description", "short_description", "appearance_summary", "note", "reasoning" });
            if (!reason.empty()) {
                if (!target.contains("reason")) target["reason"] = reason;
                if (!target.contains("description")) target["description"] = reason;
            }
            if (source.contains("stable_attributes")) {
                target["stable_attributes"] = source["stable_attributes"];
            }
            if (source.contains("identity_feature_candidates")) {
                target["identity_feature_candidates"] = source["identity_feature_candidates"];
            }
            if (source.contains("identity_signature_traits")) {
                target["identity_signature_traits"] = source["identity_signature_traits"];
            }

            const std::string zone = readTemporalEvidenceZone_(source);
            if (!zone.empty() && !target.contains("zone")) target["zone"] = zone;

            if (source.contains("confidence") && source["confidence"].is_number()) {
                target["confidence"] = source["confidence"];
            }

            if (source.contains("updated_traits")) {
                target["updated_traits"] = source["updated_traits"];
            }
            else if (source.contains("key_traits")) {
                target["updated_traits"] = source["key_traits"];
            }
            if (source.contains("identity_context_traits")) {
                target["identity_context_traits"] = source["identity_context_traits"];
            }
            if (source.contains("scene_brief") && source["scene_brief"].is_string()) {
                target["scene_brief"] = source["scene_brief"];
            }
            if (source.contains("portrait_crop") && source["portrait_crop"].is_object()) {
                target["portrait_crop"] = source["portrait_crop"];
            }
            if (source.contains("context_bbox_norm_in_cell") && source["context_bbox_norm_in_cell"].is_object()) {
                target["context_bbox_norm_in_cell"] = source["context_bbox_norm_in_cell"];
            }
            if (source.contains("context_bbox_norm_in_frame") && source["context_bbox_norm_in_frame"].is_object()) {
                target["context_bbox_norm_in_frame"] = source["context_bbox_norm_in_frame"];
            }
            if (source.contains("reference_image_urls") && source["reference_image_urls"].is_array()) {
                target["reference_image_urls"] = source["reference_image_urls"];
            }

            if (source.contains("frame_ref") && source["frame_ref"].is_object()) {
                target["frame_ref"] = source["frame_ref"];
            }
            else {
                if (source.contains("frame_index")) target["frame_index"] = source["frame_index"];
                if (source.contains("frame_timestamp_in_segment")) {
                    target["frame_timestamp_in_segment"] = source["frame_timestamp_in_segment"];
                }
                if (source.contains("timestamp_name")) target["timestamp_name"] = source["timestamp_name"];
                if (source.contains("time_in_video")) target["time_in_video"] = source["time_in_video"];
            }
        };

        if (node.contains("local_alert_update") && node["local_alert_update"].is_object()) {
            const auto& alertUpdate = node["local_alert_update"];
            if (alertUpdate.contains("alert_condition") && alertUpdate["alert_condition"].is_boolean()) {
                normalized["alert_condition"] = alertUpdate["alert_condition"];
            }
            mergeAlertRegionIds(alertUpdate);

            const std::string alertReason =
                readTemporalNodeStringAlias_(alertUpdate, { "reason", "description", "short_description" });
            const bool alertIsTrue =
                normalized.contains("alert_condition") &&
                normalized["alert_condition"].is_boolean() &&
                normalized["alert_condition"].get<bool>();
            if (alertIsTrue &&
                !alertReason.empty() &&
                (!normalized.contains("answer") ||
                 !normalized["answer"].is_string() ||
                 trimAscii(normalized["answer"].get<std::string>()).empty()))
            {
                normalized["answer"] = alertReason;
            }
        }

        if (node.contains("start_condition_update") && node["start_condition_update"].is_object()) {
            const auto& startUpdate = node["start_condition_update"];
            if (startUpdate.contains("step_id")) {
                int stepId = -1;
                if (parseStartConditionStepIdField(startUpdate["step_id"], stepId)) {
                    normalized["start_condition_step_id"] = stepId;
                }
            }
        }

        if (node.contains("identity_updates") && node["identity_updates"].is_array()) {
            for (const auto& item : node["identity_updates"]) {
                if (!item.is_object()) continue;
                nlohmann::json patch = item;
                copyCommonTemporalFields(item, patch);
                appendObject(identityPatch, std::move(patch));
            }
        }

        if (node.contains("visibility_updates") && node["visibility_updates"].is_array()) {
            for (const auto& item : node["visibility_updates"]) {
                if (item.is_string()) {
                    const std::string reason = trimAscii(item.get<std::string>());
                    if (!reason.empty()) {
                        appendObject(unknownReasons, nlohmann::json{ { "reason", reason } });
                    }
                    continue;
                }
                if (!item.is_object()) continue;

                const std::string rawState =
                    readTemporalNodeStringAlias_(item, { "state", "status", "visibility_state", "visibility" });
                const std::string normalizedState =
                    temporal::normalizeEvidenceToken(rawState.empty() ? "present" : rawState);

                nlohmann::json out = nlohmann::json::object();
                copyCommonTemporalFields(item, out);

                if (temporalDeltaVisibilityStateSuggestsUncertain_(normalizedState)) {
                    if (!normalizedState.empty()) out["state"] = normalizedState;
                    if ((!out.contains("reason") || !out["reason"].is_string()) && !rawState.empty()) {
                        out["reason"] = rawState;
                    }
                    appendObject(unknownReasons, std::move(out));
                    continue;
                }

                if (temporalDeltaVisibilityStateSuggestsPositive_(normalizedState)) {
                    out["type"] = "entity_presence";
                    out["event"] = "present";
                    out["state"] = "visible";
                }
                else {
                    const std::string absenceState =
                        normalizedState.empty() ? std::string("not_visible_this_segment") : normalizedState;
                    out["type"] = "entity_visibility";
                    out["event"] = absenceState;
                    out["state"] = absenceState;
                }
                appendObject(observations, std::move(out));
            }
        }

        if (node.contains("event_updates") && node["event_updates"].is_array()) {
            for (const auto& item : node["event_updates"]) {
                if (item.is_string()) {
                    const std::string eventName = trimAscii(item.get<std::string>());
                    if (!eventName.empty()) {
                        appendObject(observations, nlohmann::json{ { "event", eventName } });
                    }
                    continue;
                }
                if (!item.is_object()) continue;

                nlohmann::json observation = item;
                copyCommonTemporalFields(item, observation);
                const std::string eventName =
                    readTemporalNodeStringAlias_(item, { "event", "event_type", "type" });
                if (!eventName.empty() && !observation.contains("event")) {
                    observation["event"] = eventName;
                }
                appendObject(observations, std::move(observation));
            }
        }

        if (node.contains("unknown_reasons") && node["unknown_reasons"].is_array()) {
            for (const auto& item : node["unknown_reasons"]) {
                if (item.is_string()) {
                    const std::string reason = trimAscii(item.get<std::string>());
                    if (!reason.empty()) {
                        appendObject(unknownReasons, nlohmann::json{ { "reason", reason } });
                    }
                    continue;
                }
                if (!item.is_object()) continue;
                nlohmann::json unknown = item;
                copyCommonTemporalFields(item, unknown);
                appendObject(unknownReasons, std::move(unknown));
            }
        }

        if (node.contains("watchlist_updates") && node["watchlist_updates"].is_array()) {
            for (const auto& item : node["watchlist_updates"]) {
                if (!item.is_object()) continue;
                watchlistMatches.push_back(item);
            }
        }

        if (identityPatch.is_array() && !identityPatch.empty()) normalized["identity_patch"] = identityPatch;
        else normalized.erase("identity_patch");

        if (observations.is_array() && !observations.empty()) normalized["observations"] = observations;
        else normalized.erase("observations");

        if (unknownReasons.is_array() && !unknownReasons.empty()) normalized["unknown_reasons"] = unknownReasons;
        else normalized.erase("unknown_reasons");

        if (watchlistMatches.is_array() && !watchlistMatches.empty()) {
            normalized["cross_camera_watchlist_matches"] = watchlistMatches;
        }
        else {
            normalized.erase("cross_camera_watchlist_matches");
        }

        return normalized;
    }

    static nlohmann::json parseCrossCameraWatchlistMatchesFromJson_(const nlohmann::json& node)
    {
        if (!node.is_object())
        {
            return nlohmann::json::array();
        }

        const nlohmann::json* matchesNode = nullptr;
        if (node.contains("cross_camera_watchlist_matches") &&
            node["cross_camera_watchlist_matches"].is_array())
        {
            matchesNode = &node["cross_camera_watchlist_matches"];
        }
        else if (node.contains("watchlist_updates") && node["watchlist_updates"].is_array()) {
            matchesNode = &node["watchlist_updates"];
        }
        if (matchesNode == nullptr) {
            return nlohmann::json::array();
        }

        nlohmann::json out = nlohmann::json::array();
        for (const auto& item : *matchesNode) {
            if (!item.is_object()) continue;
            nlohmann::json normalized = nlohmann::json::object();
            const std::string huntId =
                item.contains("hunt_id") && item["hunt_id"].is_string()
                    ? trimAscii(item["hunt_id"].get<std::string>())
                    : std::string();
            if (!huntId.empty()) normalized["hunt_id"] = huntId;
            std::string matchedEntityId;
            if (item.contains("matched_entity_id") && item["matched_entity_id"].is_string()) {
                matchedEntityId = trimAscii(item["matched_entity_id"].get<std::string>());
            }
            else if (item.contains("entity_id") && item["entity_id"].is_string()) {
                matchedEntityId = trimAscii(item["entity_id"].get<std::string>());
            }
            if (!matchedEntityId.empty()) normalized["matched_entity_id"] = matchedEntityId;
            if (item.contains("confidence") && item["confidence"].is_number()) {
                normalized["confidence"] = item["confidence"];
            }
            const std::string reason =
                item.contains("reason") && item["reason"].is_string()
                    ? trimAscii(item["reason"].get<std::string>())
                    : std::string();
            if (!reason.empty()) normalized["reason"] = reason;
            if (item.contains("matched_target_name") && item["matched_target_name"].is_string()) {
                normalized["matched_target_name"] = item["matched_target_name"];
            }
            else if (item.contains("target_name") && item["target_name"].is_string()) {
                normalized["matched_target_name"] = item["target_name"];
            }
            if (item.contains("matched_entity_type") && item["matched_entity_type"].is_string()) {
                normalized["matched_entity_type"] = item["matched_entity_type"];
            }
            else if (item.contains("entity_type") && item["entity_type"].is_string()) {
                normalized["matched_entity_type"] = item["entity_type"];
            }
            if (!normalized.empty()) out.push_back(std::move(normalized));
        }
        return out;
    }

    static void parseTemporalFieldsFromJson_(
        const nlohmann::json& node,
        VideoHit& hit)
    {
        temporal::extractOutputTemporalFields(
            node,
            hit.identityPatch,
            hit.observations,
            hit.unknownReasons,
            hit.temporalPayloadPresent
        );
    }

    static void trimJsonArrayToMaxItems_(
        nlohmann::json& node,
        std::size_t maxItems)
    {
        if (!node.is_array() || node.size() <= maxItems) return;
        node.erase(
            node.begin() + static_cast<nlohmann::json::array_t::difference_type>(maxItems),
            node.end());
    }

    template <typename T>
    static void trimVectorToMaxItems_(
        std::vector<T>& values,
        std::size_t maxItems)
    {
        if (values.size() <= maxItems) return;
        values.resize(maxItems);
    }

    static std::vector<std::string> collectSanitizedDetectionTimesInVideoFromJson_(
        const nlohmann::json& node)
    {
        std::vector<std::string> out;
        auto pushTime = [&](std::string value) {
            value = trimAscii(value);
            if (value.empty()) return;
            if (!addOneSecondToMMSS(value)) return;
            if (std::find(out.begin(), out.end(), value) != out.end()) return;
            if (out.size() >= kStructuredVisionMaxDetectionTimesInVideo_) return;
            out.push_back(std::move(value));
        };

        if (!node.contains("detection_time_in_video")) {
            return out;
        }

        const auto& dt = node["detection_time_in_video"];
        if (dt.is_string()) {
            pushTime(dt.get<std::string>());
            return out;
        }
        if (!dt.is_array()) {
            return out;
        }

        for (const auto& item : dt) {
            if (!item.is_string()) continue;
            pushTime(item.get<std::string>());
        }
        return out;
    }

    static void applyStructuredVisionCompatCaps_(VideoHit& hit)
    {
        trimVectorToMaxItems_(hit.alertRegionIds, kStructuredVisionMaxAlertRegionIds_);
        trimVectorToMaxItems_(hit.faceIdTargetNames, kStructuredVisionMaxFaceIdTargetNames_);
        trimJsonArrayToMaxItems_(hit.identityPatch, kStructuredVisionMaxIdentityPatchItems_);
        trimJsonArrayToMaxItems_(hit.observations, kStructuredVisionMaxObservationItems_);
        trimJsonArrayToMaxItems_(hit.unknownReasons, kStructuredVisionMaxUnknownReasonItems_);
        trimJsonArrayToMaxItems_(hit.crossCameraWatchlistMatches, kStructuredVisionMaxCrossCameraMatches_);
        trimVectorToMaxItems_(hit.detectionTimeInVideo, kStructuredVisionMaxDetectionTimesInVideo_);
    }

    static void parseDetectionTimeInVideoFromJson_(
        const nlohmann::json& node,
        VideoHit& hit)
    {
        hit.detectionTimeInVideo = collectSanitizedDetectionTimesInVideoFromJson_(node);
    }

    static void parseStructuredVisionResponseIntoHit_(
        const nlohmann::json& node,
        VideoHit& hit,
        bool includeDetectionTimeInVideo,
        const std::string& logStreamId = std::string(),
        const std::string& scopeTag = std::string())
    {
        if (!node.is_object()) return;

        const nlohmann::json compatNode =
            buildStructuredVisionCompatNodeFromTemporalDelta_(node);

        if (compatNode.contains("answer") && compatNode["answer"].is_string()) {
            hit.answer = compatNode["answer"].get<std::string>();
        }
        if (compatNode.contains("alert_condition") && compatNode["alert_condition"].is_boolean()) {
            hit.alertCondition = compatNode["alert_condition"].get<bool>();
        }

        hit.alertRegionIds = parseAlertRegionIdsFromJson_(compatNode);
        parseTemporalFieldsFromJson_(compatNode, hit);
        logIdentityPatchCheckpoint_(
            logStreamId,
            scopeTag,
            "post_parse_temporal_fields_raw",
            hit.identityPatch);
        normalizeIdentityPatchArrayForMemory_(hit.identityPatch, logStreamId, scopeTag);
        logIdentityPatchCheckpoint_(
            logStreamId,
            scopeTag,
            "post_parse_normalized_for_memory",
            hit.identityPatch);
        hit.crossCameraWatchlistMatches = parseCrossCameraWatchlistMatchesFromJson_(compatNode);

        const std::size_t rawCrossCameraMatchCount =
            compatNode.contains("cross_camera_watchlist_matches") &&
            compatNode["cross_camera_watchlist_matches"].is_array()
                ? compatNode["cross_camera_watchlist_matches"].size()
                : 0;
        const std::size_t parsedCrossCameraMatchCount =
            hit.crossCameraWatchlistMatches.is_array()
                ? hit.crossCameraWatchlistMatches.size()
                : 0;
        if (!logStreamId.empty() &&
            !scopeTag.empty() &&
            (rawCrossCameraMatchCount > 0 || parsedCrossCameraMatchCount > 0))
        {
            Logger::instance().logDebug(
                logStreamId,
                scopeTag + ": parsed cross_camera_watchlist_matches raw_count=" +
                std::to_string(static_cast<unsigned long long>(rawCrossCameraMatchCount)) +
                " parsed_count=" +
                std::to_string(static_cast<unsigned long long>(parsedCrossCameraMatchCount))
            );
        }

        if (compatNode.contains("start_condition_step_id")) {
            int stepId = -1;
            if (parseStartConditionStepIdField(compatNode["start_condition_step_id"], stepId)) {
                hit.startConditionStepId = stepId;
            }
            else if (compatNode["start_condition_step_id"].is_boolean() &&
                     !compatNode["start_condition_step_id"].get<bool>())
            {
                hit.startConditionStepId = -1;
            }
        }

        if (includeDetectionTimeInVideo) {
            parseDetectionTimeInVideoFromJson_(compatNode, hit);
        }
        else {
            hit.detectionTimeInVideo.clear();
        }

        applyStructuredVisionCompatCaps_(hit);
        logIdentityPatchCheckpoint_(
            logStreamId,
            scopeTag,
            "post_parse_compat_caps",
            hit.identityPatch);
    }

    static bool hitHasStructuredMatch_(const VideoHit& hit)
    {
        const bool hasCrossCameraMatches =
            hit.crossCameraWatchlistMatches.is_array() &&
            !hit.crossCameraWatchlistMatches.empty();
        return !hit.detectionTimeInVideo.empty() ||
            hit.alertCondition ||
            (hit.startConditionStepId >= 0) ||
            hit.temporalPayloadPresent ||
            hasCrossCameraMatches;
    }

    static void appendGeminiFaceReferenceParts_(
        nlohmann::json& parts,
        const std::vector<FaceReferenceImage>& references)
    {
        for (const auto& ref : references) {
            const std::string bare = stripDataUrlPrefix(ref.imageDataUrl);
            if (bare.empty()) continue;

            std::ostringstream label;
            label << "USER_REFERENCE_IMAGE";
            if (ref.targetId > 0) {
                label << " TARGET_ID=" << ref.targetId;
            }
            if (!ref.targetName.empty()) {
                label << " TARGET_NAME=" << ref.targetName;
            }

            parts.push_back({ { "text", label.str() } });
            parts.push_back({
                { "inline_data", {
                    { "mime_type", "image/jpeg" },
                    { "data", bare }
                }}
            });
        }
    }

    static void appendOpenAIFaceReferenceContent_(
        nlohmann::json& content,
        const std::vector<FaceReferenceImage>& references,
        const std::string& modelName)
    {
        for (const auto& ref : references) {
            const std::string bare = stripDataUrlPrefix(ref.imageDataUrl);
            if (bare.empty()) continue;

            std::ostringstream label;
            label << "USER_REFERENCE_IMAGE";
            if (ref.targetId > 0) {
                label << " TARGET_ID=" << ref.targetId;
            }
            if (!ref.targetName.empty()) {
                label << " TARGET_NAME=" << ref.targetName;
            }

            content.push_back({ { "type", "text" }, { "text", label.str() } });
            content.push_back(makeOpenAIImageContentFromBareJpeg(bare, modelName));
        }
    }

    static std::vector<NegativeReferenceImage> buildEffectiveNegativeReferences_(
        const std::vector<NegativeReferenceImage>& negativeReferences)
    {
        std::vector<NegativeReferenceImage> out;
        out.reserve(negativeReferences.size());
        for (const auto& ref : negativeReferences) {
            const std::string data = stripDataUrlPrefix(ref.imageDataUrl);
            if (data.empty()) continue;
            NegativeReferenceImage normalized = ref;
            normalized.imageDataUrl = "data:image/jpeg;base64," + data;
            out.push_back(std::move(normalized));
        }
        std::stable_sort(
            out.begin(),
            out.end(),
            [](const NegativeReferenceImage& lhs, const NegativeReferenceImage& rhs) {
                if (lhs.imageId != rhs.imageId) return lhs.imageId < rhs.imageId;
                return lhs.imageDataUrl < rhs.imageDataUrl;
            });
        return out;
    }

    static void appendGeminiNegativeReferenceParts_(
        nlohmann::json& parts,
        const std::vector<NegativeReferenceImage>& references)
    {
        for (const auto& ref : references) {
            const std::string bare = stripDataUrlPrefix(ref.imageDataUrl);
            if (bare.empty()) continue;

            std::ostringstream label;
            label << "NEGATIVE_REFERENCE_IMAGE";
            if (ref.imageId > 0) {
                label << " NEGATIVE_IMAGE_ID=" << ref.imageId;
            }

            parts.push_back({ { "text", label.str() } });
            parts.push_back({
                { "inline_data", {
                    { "mime_type", "image/jpeg" },
                    { "data", bare }
                }}
            });
        }
    }

    static void appendOpenAINegativeReferenceContent_(
        nlohmann::json& content,
        const std::vector<NegativeReferenceImage>& references,
        const std::string& modelName)
    {
        for (const auto& ref : references) {
            const std::string bare = stripDataUrlPrefix(ref.imageDataUrl);
            if (bare.empty()) continue;

            std::ostringstream label;
            label << "NEGATIVE_REFERENCE_IMAGE";
            if (ref.imageId > 0) {
                label << " NEGATIVE_IMAGE_ID=" << ref.imageId;
            }

            content.push_back({ { "type", "text" }, { "text", label.str() } });
            content.push_back(makeOpenAIImageContentFromBareJpeg(bare, modelName));
        }
    }

    static std::string buildOpenAIStaticReferenceLabelText_(
        const std::vector<FaceReferenceImage>& faceReferences,
        const std::vector<NegativeReferenceImage>& negativeReferences)
    {
        std::ostringstream out;
        bool wroteAny = false;

        auto appendLine = [&](const std::string& line) {
            const std::string trimmed = trimAscii(line);
            if (trimmed.empty()) return;
            if (wroteAny) out << "\n";
            out << trimmed;
            wroteAny = true;
        };

        for (const auto& ref : faceReferences) {
            const std::string bare = stripDataUrlPrefix(ref.imageDataUrl);
            if (bare.empty()) continue;
            std::ostringstream label;
            label << "USER_REFERENCE_IMAGE";
            if (ref.targetId > 0) {
                label << " TARGET_ID=" << ref.targetId;
            }
            if (!ref.targetName.empty()) {
                label << " TARGET_NAME=" << ref.targetName;
            }
            appendLine(label.str());
        }

        for (const auto& ref : negativeReferences) {
            const std::string bare = stripDataUrlPrefix(ref.imageDataUrl);
            if (bare.empty()) continue;
            std::ostringstream label;
            label << "NEGATIVE_REFERENCE_IMAGE";
            if (ref.imageId > 0) {
                label << " NEGATIVE_IMAGE_ID=" << ref.imageId;
            }
            appendLine(label.str());
        }

        return out.str();
    }

    static bool usesOpenAIMaxCompletionTokensField_(std::string modelName)
    {
        std::transform(modelName.begin(), modelName.end(), modelName.begin(),
            [](unsigned char c) { return (char)std::tolower(c); });
        return modelName.rfind("gpt-5", 0) == 0;
    }

    static std::string normalizeOpenAIModelName_(std::string modelName)
    {
        const auto first = std::find_if_not(modelName.begin(), modelName.end(),
            [](unsigned char c) { return std::isspace(c) != 0; });
        const auto last = std::find_if_not(modelName.rbegin(), modelName.rend(),
            [](unsigned char c) { return std::isspace(c) != 0; }).base();

        if (first >= last) {
            modelName.clear();
        }
        else {
            modelName.assign(first, last);
        }

        std::transform(modelName.begin(), modelName.end(), modelName.begin(),
            [](unsigned char c) { return (char)std::tolower(c); });
        return modelName;
    }

    static bool isZAiCoreModelName_(const std::string& modelName)
    {
        const std::string normalized = normalizeOpenAIModelName_(modelName);
        return normalized == "glm-4.6v-flash" ||
            normalized.rfind("glm-4.6v-flash-", 0) == 0;
    }

    static bool shouldUseOpenAIResponsesTransportForModel_(const std::string& modelName)
    {
        if (isZAiCoreModelName_(modelName)) {
            return false;
        }
        const std::string normalized = normalizeOpenAIModelName_(modelName);
        return normalized == "gpt-5.1" ||
            normalized.rfind("gpt-5.1-", 0) == 0 ||
            normalized == "gpt-5.4" ||
            normalized.rfind("gpt-5.4-", 0) == 0 ||
            normalized == "gpt-5.4-mini" ||
            normalized.rfind("gpt-5.4-mini-", 0) == 0;
    }

    static bool isGpt5MiniModel_(const std::string& modelName)
    {
        const std::string normalized = normalizeOpenAIModelName_(modelName);
        return (normalized == "gpt-5-mini") || (normalized.rfind("gpt-5-mini-", 0) == 0);
    }

    static bool isGpt5NanoModel_(const std::string& modelName)
    {
        const std::string normalized = normalizeOpenAIModelName_(modelName);
        return (normalized == "gpt-5-nano") || (normalized.rfind("gpt-5-nano-", 0) == 0);
    }

    static int resolveOpenAITokenLimitForModel_(const std::string& modelName, int tokenLimit)
    {
        int effectiveLimit = std::max(1, tokenLimit);
        if (isGpt5NanoModel_(modelName)) {
            effectiveLimit = std::max(effectiveLimit, 4000);
        }
        else if (isGpt5MiniModel_(modelName)) {
            effectiveLimit = std::max(effectiveLimit, 1600);
        }
        return effectiveLimit;
    }

    static void applyOpenAITokenLimitField_(
        nlohmann::json& body,
        const std::string& modelName,
        int tokenLimit)
    {
        const int effectiveTokenLimit = resolveOpenAITokenLimitForModel_(modelName, tokenLimit);
        body.erase("max_tokens");
        body.erase("max_completion_tokens");
        if (usesOpenAIMaxCompletionTokensField_(modelName)) {
            body["max_completion_tokens"] = effectiveTokenLimit;
        }
        else {
            body["max_tokens"] = effectiveTokenLimit;
        }
    }

    static bool usesOpenAIFixedDefaultTemperature_(std::string modelName)
    {
        const auto first = std::find_if_not(modelName.begin(), modelName.end(),
            [](unsigned char c) { return std::isspace(c) != 0; });
        const auto last = std::find_if_not(modelName.rbegin(), modelName.rend(),
            [](unsigned char c) { return std::isspace(c) != 0; }).base();
        if (first >= last) {
            modelName.clear();
        }
        else {
            modelName.assign(first, last);
        }

        return isGpt5MiniModel_(modelName) || isGpt5NanoModel_(modelName);
    }

    static void applyOpenAITemperatureField_(
        nlohmann::json& body,
        const std::string& modelName,
        double fallbackTemperature)
    {
        body["temperature"] = usesOpenAIFixedDefaultTemperature_(modelName)
            ? 1.0
            : fallbackTemperature;
    }

