bool AgentCore::materializeOperationalIdentityCards(
    VideoHit& hit,
    nlohmann::json& temporalState,
    nlohmann::json& visualState,
    const std::string& logStreamId,
    const std::string& scopeTag)
{
    try {
        return forceIdentityCardForPositiveHit_(
            hit,
            temporalState,
            visualState,
            logStreamId,
            scopeTag
        );
    }
    catch (const std::exception& ex) {
        Logger::instance().logDebug(
            logStreamId.empty() ? std::string("agent") : logStreamId,
            "materializeOperationalIdentityCards: exception scope=" + scopeTag +
            " error=" + ex.what()
        );
        return false;
    }
    catch (...) {
        Logger::instance().logDebug(
            logStreamId.empty() ? std::string("agent") : logStreamId,
            "materializeOperationalIdentityCards: unknown exception scope=" + scopeTag
        );
        return false;
    }
}

nlohmann::json AgentCore::collectOperationalIdentityCards(
    const nlohmann::json& temporalState,
    nlohmann::json& visualState)
{
    try {
        return collectAllChatIdentityCards_(temporalState, visualState);
    }
    catch (const std::exception& ex) {
        Logger::instance().logDebug(
            "agent",
            std::string("collectOperationalIdentityCards: exception error=") + ex.what());
    }
    catch (...) {
        Logger::instance().logDebug(
            "agent",
            "collectOperationalIdentityCards: unknown exception");
    }
    return nlohmann::json::array();
}

DrakonFindInferenceResult AgentCore::runDrakonFindImageInference_(
    int cameraId,
    const std::string& jpegBase64,
    const std::string& searchPrompt,
    const std::vector<DrakonFindReferenceImage>& referenceImages,
    const std::string& modelName,
    const std::string& modelApiKey,
    const std::string& snapshotTsUtcIso,
    int& outPromptTokens,
    int& outOutputTokens,
    int& outTotalTokens)
{
    DrakonFindInferenceResult result;
    outPromptTokens = outOutputTokens = outTotalTokens = 0;

    auto trimLocal = [](const std::string& value) {
        const auto first = value.find_first_not_of(" \t\r\n");
        if (first == std::string::npos) return std::string();
        const auto last = value.find_last_not_of(" \t\r\n");
        return value.substr(first, last - first + 1);
    };

    if (jpegBase64.empty()) {
        Logger::instance().logError(
            sourceIdForCamera_(cameraId),
            "empty jpeg base64",
            makeAgentErrorContext_(
                "drakon_find",
                "AgentCore::runDrakonFindImageInference_",
                "validate_input",
                {
                    { "camera_id", cameraId }
                }
            )
        );
        return result;
    }
    if (modelApiKey.empty()) {
        Logger::instance().logError(
            sourceIdForCamera_(cameraId),
            "missing OpenAI api key",
            makeAgentErrorContext_(
                "drakon_find",
                "AgentCore::runDrakonFindImageInference_",
                "validate_input",
                {
                    { "camera_id", cameraId }
                }
            )
        );
        return result;
    }

    const std::string safeModelName =
        trimLocal(modelName).empty() ? std::string("gpt-5.1") : trimLocal(modelName);

    try {
        std::ostringstream prompt;
        prompt << "You are Drakon Find, a CCTV visual search assistant.\n";
        prompt << "You will receive ONE current CCTV snapshot plus zero or more TARGET_REFERENCE_IMAGE samples.\n";
        prompt << "Search brief: \"" << searchPrompt << "\".\n";
        prompt << "Snapshot timestamp (UTC): "
               << (snapshotTsUtcIso.empty() ? "unknown" : snapshotTsUtcIso) << "\n\n";
        prompt << "TASK:\n";
        prompt << "- Decide whether the current snapshot contains the same target described in the brief and reference images.\n";
        prompt << "- Targets may be people, vehicles, animals, objects, or custom visual entities.\n";
        prompt << "- Treat the reference images as generic visual references, not face-only identity references.\n";
        prompt << "- Allow normal changes in viewpoint, lighting, distance, scale, blur, and partial occlusion.\n";
        prompt << "- If evidence is weak, ambiguous, or insufficient, return match=false.\n\n";
        prompt << "OUTPUT RULES:\n";
        prompt << "- Respond in the same language as the search brief.\n";
        prompt << "- Return RAW JSON only. No markdown.\n";
        prompt << "- confidence must be a number between 0 and 1.\n";
        prompt << "- observed_traits should list short visual cues that support your decision.\n\n";
        prompt << "RESPONSE FORMAT:\n";
        prompt << "{\n";
        prompt << "  \"match\": boolean,\n";
        prompt << "  \"confidence\": number,\n";
        prompt << "  \"summary\": string,\n";
        prompt << "  \"observed_traits\": array of strings\n";
        prompt << "}\n";

        nlohmann::json content = nlohmann::json::array();
        content.push_back({ { "type", "text" }, { "text", prompt.str() } });

        int referenceIndex = 0;
        for (const auto& reference : referenceImages) {
            const std::string bare = stripDataUrlPrefix(reference.imageDataUrl);
            if (bare.empty()) continue;
            ++referenceIndex;
            std::ostringstream label;
            label << "TARGET_REFERENCE_IMAGE #" << referenceIndex;
            if (!reference.imageUrl.empty()) {
                label << " (" << reference.imageUrl << ")";
            }
            content.push_back({ { "type", "text" }, { "text", label.str() } });
            content.push_back(makeOpenAIImageContentFromBareJpeg(bare, safeModelName));
        }

        content.push_back({ { "type", "text" }, { "text", "LIVE_CAMERA_SNAPSHOT" } });
        content.push_back(
            makeOpenAIFrameImageContentFromBareJpeg(stripDataUrlPrefix(jpegBase64), safeModelName)
        );

        nlohmann::json body = {
            { "model", safeModelName },
            { "messages", nlohmann::json::array({
                {
                    { "role", "user" },
                    { "content", content }
                }
            })}
        };
        applyOpenAITemperatureField_(body, safeModelName, 0.05);
        applyOpenAITokenLimitField_(body, safeModelName, 900);

        std::string rawResp = postOpenAIChatCompletionsWithCoreLease_(
            modelApiKey,
            body,
            []() { MaybeNotifyFirstRetry(); },
            false,
            {},
            "drakon_find_image"
        );

        nlohmann::json respJson = nlohmann::json::parse(rawResp, nullptr, false);
        if (respJson.is_discarded() || !respJson.is_object()) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindImageInference_: invalid JSON response from OpenAI"
            );
            return result;
        }

        extractOpenAIUsageTokens(respJson, outPromptTokens, outOutputTokens, outTotalTokens);

        std::string text = extractOpenAITextFromResponse(respJson);
        if (text.empty()) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindImageInference_: empty text response from OpenAI"
            );
            return result;
        }

        std::string jsonSlice;
        if (!tryExtractJsonObjectSlice(text, jsonSlice)) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindImageInference_: could not extract JSON object from model text"
            );
            return result;
        }

        nlohmann::json parsed = nlohmann::json::parse(jsonSlice, nullptr, false);
        if (!parsed.is_object()) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindImageInference_: parsed response is not a JSON object"
            );
            return result;
        }

        const double rawConfidence =
            parsed.contains("confidence") && parsed["confidence"].is_number()
                ? parsed["confidence"].get<double>()
                : 0.0;
        result.hasMatch = parsed.value("match", false);
        result.confidence = (std::max)(0.0, (std::min)(1.0, rawConfidence));
        result.summary = trimLocal(parsed.value("summary", std::string()));
        if (result.summary.empty()) {
            result.summary = result.hasMatch
                ? "Match visual identificado na snapshot atual."
                : "Sem match confiavel na snapshot atual.";
        }
        if (parsed.contains("observed_traits") && parsed["observed_traits"].is_array()) {
            result.observedTraits = parsed["observed_traits"];
        }
        result.raw = parsed;
    }
    catch (const std::exception& e) {
        logAgentException_(
            sourceIdForCamera_(cameraId),
            "drakon_find",
            "AgentCore::runDrakonFindImageInference_",
            "infer_snapshot",
            {
                { "camera_id", cameraId },
                { "snapshot_ts_utc_iso", snapshotTsUtcIso }
            },
            e
        );
    }
    catch (...) {
        logAgentUnknownException_(
            sourceIdForCamera_(cameraId),
            "drakon_find",
            "AgentCore::runDrakonFindImageInference_",
            "infer_snapshot",
            {
                { "camera_id", cameraId },
                { "snapshot_ts_utc_iso", snapshotTsUtcIso }
            }
        );
    }

    return result;
}

DrakonFindInferenceResult AgentCore::runDrakonFindVideoInference_(
    const EncodedVideoSegment& segment,
    const std::string& searchPrompt,
    const std::vector<DrakonFindReferenceImage>& referenceImages,
    const std::string& modelName,
    const std::string& modelApiKey,
    int modelInputFps,
    int expectedWindowSeconds,
    int& outPromptTokens,
    int& outOutputTokens,
    int& outTotalTokens)
{
    DrakonFindInferenceResult result;
    outPromptTokens = outOutputTokens = outTotalTokens = 0;

    auto trimLocal = [](const std::string& value) {
        const auto first = value.find_first_not_of(" \t\r\n");
        if (first == std::string::npos) return std::string();
        const auto last = value.find_last_not_of(" \t\r\n");
        return value.substr(first, last - first + 1);
    };

    const std::string safeModelName =
        trimLocal(modelName).empty() ? std::string("gpt-5.1") : trimLocal(modelName);
    const int safeWindow = expectedWindowSeconds <= 0 ? 60 : expectedWindowSeconds;

    if (modelApiKey.empty()) {
        Logger::instance().logError(
            sourceIdForCamera_(segment.cameraId),
            "missing OpenAI api key",
            makeAgentErrorContext_(
                "drakon_find",
                "AgentCore::runDrakonFindVideoInference_",
                "validate_input",
                {
                    { "camera_id", segment.cameraId },
                    { "segment_source_file", segment.sourceFilePath }
                }
            )
        );
        return result;
    }
    if (segment.bytes.empty() && segment.sourceFilePath.empty()) {
        Logger::instance().logError(
            sourceIdForCamera_(segment.cameraId),
            "empty video input",
            makeAgentErrorContext_(
                "drakon_find",
                "AgentCore::runDrakonFindVideoInference_",
                "validate_input",
                {
                    { "camera_id", segment.cameraId }
                }
            )
        );
        return result;
    }

    try {
        std::string videoPath = segment.sourceFilePath;
        struct TempFileGuard {
            std::string path;
            ~TempFileGuard() {
                if (!path.empty()) {
                    std::error_code ec;
                    fs::remove(path, ec);
                }
            }
        } tempGuard;

        if (videoPath.empty() || !fs::exists(videoPath)) {
            if (!writeBytesToTempMp4ForOpenAI(segment.bytes, videoPath)) {
                Logger::instance().logDebug("agent", "runDrakonFindVideoInference_: failed to materialize mp4");
                return result;
            }
            tempGuard.path = videoPath;
        }

        const std::string camLogId = segment.cameraId > 0
            ? std::to_string(segment.cameraId)
            : std::string("agent");
        double analyzedDurationSeconds = 0.0;
        const std::vector<PromptVideoFrame> frames =
            buildOpenAIVideoFrameInputs(
                videoPath,
                kMaxOpenAIVideoFramesPerRequest,
                clampRequestedModelFps_(modelInputFps),
                safeModelName,
                safeWindow,
                640,
                camLogId,
                segment.startTs,
                segment.endTs,
                &analyzedDurationSeconds
            );
        if (frames.empty()) {
            Logger::instance().logDebug("agent", "runDrakonFindVideoInference_: no frames extracted");
            return result;
        }

        std::string segmentStartForPrompt = trimAscii(segment.startTs);
        std::string segmentEndForPrompt = trimAscii(segment.endTs);
        if (segmentStartForPrompt.empty() || segmentEndForPrompt.empty()) {
            std::string derivedStartTs;
            std::string derivedEndTs;
            if (deriveSegmentRangeFromPathForPrompt_(videoPath, derivedStartTs, derivedEndTs)) {
                if (segmentStartForPrompt.empty()) segmentStartForPrompt = derivedStartTs;
                if (segmentEndForPrompt.empty()) segmentEndForPrompt = derivedEndTs;
            }
        }
        if (segmentStartForPrompt.empty()) segmentStartForPrompt = "UNKNOWN_START";
        if (segmentEndForPrompt.empty()) segmentEndForPrompt = "UNKNOWN_END";
        clampSegmentRangeToAnalyzedWindow_(
            segmentStartForPrompt,
            segmentEndForPrompt,
            analyzedDurationSeconds,
            camLogId,
            "runDrakonFindVideoInference_"
        );

        std::ostringstream prompt;
        prompt << "You are Drakon Find, a CCTV visual search assistant.\n";
        prompt << "You will receive ONE CCTV video segment as an ORDERED sequence of frames plus zero or more TARGET_REFERENCE_IMAGE samples.\n";
        prompt << "Search brief: \"" << searchPrompt << "\".\n";
        prompt << "Each frame is preceded by FRAME_META_JSON with frame_index, timestamp_name, and frame_timestamp_in_segment.\n";
        prompt << "This segment covers: " << segmentStartForPrompt << " to " << segmentEndForPrompt << ".\n";
        prompt << "Treat this segment range as the authoritative timeline for this batch.\n";
        prompt << "Frames were sampled at approximately 1 FPS from a 60-second window.\n\n";
        prompt << "TASK:\n";
        prompt << "- Decide whether this segment contains the same target described in the brief and reference images.\n";
        prompt << "- Targets may be people, vehicles, animals, objects, or custom visual entities.\n";
        prompt << "- Treat the reference images as generic visual references, not face-only identity references.\n";
        prompt << "- Allow normal changes in viewpoint, lighting, motion blur, distance, scale, and partial occlusion.\n";
        prompt << "- If evidence is weak, ambiguous, or insufficient, return match=false.\n";
        prompt << "- If the target appears, include one or more approximate MM:SS timestamps inside detection_time_in_video.\n\n";
        prompt << "OUTPUT RULES:\n";
        prompt << "- Respond in the same language as the search brief.\n";
        prompt << "- Return RAW JSON only. No markdown.\n";
        prompt << "- confidence must be a number between 0 and 1.\n";
        prompt << "- observed_traits should list short visual cues that support your decision.\n";
        prompt << "- detection_time_in_video should be an array of MM:SS timestamps when the target is visible.\n\n";
        prompt << "RESPONSE FORMAT:\n";
        prompt << "{\n";
        prompt << "  \"match\": boolean,\n";
        prompt << "  \"confidence\": number,\n";
        prompt << "  \"summary\": string,\n";
        prompt << "  \"observed_traits\": array of strings,\n";
        prompt << "  \"detection_time_in_video\": array of strings\n";
        prompt << "}\n";

        nlohmann::json content = nlohmann::json::array();
        content.push_back({ { "type", "text" }, { "text", prompt.str() } });

        int referenceIndex = 0;
        for (const auto& reference : referenceImages) {
            const std::string bare = stripDataUrlPrefix(reference.imageDataUrl);
            if (bare.empty()) continue;
            ++referenceIndex;
            std::ostringstream label;
            label << "TARGET_REFERENCE_IMAGE #" << referenceIndex;
            if (!reference.imageUrl.empty()) {
                label << " (" << reference.imageUrl << ")";
            }
            content.push_back({ { "type", "text" }, { "text", label.str() } });
            content.push_back(makeOpenAIImageContentFromBareJpeg(bare, safeModelName));
        }

        for (const auto& frame : frames) {
            content.push_back({
                { "type", "text" },
                { "text", buildPromptVideoFrameMetaText_(frame) }
            });
            content.push_back(makeOpenAIFrameImageContentFromBareJpeg(frame.jpegBase64, safeModelName));
        }

        nlohmann::json body = {
            { "model", safeModelName },
            { "messages", nlohmann::json::array({
                {
                    { "role", "user" },
                    { "content", content }
                }
            })}
        };
        applyOpenAITemperatureField_(body, safeModelName, 0.0);
        applyOpenAITokenLimitField_(body, safeModelName, 2200);

        std::string rawResp = postOpenAIChatCompletionsWithCoreLease_(
            modelApiKey,
            body,
            []() { MaybeNotifyFirstRetry(); },
            false,
            {},
            "drakon_find_video",
            camLogId
        );

        nlohmann::json respJson = nlohmann::json::parse(rawResp, nullptr, false);
        if (respJson.is_discarded() || !respJson.is_object()) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindVideoInference_: invalid JSON response from OpenAI"
            );
            return result;
        }

        extractOpenAIUsageTokens(respJson, outPromptTokens, outOutputTokens, outTotalTokens);

        std::string text = extractOpenAITextFromResponse(respJson);
        if (text.empty()) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindVideoInference_: empty text response from OpenAI"
            );
            return result;
        }

        std::string jsonSlice;
        if (!tryExtractJsonObjectSlice(text, jsonSlice)) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindVideoInference_: could not extract JSON object from model text"
            );
            return result;
        }

        nlohmann::json parsed = nlohmann::json::parse(jsonSlice, nullptr, false);
        if (!parsed.is_object()) {
            Logger::instance().logDebug(
                "agent",
                "runDrakonFindVideoInference_: parsed response is not a JSON object"
            );
            return result;
        }

        const double rawConfidence =
            parsed.contains("confidence") && parsed["confidence"].is_number()
                ? parsed["confidence"].get<double>()
                : 0.0;
        result.hasMatch = parsed.value("match", false);
        result.confidence = (std::max)(0.0, (std::min)(1.0, rawConfidence));
        result.summary = trimLocal(parsed.value("summary", std::string()));
        if (result.summary.empty()) {
            result.summary = result.hasMatch
                ? "Match visual identificado na janela de video."
                : "Sem match confiavel na janela de video.";
        }
        if (parsed.contains("observed_traits") && parsed["observed_traits"].is_array()) {
            result.observedTraits = parsed["observed_traits"];
        }
        const std::vector<std::string> sanitizedDetectionTimes =
            collectSanitizedDetectionTimesInVideoFromJson_(parsed);
        if (!sanitizedDetectionTimes.empty()) {
            result.detectionTimeInVideo = sanitizedDetectionTimes;
        }
        result.raw = parsed;
    }
    catch (const std::exception& e) {
        logAgentException_(
            sourceIdForCamera_(segment.cameraId),
            "drakon_find",
            "AgentCore::runDrakonFindVideoInference_",
            "infer_video_window",
            {
                { "camera_id", segment.cameraId },
                { "segment_start_ts", segment.startTs },
                { "segment_end_ts", segment.endTs },
                { "segment_source_file", segment.sourceFilePath }
            },
            e
        );
    }
    catch (...) {
        logAgentUnknownException_(
            sourceIdForCamera_(segment.cameraId),
            "drakon_find",
            "AgentCore::runDrakonFindVideoInference_",
            "infer_video_window",
            {
                { "camera_id", segment.cameraId },
                { "segment_start_ts", segment.startTs },
                { "segment_end_ts", segment.endTs },
                { "segment_source_file", segment.sourceFilePath }
            }
        );
    }

    return result;
}


VideoHit AgentCore::callOpenAIVisionImageJOB_(
    int cameraId,
    const std::string& jpegBase64,
    const std::string& userQuestion,
    const std::vector<FaceReferenceImage>& faceReferences,
    const std::vector<NegativeReferenceImage>& negativeReferences,
    const std::string& alertConditionText,
    const std::string& startConditionText,
    const std::string& openAiModelName,
    const std::string& openAiApiKey,
    const std::string& snapshotTsUtcIso,
    int& outPromptTokens,
    int& outOutputTokens,
    int& outTotalTokens
)
{
    VideoHit hit;
    outPromptTokens = outOutputTokens = outTotalTokens = 0;

    if (jpegBase64.empty()) {
        Logger::instance().logDebug("agent", "callOpenAIVisionImageJOB_: empty jpeg base64");
        return hit;
    }
    if (openAiApiKey.empty()) {
        Logger::instance().logDebug("agent", "callOpenAIVisionImageJOB_: missing OpenAI api key");
        return hit;
    }

    const std::vector<FaceReferenceImage> effectiveFaceReferences =
        buildEffectiveFaceReferences_(faceReferences);
    const bool hasFaceReferences = !effectiveFaceReferences.empty();
    const std::vector<NegativeReferenceImage> effectiveNegativeReferences =
        buildEffectiveNegativeReferences_(negativeReferences);
    const VisionPromptSections_ promptSections = parseVisionPromptSections_(userQuestion);
    const std::vector<std::string> fallbackFaceTargetNames =
        collectTargetNamesFromFaceReferences_(effectiveFaceReferences);

    try {
        const std::string modelName = openAiModelName.empty() ? "gpt-5-mini" : openAiModelName;
        const std::string camLogId = std::to_string(cameraId);
        OpenAIVisionRequestBuild_ requestBuild = buildOpenAIImageRequest_(
            modelName,
            promptSections,
            alertConditionText,
            startConditionText,
            snapshotTsUtcIso,
            jpegBase64,
            effectiveFaceReferences,
            effectiveNegativeReferences
        );
        logOpenAIVisionPromptBuild_(
            camLogId,
            "callOpenAIVisionImageJOB_",
            modelName,
            requestBuild
        );

        nlohmann::json body = requestBuild.body;
        applyOpenAITemperatureField_(body, modelName, 0.0);
        const int baseRequestedLimit = 1200;
        const int firstEffectiveLimit = resolveOpenAITokenLimitForModel_(modelName, baseRequestedLimit);
        const int secondEffectiveLimit = std::min(3000, firstEffectiveLimit + 800);
        const bool useCoreModel = isZAiCoreModelName_(modelName);
        const bool useResponsesTransport = shouldUseOpenAIResponsesTransportForModel_(modelName);

        std::string rawResp;
        OpenAITextObjectResponse_ parsedResponse;

        auto postAndParse = [&](int requestedLimit, int attemptNo) -> bool {
            nlohmann::json reqBody = body;
            applyOpenAITokenLimitField_(reqBody, modelName, requestedLimit);
            const auto coreRequestStart = std::chrono::steady_clock::now();

            try {
                if (useResponsesTransport) {
                    rawResp = postOpenAIResponsesWithCoreLease_(
                        openAiApiKey,
                        reqBody,
                        []() { MaybeNotifyFirstRetry(); },
                        false,
                        {},
                        "background_image_job",
                        camLogId
                    );
                }
                else {
                    rawResp = postOpenAIChatCompletionsWithCoreLease_(
                        openAiApiKey,
                        reqBody,
                        []() { MaybeNotifyFirstRetry(); },
                        false,
                        {},
                        "background_image_job",
                        camLogId
                    );
                }
            }
            catch (const std::exception& e) {
                if (useCoreModel) {
                    const auto latencyMs =
                        std::chrono::duration_cast<std::chrono::milliseconds>(
                            std::chrono::steady_clock::now() - coreRequestStart).count();
                    Logger::instance().logDebug(
                        camLogId,
                        "core_inference_context_latency_ms scope=callOpenAIVisionImageJOB_ status=error model=" +
                        modelName + " camera_id=" + std::to_string(cameraId) +
                        " attempt=" + std::to_string(attemptNo) +
                        " latency_ms=" + std::to_string(latencyMs)
                    );
                }
                Logger::instance().logDebug(
                    camLogId,
                    "callOpenAIVisionImageJOB_: httpPostJsonOpenAI exception (attempt=" +
                    std::to_string(attemptNo) + "): " + e.what());
                emitAgentApiErrorEvent_(
                    this,
                    cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
                    "job_or_camera_image",
                    "http_post",
                    modelName,
                    e.what(),
                    nlohmann::json{
                        { "attempt", attemptNo },
                        { "snapshot_ts_utc_iso", snapshotTsUtcIso }
                    }
                );
                return false;
            }
            if (useCoreModel) {
                const auto latencyMs =
                    std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - coreRequestStart).count();
                Logger::instance().logDebug(
                    camLogId,
                    "core_inference_context_latency_ms scope=callOpenAIVisionImageJOB_ status=success model=" +
                    modelName + " camera_id=" + std::to_string(cameraId) +
                    " attempt=" + std::to_string(attemptNo) +
                    " latency_ms=" + std::to_string(latencyMs)
                );
            }

            parsedResponse = extractOpenAITextObjectResponse_(rawResp);
            Logger::instance().logDebugNoEscalation(
                camLogId,
                buildOpenAIResponseLogBlock_(
                    "callOpenAIVisionImageJOB_: rawResp (attempt=" + std::to_string(attemptNo) + ")",
                    rawResp,
                    parsedResponse)
            );
            if (!parsedResponse.hasValidResponseJson) {
                Logger::instance().logDebug("agent", "callOpenAIVisionImageJOB_: invalid JSON response");
                emitAgentApiErrorEvent_(
                    this,
                    cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
                    "job_or_camera_image",
                    "invalid_json_response",
                    modelName,
                    "OpenAI returned invalid JSON response",
                    nlohmann::json{
                        { "attempt", attemptNo },
                        { "snapshot_ts_utc_iso", snapshotTsUtcIso }
                    }
                );
                return false;
            }

            outPromptTokens += parsedResponse.usageStats.promptTokens;
            outOutputTokens += parsedResponse.usageStats.outputTokens;
            outTotalTokens += parsedResponse.usageStats.totalTokens;
            Logger::instance().logDebug(
                camLogId,
                "callOpenAIVisionImageJOB_: prompt cache usage model=" + modelName +
                " variant=" + requestBuild.cacheVariant +
                " cache_key=" + requestBuild.cacheKey +
                " attempt=" + std::to_string(attemptNo) +
                " input_tokens=" + std::to_string(parsedResponse.usageStats.promptTokens) +
                " prompt_tokens=" + std::to_string(parsedResponse.usageStats.promptTokens) +
                " cached_input_tokens=" + std::to_string(parsedResponse.usageStats.cachedPromptTokens) +
                " cached_prompt_tokens=" + std::to_string(parsedResponse.usageStats.cachedPromptTokens) +
                " uncached_input_tokens=" +
                    std::to_string((std::max)(
                        0,
                        parsedResponse.usageStats.promptTokens - parsedResponse.usageStats.cachedPromptTokens)) +
                " uncached_prompt_tokens=" +
                    std::to_string((std::max)(
                        0,
                        parsedResponse.usageStats.promptTokens - parsedResponse.usageStats.cachedPromptTokens)) +
                " output_tokens=" + std::to_string(parsedResponse.usageStats.outputTokens)
            );
            return true;
            };

        if (!postAndParse(firstEffectiveLimit, 1)) {
            return hit;
        }

        if (shouldRetryOpenAITextObjectResponseForLength_(parsedResponse) &&
            secondEffectiveLimit > firstEffectiveLimit)
        {
            Logger::instance().logDebug(
                camLogId,
                "callOpenAIVisionImageJOB_: finish_reason=length with incomplete JSON; retrying once with higher token limit " +
                std::to_string(secondEffectiveLimit));

            if (!postAndParse(secondEffectiveLimit, 2)) {
                return hit;
            }
        }

        if (shouldRetryOpenAITextObjectResponseForLength_(parsedResponse)) {
            Logger::instance().logDebug(
                camLogId,
                "callOpenAIVisionImageJOB_: finish_reason=length persisted after retry; giving up for this inference");
            emitAgentApiErrorEvent_(
                this,
                cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
                "job_or_camera_image",
                "finish_reason_length",
                modelName,
                "OpenAI returned finish_reason=length before completing a valid JSON object",
                nlohmann::json{
                    { "snapshot_ts_utc_iso", snapshotTsUtcIso }
                }
            );
            return hit;
        }

        if (parsedResponse.text.empty()) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageJOB_: empty text");
            emitAgentApiErrorEvent_(
                this,
                cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
                "job_or_camera_image",
                "empty_text",
                modelName,
                "OpenAI returned empty text response",
                nlohmann::json{
                    { "snapshot_ts_utc_iso", snapshotTsUtcIso }
                }
            );
            return hit;
        }

        if (!parsedResponse.hasJsonObjectSlice) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageJOB_: no JSON braces");
            emitAgentApiErrorEvent_(
                this,
                cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
                "job_or_camera_image",
                "no_json_object",
                modelName,
                "OpenAI text response did not contain JSON object",
                nlohmann::json{
                    { "snapshot_ts_utc_iso", snapshotTsUtcIso }
                }
            );
            return hit;
        }

        if (!parsedResponse.hasValidJsonObject) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageJOB_: invalid JSON object");
            emitAgentApiErrorEvent_(
                this,
                cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
                "job_or_camera_image",
                "invalid_json_object",
                modelName,
                "OpenAI returned malformed JSON object",
                nlohmann::json{
                    { "snapshot_ts_utc_iso", snapshotTsUtcIso }
                }
            );
            return hit;
        }

        const nlohmann::json& res = parsedResponse.jsonObject;
        parseStructuredVisionResponseIntoHit_(
            res,
            hit,
            /*includeDetectionTimeInVideo*/ false
        );
        normalizeTemporalPayloadForStill_(hit, snapshotTsUtcIso);
        if (res.contains("faceid_match") && res["faceid_match"].is_boolean()) {
            hit.faceIdMatch = res["faceid_match"].get<bool>();
        }
        if (hasFaceReferences) {
            hit.faceIdTargetNames = parseFaceIdTargetNamesFromJson_(res);
            if (hit.faceIdMatch && hit.faceIdTargetNames.empty()) {
                hit.faceIdTargetNames = fallbackFaceTargetNames;
            }
            if (hit.faceIdMatch) {
                hit.faceIdentityMatches = buildFaceIdentityMatchesFromReferences_(
                    effectiveFaceReferences,
                    hit.faceIdTargetNames,
                    "face_target_match"
                );
            }
        }
        if (hit.faceIdMatch) {
            hit.alertCondition = true;
        }
        hit.hasMatch = hitHasStructuredMatch_(hit);
        return hit;
    }
    catch (const std::exception& e) {
        Logger::instance().logDebug("agent",
            std::string("callOpenAIVisionImageJOB_: UNHANDLED exception: ") + e.what());
        emitAgentApiErrorEvent_(
            this,
            cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
            "job_or_camera_image",
            "unhandled_exception",
            openAiModelName.empty() ? "gpt-5-mini" : openAiModelName,
            e.what(),
            nlohmann::json{
                { "snapshot_ts_utc_iso", snapshotTsUtcIso }
            }
        );
        return hit;
    }
    catch (...) {
        Logger::instance().logDebug("agent",
            "callOpenAIVisionImageJOB_: UNHANDLED unknown exception");
        emitAgentApiErrorEvent_(
            this,
            cameraId > 0 ? std::optional<int>(cameraId) : std::nullopt,
            "job_or_camera_image",
            "unhandled_exception",
            openAiModelName.empty() ? "gpt-5-mini" : openAiModelName,
            "Unhandled unknown exception while calling OpenAI",
            nlohmann::json{
                { "snapshot_ts_utc_iso", snapshotTsUtcIso }
            }
        );
        return hit;
    }
}




VideoHit AgentCore::callOpenAIVisionImageGroupJOB_(
    const std::vector<GroupImageInput>& inputs,
    const std::string& groupPrompt,
    const std::vector<FaceReferenceImage>& faceReferences,
    const std::vector<NegativeReferenceImage>& negativeReferences,
    const std::string& alertConditionText,
    const std::string& startConditionText,
    const std::string& openAiModelName,
    const std::string& openAiApiKey,
    int& outPromptTokens,
    int& outOutputTokens,
    int& outTotalTokens
)
{
    VideoHit hit;
    outPromptTokens = outOutputTokens = outTotalTokens = 0;

    if (inputs.empty()) {
        Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: empty inputs");
        return hit;
    }
    if (openAiApiKey.empty()) {
        Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: missing OpenAI api key");
        return hit;
    }

    const std::vector<FaceReferenceImage> effectiveFaceReferences =
        buildEffectiveFaceReferences_(faceReferences);
    const bool hasFaceReferences = !effectiveFaceReferences.empty();
    const std::vector<NegativeReferenceImage> effectiveNegativeReferences =
        buildEffectiveNegativeReferences_(negativeReferences);
    const bool hasNegativeReferences = !effectiveNegativeReferences.empty();
    const std::vector<std::string> fallbackFaceTargetNames =
        collectTargetNamesFromFaceReferences_(effectiveFaceReferences);
    const VisionPromptSections_ promptSections = parseVisionPromptSections_(groupPrompt);

    try {
        const std::string modelName = openAiModelName.empty() ? "gpt-5-mini" : openAiModelName;
        int validCount = 0;

        for (const auto& in : inputs) {
            if (in.jpegBase64.empty()) continue;
            validCount++;
        }

        if (validCount == 0) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: no valid jpeg inputs");
            return hit;
        }
        const std::string inputSourceSummary = buildGroupInputSourceSummary_(inputs);
        OpenAIVisionRequestBuild_ requestBuild = buildOpenAIGroupImageRequest_(
            modelName,
            promptSections,
            inputs,
            effectiveFaceReferences,
            effectiveNegativeReferences,
            alertConditionText,
            startConditionText
        );
        auto attachInputSourcesToPromptLog = [&](const std::string& message) {
            const std::string suffix = " input_sources=" + inputSourceSummary;
            const std::size_t newlinePos = message.find('\n');
            if (newlinePos == std::string::npos) {
                return message + suffix;
            }
            return message.substr(0, newlinePos) + suffix + message.substr(newlinePos);
        };
        for (const std::string& message :
             buildOpenAIVisionPromptLogMessages_(
                 "callOpenAIVisionImageGroupJOB_",
                 modelName,
                 requestBuild))
        {
            logGroupCameraDebug_(
                inputs,
                attachInputSourcesToPromptLog(message),
                /*forceCameraStream*/ true
            );
        }

        nlohmann::json body = requestBuild.body;
        applyOpenAITemperatureField_(body, modelName, 0.0);
        applyOpenAITokenLimitField_(body, modelName, 4000);
        const bool useCoreModel = isZAiCoreModelName_(modelName);
        const bool useResponsesTransport = shouldUseOpenAIResponsesTransportForModel_(modelName);
        const auto coreRequestStart = std::chrono::steady_clock::now();

        std::string rawResp;
        try {
            if (useResponsesTransport) {
                rawResp = postOpenAIResponsesWithCoreLease_(
                    openAiApiKey,
                    body,
                    []() { MaybeNotifyFirstRetry(); },
                    false,
                    {},
                    "background_image_group_job"
                );
            }
            else {
                rawResp = postOpenAIChatCompletionsWithCoreLease_(
                    openAiApiKey,
                    body,
                    []() { MaybeNotifyFirstRetry(); },
                    false,
                    {},
                    "background_image_group_job"
                );
            }
        }
        catch (const std::exception& e) {
            if (useCoreModel) {
                const auto latencyMs =
                    std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - coreRequestStart).count();
                logGroupCameraDebug_(
                    inputs,
                    "core_inference_context_latency_ms scope=callOpenAIVisionImageGroupJOB_ status=error model=" +
                    modelName + " latency_ms=" + std::to_string(latencyMs) +
                    " input_sources=" + inputSourceSummary,
                    /*forceCameraStream*/ true
                );
            }
            logGroupCameraDebug_(
                inputs,
                std::string("callOpenAIVisionImageGroupJOB_: httpPostJsonOpenAI exception: ") + e.what() +
                " (input_sources=" + inputSourceSummary + ")",
                /*forceCameraStream*/ true
            );
            nlohmann::json extra = nlohmann::json::object();
            extra["input_sources"] = inputSourceSummary;
            extra["input_count"] = static_cast<int>(inputs.size());
            nlohmann::json cameraIds = nlohmann::json::array();
            for (const auto& in : inputs) {
                if (in.cameraId > 0) cameraIds.push_back(in.cameraId);
            }
            if (!cameraIds.empty()) {
                extra["camera_ids"] = cameraIds;
            }
            emitAgentApiErrorEvent_(
                this,
                std::nullopt,
                "job_group_image",
                "http_post",
                modelName,
                e.what(),
                extra
            );
            return hit;
        }
        if (useCoreModel) {
            const auto latencyMs =
                std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - coreRequestStart).count();
            logGroupCameraDebug_(
                inputs,
                "core_inference_context_latency_ms scope=callOpenAIVisionImageGroupJOB_ status=success model=" +
                modelName + " latency_ms=" + std::to_string(latencyMs) +
                " input_sources=" + inputSourceSummary,
                /*forceCameraStream*/ true
            );
        }

        nlohmann::json respJson = nlohmann::json::parse(rawResp, nullptr, false);
        const OpenAITextObjectResponse_ parsedGroupResponse =
            extractOpenAITextObjectResponse_(rawResp);
        logGroupCameraDebug_(
            inputs,
            buildOpenAIResponseLogBlock_(
                "callOpenAIVisionImageGroupJOB_: rawResp (input_sources=" + inputSourceSummary + ")",
                rawResp,
                parsedGroupResponse),
            /*forceCameraStream*/ true
        );
        if (respJson.is_discarded() || !respJson.is_object()) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: invalid JSON response");
            emitAgentApiErrorEvent_(
                this,
                std::nullopt,
                "job_group_image",
                "invalid_json_response",
                modelName,
                "OpenAI returned invalid JSON response",
                nlohmann::json{
                    { "input_sources", inputSourceSummary },
                    { "input_count", static_cast<int>(inputs.size()) }
                }
            );
            return hit;
        }

        const OpenAIUsageStats_ usageStats = extractOpenAIUsageStats_(respJson);
        outPromptTokens = usageStats.promptTokens;
        outOutputTokens = usageStats.outputTokens;
        outTotalTokens = usageStats.totalTokens;
        logGroupCameraDebug_(
            inputs,
            "callOpenAIVisionImageGroupJOB_: prompt cache usage model=" + modelName +
            " variant=" + requestBuild.cacheVariant +
            " cache_key=" + requestBuild.cacheKey +
            " input_tokens=" + std::to_string(usageStats.promptTokens) +
            " prompt_tokens=" + std::to_string(usageStats.promptTokens) +
            " cached_input_tokens=" + std::to_string(usageStats.cachedPromptTokens) +
            " cached_prompt_tokens=" + std::to_string(usageStats.cachedPromptTokens) +
            " uncached_input_tokens=" +
                std::to_string((std::max)(0, usageStats.promptTokens - usageStats.cachedPromptTokens)) +
            " uncached_prompt_tokens=" +
                std::to_string((std::max)(0, usageStats.promptTokens - usageStats.cachedPromptTokens)) +
            " output_tokens=" + std::to_string(usageStats.outputTokens) +
            " input_sources=" + inputSourceSummary,
            /*forceCameraStream*/ true
        );

        std::string text = extractOpenAITextFromResponse(respJson);
        if (text.empty()) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: empty text");
            emitAgentApiErrorEvent_(
                this,
                std::nullopt,
                "job_group_image",
                "empty_text",
                modelName,
                "OpenAI returned empty text response",
                nlohmann::json{
                    { "input_sources", inputSourceSummary },
                    { "input_count", static_cast<int>(inputs.size()) }
                }
            );
            return hit;
        }

        std::string jsonSlice;
        if (!tryExtractJsonObjectSlice(text, jsonSlice)) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: no JSON braces");
            emitAgentApiErrorEvent_(
                this,
                std::nullopt,
                "job_group_image",
                "no_json_object",
                modelName,
                "OpenAI text response did not contain JSON object",
                nlohmann::json{
                    { "input_sources", inputSourceSummary },
                    { "input_count", static_cast<int>(inputs.size()) }
                }
            );
            return hit;
        }

        nlohmann::json res = nlohmann::json::parse(jsonSlice, nullptr, false);
        if (!res.is_object()) {
            Logger::instance().logDebug("agent", "callOpenAIVisionImageGroupJOB_: invalid JSON object");
            emitAgentApiErrorEvent_(
                this,
                std::nullopt,
                "job_group_image",
                "invalid_json_object",
                modelName,
                "OpenAI returned malformed JSON object",
                nlohmann::json{
                    { "input_sources", inputSourceSummary },
                    { "input_count", static_cast<int>(inputs.size()) }
                }
            );
            return hit;
        }

        if (hasFaceReferences && res.contains("results") && res["results"].is_array()) {
            nlohmann::json rebuiltAlertCameraIds = nlohmann::json::array();
            for (auto& item : res["results"]) {
                if (!item.is_object()) continue;
                const bool faceMatch =
                    item.contains("faceid_match") && item["faceid_match"].is_boolean() &&
                    item["faceid_match"].get<bool>();
                const std::vector<std::string> parsedNames = parseFaceIdTargetNamesFromJson_(item);
                if (!parsedNames.empty()) {
                    item["faceid_target_names"] = parsedNames;
                }
                else if (faceMatch && !fallbackFaceTargetNames.empty()) {
                    item["faceid_target_names"] = fallbackFaceTargetNames;
                }
                if (faceMatch) {
                    item["alert_condition"] = true;
                }
                if (item.contains("alert_condition") && item["alert_condition"].is_boolean() &&
                    item["alert_condition"].get<bool>() &&
                    item.contains("camera_id") && item["camera_id"].is_number_integer())
                {
                    rebuiltAlertCameraIds.push_back(item["camera_id"]);
                }
            }
            res["alert_camera_ids"] = rebuiltAlertCameraIds;
        }

        hit.hasMatch = true;
        hit.answer = res.dump();
        return hit;
    }
    catch (const std::exception& e) {
        Logger::instance().logDebug("agent",
            std::string("callOpenAIVisionImageGroupJOB_: UNHANDLED exception: ") + e.what());
        emitAgentApiErrorEvent_(
            this,
            std::nullopt,
            "job_group_image",
            "unhandled_exception",
            openAiModelName.empty() ? "gpt-5-mini" : openAiModelName,
            e.what(),
            nlohmann::json{
                { "input_count", static_cast<int>(inputs.size()) }
            }
        );
        return hit;
    }
    catch (...) {
        Logger::instance().logDebug("agent",
            "callOpenAIVisionImageGroupJOB_: UNHANDLED unknown exception");
        emitAgentApiErrorEvent_(
            this,
            std::nullopt,
            "job_group_image",
            "unhandled_exception",
            openAiModelName.empty() ? "gpt-5-mini" : openAiModelName,
            "Unhandled unknown exception while calling OpenAI",
            nlohmann::json{
                { "input_count", static_cast<int>(inputs.size()) }
            }
        );
        return hit;
    }
}




void AgentCore::postCommandResult_(
    int commandId,
    const std::string& status,
    const nlohmann::json& resultPayload)
{
    if (commandId <= 0) return;

    try {
        nlohmann::json body;
        body["status"] = status;
        body["result"] = resultPayload.is_null() ? nlohmann::json::object() : resultPayload;

        if (status == "failed") {
            if (resultPayload.is_object() &&
                resultPayload.contains("error") &&
                resultPayload["error"].is_string())
            {
                body["error"] = resultPayload["error"].get<std::string>();
            }
            else {
                body["error"] = "command failed";
            }
        }

        const std::string url = baseUrl_ +
            "/api/agent/commands/" + std::to_string(commandId) +
            "/result?client_id=" + clientId_;

        std::string response;
        const long code = HttpPostJson(url, exeToken_, body.dump(), response);

        Logger::instance().logDebug(
            "agent",
            "postCommandResult_: commandId=" + std::to_string(commandId) +
            " status=" + status +
            " httpCode=" + std::to_string(code) +
            " response=" + response
        );
    }
    catch (const std::exception& e) {
        Logger::instance().logDebug(
            "agent",
            std::string("postCommandResult_ exception: ") + e.what()
        );
    }
    catch (...) {
        Logger::instance().logDebug("agent", "postCommandResult_ unknown exception");
    }
}

void AgentCore::handleProbeWebcamsCommand_(int commandId, const nlohmann::json& payload)
{
    if (commandId <= 0) {
        return;
    }

    try {
        std::vector<int> indices;
        if (payload.is_object() && payload.contains("indices") && payload["indices"].is_array()) {
            for (const auto& item : payload["indices"]) {
                if (!item.is_number_integer()) continue;
                const int webcamIndex = item.get<int>();
                if (webcamIndex < 0 || webcamIndex > 5) continue;
                if (std::find(indices.begin(), indices.end(), webcamIndex) == indices.end()) {
                    indices.push_back(webcamIndex);
                }
            }
        }

        if (indices.empty()) {
            indices = { 0, 1, 2, 3, 4, 5 };
        }

        nlohmann::json result;
        result["attempted_indices"] = nlohmann::json::array();
        result["responding_indices"] = nlohmann::json::array();
        result["preferred_index"] = nullptr;
        result["has_responsive_webcam"] = false;
        nlohmann::json errors = nlohmann::json::array();

        for (const int webcamIndex : indices) {
            result["attempted_indices"].push_back(webcamIndex);

            std::string probeError;
            const bool responding = probeLocalWebcamIndexResponding_(webcamIndex, 1400, probeError);
            if (responding) {
                result["responding_indices"].push_back(webcamIndex);
                result["preferred_index"] = webcamIndex;
                result["has_responsive_webcam"] = true;
                break;
            }

            if (!probeError.empty()) {
                errors.push_back({
                    { "index", webcamIndex },
                    { "error", probeError }
                });
            }
        }

        if (!errors.empty()) {
            result["errors"] = errors;
        }

        postCommandResult_(commandId, "completed", result);
    }
    catch (const std::exception& e) {
        nlohmann::json errorPayload;
        errorPayload["error"] = std::string("webcam probe failed: ") + e.what();
        postCommandResult_(commandId, "failed", errorPayload);
    }
    catch (...) {
        nlohmann::json errorPayload;
        errorPayload["error"] = "webcam probe failed";
        postCommandResult_(commandId, "failed", errorPayload);
    }
}

void AgentCore::handleDrakonFindCancelCommand_(int commandId, const nlohmann::json& payload)
{
    const int searchId = payload.value("search_id", -1);
    if (searchId <= 0) {
        if (commandId > 0) {
            nlohmann::json err;
            err["error"] = "search_id is required";
            postCommandResult_(commandId, "failed", err);
        }
        return;
    }

    bool accepted = false;
    {
        std::lock_guard<std::mutex> lk(drakonFindMu_);
        auto it = drakonFindTasks_.find(searchId);
        if (it != drakonFindTasks_.end() && it->second && it->second->state) {
            it->second->state->cancelRequested = true;
            accepted = true;
        }
    }

    if (commandId > 0) {
        nlohmann::json result;
        result["search_id"] = searchId;
        result["accepted"] = accepted;
        postCommandResult_(commandId, "completed", result);
    }
}

std::shared_ptr<AgentCore::ChatTaskState> AgentCore::registerChatTask_(int chatSessionId)
{
    if (chatSessionId <= 0) {
        return nullptr;
    }

    auto taskState = std::make_shared<ChatTaskState>();
    std::lock_guard<std::mutex> lock(chatTasksMu_);
    chatTasksBySession_[chatSessionId] = taskState;
    return taskState;
}

bool AgentCore::isChatCancellationRequested_(int chatSessionId) const
{
    if (chatSessionId <= 0) {
        return false;
    }

    std::lock_guard<std::mutex> lock(chatTasksMu_);
    const auto it = chatTasksBySession_.find(chatSessionId);
    if (it == chatTasksBySession_.end() || !it->second) {
        return false;
    }
    return it->second->cancelRequested.load();
}

void AgentCore::cleanupCompletedChatTasks_()
{
    std::lock_guard<std::mutex> lock(chatTasksMu_);
    for (auto it = chatTasksBySession_.begin(); it != chatTasksBySession_.end();) {
        if (!it->second || it->second->done.load()) {
            it = chatTasksBySession_.erase(it);
        }
        else {
            ++it;
        }
    }
}

void AgentCore::handleChatCancelCommand_(int commandId, const nlohmann::json& payload)
{
    const int chatSessionId = payload.value("chat_session_id", -1);
    if (chatSessionId <= 0) {
        if (commandId > 0) {
            nlohmann::json err;
            err["error"] = "chat_session_id is required";
            postCommandResult_(commandId, "failed", err);
        }
        return;
    }

    bool accepted = false;
    {
        std::lock_guard<std::mutex> lock(chatTasksMu_);
        const auto it = chatTasksBySession_.find(chatSessionId);
        if (it != chatTasksBySession_.end() && it->second) {
            it->second->cancelRequested = true;
            accepted = true;
        }
    }
    if (accepted) {
        coreModelArbiterCv_.notify_all();
    }

    if (commandId > 0) {
        nlohmann::json result;
        result["chat_session_id"] = chatSessionId;
        result["accepted"] = accepted;
        postCommandResult_(commandId, "completed", result);
    }
}

void AgentCore::handleChatIdentityUpsertCommand_(
    int commandId,
    const nlohmann::json& payload)
{
    auto fail = [&](const std::string& reason, const nlohmann::json& extra = nlohmann::json::object()) {
        nlohmann::json err = extra.is_object() ? extra : nlohmann::json::object();
        err["error"] = reason;
        if (commandId > 0) {
            postCommandResult_(commandId, "failed", err);
        }
        Logger::instance().logDebug(
            "agent",
            "handleChatIdentityUpsertCommand_: failed reason=" + reason);
    };

    const int chatSessionId = payload.value("chat_session_id", -1);
    const std::string entityId = trimAscii(payload.value("entity_id", std::string()));
    if (chatSessionId <= 0) {
        fail("chat_session_id is required");
        return;
    }
    if (entityId.empty()) {
        fail("entity_id is required", nlohmann::json::object({ { "chat_session_id", chatSessionId } }));
        return;
    }

    ChatTemporalState chatTemporalState;
    bool loadedFromMemory = false;
    {
        std::lock_guard<std::mutex> lock(chatTemporalMu_);
        auto it = chatTemporalBySession_.find(chatSessionId);
        if (it != chatTemporalBySession_.end()) {
            chatTemporalState = it->second;
            loadedFromMemory = true;
        }
    }
    if (!loadedFromMemory) {
        (void)loadPersistedChatTemporalState_(chatSessionId, chatTemporalState);
    }

    temporal::ensureState(chatTemporalState.state);
    ensureChatTemporalVisualState_(chatTemporalState.visualState);
    if (!chatTemporalState.state.contains("entities") || !chatTemporalState.state["entities"].is_object()) {
        chatTemporalState.state["entities"] = nlohmann::json::object();
    }
    if (!chatTemporalState.state["entities"].contains(entityId) ||
        !chatTemporalState.state["entities"][entityId].is_object())
    {
        chatTemporalState.state["entities"][entityId] = nlohmann::json::object();
    }

    const nlohmann::json cardSnapshot =
        payload.contains("card_snapshot") && payload["card_snapshot"].is_object()
            ? payload["card_snapshot"]
            : nlohmann::json::object();
    const nlohmann::json* primaryPortrait = findOptionalObjectField_(cardSnapshot, "primary_portrait");
    const nlohmann::json* contextPortrait = findOptionalObjectField_(cardSnapshot, "context_portrait");
    const nlohmann::json* lastSeenSnapshot = findOptionalObjectField_(cardSnapshot, "last_seen");

    std::string entityType = canonicalizeEntityTypeForCard_(trimAscii(payload.value("entity_type", std::string())));
    if (entityType.empty()) {
        entityType = canonicalizeEntityTypeForCard_(trimAscii(cardSnapshot.value("entity_type", std::string())));
    }
    if (entityType.empty() && chatTemporalState.state["entities"][entityId].contains("entity_type") &&
        chatTemporalState.state["entities"][entityId]["entity_type"].is_string())
    {
        entityType = canonicalizeEntityTypeForCard_(
            chatTemporalState.state["entities"][entityId]["entity_type"].get<std::string>());
    }
    if (!entityType.empty()) {
        chatTemporalState.state["entities"][entityId]["entity_type"] = entityType;
    }

    const nlohmann::json physicalTraits =
        temporal::parseTraitsValue(
            payload.contains("physical_traits") ? payload["physical_traits"] : nlohmann::json::array());
    const nlohmann::json manualFeatureCandidates =
        buildManualIdentityFeatureCandidatesFromTraits_(physicalTraits);

    std::string seenTs = readOptionalTrimmedStringField_(lastSeenSnapshot, "timestamp_utc_iso");
    if (seenTs.empty()) {
        seenTs = readOptionalTrimmedStringField_(primaryPortrait, "timestamp_utc_iso");
    }
    if (seenTs.empty()) {
        seenTs = readOptionalTrimmedStringField_(contextPortrait, "timestamp_utc_iso");
    }
    if (seenTs.empty()) {
        seenTs = readOptionalTrimmedStringField_(primaryPortrait, "last_seen_ts_utc");
    }
    if (seenTs.empty()) {
        seenTs = temporal::nowIso();
    }

    std::string zone = readOptionalTrimmedStringField_(lastSeenSnapshot, "zone");
    if (zone.empty()) {
        zone = readOptionalTrimmedStringField_(primaryPortrait, "zone");
    }

    nlohmann::json resolvedIdentity = nlohmann::json::object();
    const nlohmann::json& entityState = chatTemporalState.state["entities"][entityId];
    if (entityState.contains("resolved_identity") && entityState["resolved_identity"].is_object()) {
        resolvedIdentity = entityState["resolved_identity"];
    }
    if (cardSnapshot.contains("resolved_identity") && cardSnapshot["resolved_identity"].is_object()) {
        for (auto it = cardSnapshot["resolved_identity"].begin();
             it != cardSnapshot["resolved_identity"].end();
             ++it)
        {
            resolvedIdentity[it.key()] = it.value();
        }
    }
    if (payload.contains("resolved_identity") && payload["resolved_identity"].is_object()) {
        for (auto it = payload["resolved_identity"].begin();
             it != payload["resolved_identity"].end();
             ++it)
        {
            resolvedIdentity[it.key()] = it.value();
        }
    }

    const std::string targetName = trimAscii(payload.value("target_name", std::string()));
    if (!targetName.empty()) {
        resolvedIdentity["target_name"] = targetName;
    }
    const std::string targetDescription = trimAscii(payload.value("target_description", std::string()));
    if (!targetDescription.empty()) {
        resolvedIdentity["target_description"] = targetDescription;
    }
    if (!resolvedIdentity.contains("source") || !resolvedIdentity["source"].is_string()) {
        const bool saveAsFaceTarget =
            (payload.contains("save_as_face_target") && payload["save_as_face_target"].is_boolean())
                ? payload["save_as_face_target"].get<bool>()
                : false;
        resolvedIdentity["source"] = saveAsFaceTarget
            ? "user_confirmed_target_link"
            : "user_named_identity";
    }
    resolvedIdentity["confirmed_at_utc"] = seenTs;

    nlohmann::json manualPatch = nlohmann::json::object();
    manualPatch["entity_id"] = entityId;
    if (!entityType.empty()) {
        manualPatch["entity_type"] = entityType;
    }
    if (!targetDescription.empty()) {
        manualPatch["description"] = targetDescription;
    }
    else {
        const std::string snapshotDescription = trimAscii(cardSnapshot.value("description", std::string()));
        if (!snapshotDescription.empty()) {
            manualPatch["description"] = snapshotDescription;
        }
    }
    if (physicalTraits.is_array() && !physicalTraits.empty()) {
        manualPatch["identity_signature_traits"] = physicalTraits;
    }
    if (manualFeatureCandidates.is_array() && !manualFeatureCandidates.empty()) {
        manualPatch["identity_feature_candidates"] = manualFeatureCandidates;
    }
    else if (cardSnapshot.contains("identity_feature_candidates")) {
        manualPatch["identity_feature_candidates"] = cardSnapshot["identity_feature_candidates"];
    }
    if (resolvedIdentity.contains("reference_image_urls")) {
        manualPatch["reference_image_urls"] = resolvedIdentity["reference_image_urls"];
    }
    else if (cardSnapshot.contains("reference_image_urls")) {
        manualPatch["reference_image_urls"] = cardSnapshot["reference_image_urls"];
    }

    temporal::upsertIdentityMemory(
        chatTemporalState.state,
        entityId,
        manualPatch,
        seenTs,
        zone);
    if (resolvedIdentity.is_object() && !resolvedIdentity.empty()) {
        temporal::upsertResolvedIdentity(
            chatTemporalState.state,
            entityId,
            resolvedIdentity,
            seenTs);
    }

    const std::string portraitDataUrl = trimAscii(payload.value("portrait_data_url", std::string()));
    if (!portraitDataUrl.empty()) {
        nlohmann::json portraitCandidate = buildManualChatIdentityPortraitCandidate_(
            cardSnapshot,
            entityId,
            entityType,
            seenTs,
            physicalTraits,
            resolvedIdentity,
            portraitDataUrl);
        if (portraitCandidate.is_object() && !portraitCandidate.empty()) {
            seedIdentityMemoryFromPortraitCandidate_(
                portraitCandidate,
                entityId,
                chatTemporalState.state);
            (void)promotePortraitCandidateToVisualState_(
                portraitCandidate,
                nlohmann::json::array(),
                chatTemporalState.state,
                chatTemporalState.visualState);
        }
    }

    nlohmann::json lastSeen = nlohmann::json::object();
    if (!seenTs.empty()) {
        lastSeen["timestamp_utc_iso"] = seenTs;
    }
    const int cameraId =
        lastSeenSnapshot != nullptr
            ? lastSeenSnapshot->value("camera_id", primaryPortrait != nullptr ? primaryPortrait->value("camera_id", -1) : -1)
            : (primaryPortrait != nullptr ? primaryPortrait->value("camera_id", -1) : -1);
    if (cameraId > 0) {
        lastSeen["camera_id"] = cameraId;
    }
    const std::string cameraName =
        !readOptionalTrimmedStringField_(lastSeenSnapshot, "camera_name").empty()
            ? readOptionalTrimmedStringField_(lastSeenSnapshot, "camera_name")
            : readOptionalTrimmedStringField_(primaryPortrait, "camera_name");
    if (!cameraName.empty()) {
        lastSeen["camera_name"] = cameraName;
    }
    if (!zone.empty()) {
        lastSeen["zone"] = zone;
    }
    if (!lastSeen.empty()) {
        chatTemporalState.visualState["last_seen_by_entity_id"][entityId] = lastSeen;
    }

    nlohmann::json updatedCard = buildChatIdentityCardForEntity_(
        entityId,
        chatTemporalState.state,
        chatTemporalState.visualState);
    if (!updatedCard.is_object() || updatedCard.empty()) {
        fail(
            "Failed to rebuild identity card after update.",
            nlohmann::json::object({
                { "chat_session_id", chatSessionId },
                { "entity_id", entityId }
            }));
        return;
    }

    const std::string replyLanguage = resolveChatReplyLocaleFromPayload_(payload);
    const bool savedFaceTarget =
        resolvedIdentity.contains("target_id") &&
        ((resolvedIdentity["target_id"].is_number_integer() && resolvedIdentity["target_id"].get<int>() > 0) ||
         (resolvedIdentity["target_id"].is_string() &&
          !trimAscii(resolvedIdentity["target_id"].get<std::string>()).empty()));
    const std::string displayLabel =
        trimAscii(updatedCard.value("display_name", std::string())).empty()
            ? entityId
            : trimAscii(updatedCard.value("display_name", std::string()));
    const std::string answer = buildManualChatIdentityUpdateAnswer_(
        replyLanguage,
        displayLabel,
        savedFaceTarget);

    nlohmann::json postBody = nlohmann::json::object();
    postBody["chat_session_id"] = chatSessionId;
    postBody["command_id"] = commandId;
    postBody["answer"] = answer;
    postBody["vision_hits"] = nlohmann::json::array();
    postBody["identity_cards"] = nlohmann::json::array({ updatedCard });
    postBody["response_type"] = "final_answer";
    postBody["status"] = "identity_card_updated";
    postBody["model_prompt_tokens"] = 0;
    postBody["model_output_tokens"] = 0;
    postBody["model_total_tokens"] = 0;

    try {
        const std::string url = baseUrl_ + "/api/agent/chat-response?client_id=" + clientId_;
        std::string responseBody;
        const long httpCode = HttpPostJson(url, exeToken_, postBody.dump(), responseBody);
        if (httpCode != 200) {
            fail(
                "Failed to post updated identity card to chat.",
                nlohmann::json::object({
                    { "chat_session_id", chatSessionId },
                    { "entity_id", entityId },
                    { "http_code", httpCode }
                }));
            return;
        }
    }
    catch (const std::exception& e) {
        fail(
            std::string("Failed to post updated identity card to chat: ") + e.what(),
            nlohmann::json::object({
                { "chat_session_id", chatSessionId },
                { "entity_id", entityId }
            }));
        return;
    }

    chatTemporalState.touchedAt = std::chrono::steady_clock::now();
    {
        std::lock_guard<std::mutex> lock(chatTemporalMu_);
        chatTemporalBySession_[chatSessionId] = chatTemporalState;
    }
    if (!persistChatTemporalState_(chatSessionId, chatTemporalState)) {
        Logger::instance().logDebug(
            "agent",
            "handleChatIdentityUpsertCommand_: persistChatTemporalState_ failed for chat_session_id=" +
            std::to_string(chatSessionId));
    }

    if (commandId > 0) {
        nlohmann::json result = nlohmann::json::object({
            { "chat_session_id", chatSessionId },
            { "entity_id", entityId },
            { "card_id", updatedCard.value("card_id", std::string()) },
            { "display_name", updatedCard.value("display_name", std::string()) }
        });
        if (resolvedIdentity.contains("target_id")) {
            result["target_id"] = resolvedIdentity["target_id"];
        }
        postCommandResult_(commandId, "completed", result);
    }
}

void AgentCore::handleDrakonFindStartCommand_(int commandId, const nlohmann::json& payload)
{
    auto fail = [&](const std::string& reason) {
        if (commandId > 0) {
            nlohmann::json err;
            err["error"] = reason;
            postCommandResult_(commandId, "failed", err);
        }
    };

    cleanupCompletedDrakonFindTasks_(false);

    const int searchId = payload.value("search_id", -1);
    const int targetId = payload.value("target_id", -1);
    const int attemptCount = (std::max)(1, payload.value("attempt_count", 1));
    const std::string operatorUserId = payload.value("operator_user_id", std::string());
    std::string searchPrompt = payload.value("search_prompt", std::string());
    std::string modelName = payload.value("model_name", std::string("gpt-5.1"));
    std::string modelApiKey = payload.value("model_api_key", std::string());
    const int modelInputFps = clampRequestedModelFps_(payload.value("model_fps", 1));

    auto trimLocal = [](const std::string& value) {
        const auto first = value.find_first_not_of(" \t\r\n");
        if (first == std::string::npos) return std::string();
        const auto last = value.find_last_not_of(" \t\r\n");
        return value.substr(first, last - first + 1);
    };

    searchPrompt = trimLocal(searchPrompt);
    modelName = trimLocal(modelName);
    modelApiKey = trimLocal(modelApiKey);

    if (searchId <= 0) {
        fail("search_id is required");
        return;
    }
    if (searchPrompt.empty()) {
        fail("search_prompt is required");
        return;
    }
    if (modelApiKey.empty()) {
        fail("model_api_key is required");
        return;
    }

    std::string targetName;
    if (payload.contains("target") && payload["target"].is_object()) {
        targetName = payload["target"].value("name", std::string());
    }
    targetName = trimLocal(targetName);

    struct CameraAssignmentLocal {
        int cameraId = -1;
        std::string cameraName;
        std::string cameraOwnerUserId;
        std::string city;
        std::string stateCode;
        std::string countryCode;
        bool wasServiceRunning = false;
        nlohmann::json cameraPayload = nlohmann::json::object();
    };

    std::vector<CameraAssignmentLocal> cameraAssignments;
    if (payload.contains("camera_assignments") && payload["camera_assignments"].is_array()) {
        for (const auto& item : payload["camera_assignments"]) {
            if (!item.is_object()) continue;
            CameraAssignmentLocal row;
            row.cameraId = item.value("camera_id", -1);
            row.cameraName = trimLocal(item.value("camera_name", std::string()));
            row.cameraOwnerUserId = trimLocal(item.value("camera_owner_user_id", std::string()));
            row.city = trimLocal(item.value("city", std::string()));
            row.stateCode = trimLocal(item.value("state_code", std::string()));
            row.countryCode = trimLocal(item.value("country_code", std::string()));
            if (item.contains("was_service_running")) {
                if (item["was_service_running"].is_boolean()) {
                    row.wasServiceRunning = item["was_service_running"].get<bool>();
                }
                else if (item["was_service_running"].is_number_integer()) {
                    row.wasServiceRunning = item["was_service_running"].get<int>() != 0;
                }
            }
            if (item.contains("camera_payload") && item["camera_payload"].is_object()) {
                row.cameraPayload = item["camera_payload"];
            }
            if (row.cameraId > 0) {
                cameraAssignments.push_back(std::move(row));
            }
        }
    }
    if (cameraAssignments.empty()) {
        fail("camera_assignments is required");
        return;
    }

    std::vector<DrakonFindReferenceImage> referenceImages;
    if (payload.contains("reference_images") && payload["reference_images"].is_array()) {
        for (const auto& item : payload["reference_images"]) {
            if (!item.is_object()) continue;
            DrakonFindReferenceImage reference;
            reference.imageId = item.value("image_id", -1);
            reference.imageUrl = trimLocal(item.value("image_url", std::string()));
            reference.contentType = trimLocal(item.value("content_type", std::string()));
            reference.imageDataUrl = trimLocal(item.value("data_url", std::string()));
            if (!reference.imageDataUrl.empty()) {
                referenceImages.push_back(std::move(reference));
            }
        }
    }

    std::string runtimeMode = payload.value("runtime_mode", std::string("continuous_video_60s"));
    std::string inputType = payload.value("input_type", std::string("video"));
    runtimeMode = trimLocal(runtimeMode);
    inputType = trimLocal(inputType);
    if (runtimeMode.empty()) runtimeMode = "continuous_video_60s";
    if (inputType.empty()) inputType = "video";

    const int windowSeconds = (std::max)(1, payload.value("window_seconds", 60));
    const int durationSeconds = (std::max)(
        windowSeconds,
        payload.value("duration_seconds", 1800)
    );

    auto taskState = std::make_shared<DrakonFindTaskState>();
    {
        std::lock_guard<std::mutex> lk(drakonFindMu_);
        auto it = drakonFindTasks_.find(searchId);
        if (it != drakonFindTasks_.end() &&
            it->second &&
            it->second->state &&
            !it->second->state->done.load())
        {
            fail("search is already running on this EXE");
            return;
        }
    }

    auto task = std::make_unique<DrakonFindTask>();
    task->state = taskState;
    task->worker = std::thread(
        [this,
         commandId,
         searchId,
         targetId,
         attemptCount,
         operatorUserId,
         targetName,
         searchPrompt,
         modelName,
         modelApiKey,
         modelInputFps,
         runtimeMode,
         inputType,
         windowSeconds,
         durationSeconds,
         trimLocal,
         referenceImages,
         cameraAssignments,
         taskState]() {
            auto postSearchEvent = [&](const std::string& eventType,
                                       const std::string& message,
                                       const nlohmann::json& extra = nlohmann::json::object()) {
                nlohmann::json details = extra;
                details["search_id"] = searchId;
                details["target_id"] = targetId;
                details["attempt_count"] = attemptCount;
                if (!targetName.empty()) details["target_name"] = targetName;
                postAgentEvent(eventType, std::nullopt, operatorUserId, message, details);
            };

            auto postCameraEvent = [&](const std::string& eventType,
                                       const CameraAssignmentLocal& camera,
                                       const std::string& message,
                                       const nlohmann::json& extra = nlohmann::json::object()) {
                nlohmann::json details = extra;
                details["search_id"] = searchId;
                details["target_id"] = targetId;
                details["attempt_count"] = attemptCount;
                details["camera_id"] = camera.cameraId;
                details["camera_name"] = camera.cameraName;
                details["camera_owner_user_id"] = camera.cameraOwnerUserId;
                details["city"] = camera.city;
                details["state_code"] = camera.stateCode;
                details["country_code"] = camera.countryCode;
                if (!targetName.empty()) details["target_name"] = targetName;
                postAgentEvent(eventType, std::optional<int>(camera.cameraId), operatorUserId, message, details);
            };

            auto stopTemporarySessionIfSafe = [&](const CameraAssignmentLocal& camera,
                                                  bool temporarySessionStarted,
                                                  const std::optional<CameraConfig>& temporaryCfg) {
                if (!temporarySessionStarted) return;
                if (camera.wasServiceRunning) return;
                if (!temporaryCfg.has_value()) return;

                CameraSession* currentSession = getCameraSession(camera.cameraId);
                if (!currentSession) return;
                if (!currentSession->matchesStartConfig(*temporaryCfg)) return;

                Logger::instance().logDebug(
                    "agent",
                    "handleDrakonFindStartCommand_: stopping temporary Drakon Find session for camera " +
                    std::to_string(camera.cameraId)
                );
                stopCamera_(camera.cameraId);
            };

            auto waitForNewStoredClip = [&](int cameraId,
                                            const std::string& lastProcessedPath,
                                            const std::chrono::steady_clock::time_point& deadline,
                                            std::string& outClipPath) -> bool {
                outClipPath.clear();

                while (running_ && !taskState->cancelRequested.load()) {
                    if (std::chrono::steady_clock::now() >= deadline) {
                        break;
                    }

                    const auto newestClip = getNewestStoredSixtySecondClipForCameraDrakonFind_(cameraId);
                    if (newestClip.has_value() &&
                        !newestClip->empty() &&
                        *newestClip != lastProcessedPath)
                    {
                        outClipPath = *newestClip;
                        return true;
                    }

                    std::this_thread::sleep_for(std::chrono::milliseconds(1000));
                }

                const auto newestClip = getNewestStoredSixtySecondClipForCameraDrakonFind_(cameraId);
                if (newestClip.has_value() &&
                    !newestClip->empty() &&
                    *newestClip != lastProcessedPath)
                {
                    outClipPath = *newestClip;
                    return true;
                }

                return false;
            };

            auto buildStoredClipSegment = [&](const CameraAssignmentLocal& camera,
                                              const std::string& clipPath,
                                              EncodedVideoSegment& outSegment,
                                              std::string& outError) -> bool {
                outSegment = EncodedVideoSegment{};
                outError.clear();

                if (clipPath.empty()) {
                    outError = "stored clip path is empty";
                    return false;
                }

                std::error_code ec;
                if (!fs::exists(clipPath, ec) || ec) {
                    outError = "stored 60s clip is not available on disk";
                    return false;
                }

                outSegment.cameraId = camera.cameraId;
                outSegment.cameraName = camera.cameraName;
                outSegment.sourceFilePath = clipPath;
                outSegment.isTempFile = false;

                if (!deriveStoredClipUtcRangeDrakonFind_(
                    fs::path(clipPath),
                    outSegment.startTs,
                    outSegment.endTs))
                {
                    Logger::instance().logDebug(
                        "agent",
                        "handleDrakonFindStartCommand_: could not derive UTC range from stored clip " + clipPath
                    );
                }

                return true;
            };

            auto buildDetectionTimeHint = [&](const nlohmann::json& detectionTimeInVideo) -> std::string {
                if (detectionTimeInVideo.is_string()) {
                    return trimAscii(detectionTimeInVideo.get<std::string>());
                }
                if (!detectionTimeInVideo.is_array()) {
                    return std::string();
                }
                for (const auto& item : detectionTimeInVideo) {
                    if (item.is_string()) {
                        const std::string value = trimAscii(item.get<std::string>());
                        if (!value.empty()) return value;
                    }
                }
                return std::string();
            };

            auto cleanupTempSegmentFile = [&](const EncodedVideoSegment& segment) {
                if (!segment.isTempFile || segment.sourceFilePath.empty()) return;
                std::error_code rmEc;
                fs::remove(segment.sourceFilePath, rmEc);
            };

            std::atomic<int> matchedCameraCount{ 0 };
            std::atomic<int> completedCameraCount{ 0 };
            std::atomic<int> failedCameraCount{ 0 };
            std::atomic<int> cancelledCameraCount{ 0 };
            std::atomic<int> totalPromptTokens{ 0 };
            std::atomic<int> totalOutputTokens{ 0 };
            std::atomic<int> totalTokens{ 0 };
            const auto searchStartedAtSteady = std::chrono::steady_clock::now();
            const auto searchDeadlineSteady =
                searchStartedAtSteady + std::chrono::seconds(durationSeconds);
            std::vector<std::thread> cameraWorkers;
            cameraWorkers.reserve(cameraAssignments.size());

            try {
                postSearchEvent(
                    "drakon_find_search_started",
                    "Drakon Find search started",
                    {
                        { "camera_count", static_cast<int>(cameraAssignments.size()) },
                        { "reference_image_count", static_cast<int>(referenceImages.size()) },
                        { "runtime_mode", runtimeMode },
                        { "input_type", inputType },
                        { "window_seconds", windowSeconds },
                        { "duration_seconds", durationSeconds }
                    }
                );

                for (const auto& camera : cameraAssignments) {
                    cameraWorkers.emplace_back([&, camera]() {
                        bool temporarySessionStarted = false;
                        std::optional<CameraConfig> temporaryCfg;
                        int analyzedWindowCount = 0;
                        int cameraHitCount = 0;
                        int cameraPromptTokens = 0;
                        int cameraOutputTokens = 0;
                        int cameraUsedTokens = 0;
                        int consecutiveWindowFailures = 0;
                        std::string lastProcessedStoredClipPath;
                        std::string lastSegmentSource;
                        std::string lastSummary;
                        std::string lastErrorForCamera;
                        std::unordered_set<std::string> processedSegmentKeys;

                        auto buildRuntimeDetails = [&](const std::string& status) {
                            nlohmann::json details = {
                                { "status", status },
                                { "runtime_mode", runtimeMode },
                                { "input_type", inputType },
                                { "window_seconds", windowSeconds },
                                { "duration_seconds", durationSeconds },
                                { "analyzed_window_count", analyzedWindowCount },
                                { "camera_hit_count", cameraHitCount },
                                { "prompt_tokens", cameraPromptTokens },
                                { "output_tokens", cameraOutputTokens },
                                { "total_tokens", cameraUsedTokens }
                            };
                            if (!lastSegmentSource.empty()) details["segment_source"] = lastSegmentSource;
                            if (!lastErrorForCamera.empty()) details["error"] = lastErrorForCamera;
                            return details;
                        };
                        auto buildSegmentIdentityKey = [&](const EncodedVideoSegment& segment) -> std::string {
                            std::string startTs = trimAscii(segment.startTs);
                            std::string endTs = trimAscii(segment.endTs);
                            if ((startTs.empty() || endTs.empty()) && !segment.sourceFilePath.empty()) {
                                std::string clipCameraId;
                                std::string clipStartTs;
                                std::string clipEndTs;
                                int clipNominalSeconds = 0;
                                if (parseClipNamePartsForAgent(
                                    fs::path(segment.sourceFilePath).stem().string(),
                                    clipCameraId,
                                    clipStartTs,
                                    clipEndTs,
                                    clipNominalSeconds))
                                {
                                    if (startTs.empty()) startTs = clipStartTs;
                                    if (endTs.empty()) endTs = clipEndTs;
                                }
                            }
                            if (!startTs.empty() && !endTs.empty()) {
                                return startTs + "|" + endTs;
                            }
                            return trimAscii(segment.sourceFilePath);
                        };

                        int drakonFindCaptureRequestId = -1;
                        auto releaseDrakonFindCaptureRequest = [&](int* requestIdPtr) {
                            if (!requestIdPtr || *requestIdPtr <= 0) return;
                            releaseDrakonFindVideoCapture_(camera.cameraId, *requestIdPtr);
                            *requestIdPtr = -1;
                        };
                        std::unique_ptr<int, decltype(releaseDrakonFindCaptureRequest)> drakonFindCaptureGuard(
                            nullptr,
                            releaseDrakonFindCaptureRequest
                        );

                        try {
                            postCameraEvent(
                                "drakon_find_camera_started",
                                camera,
                                "Camera assigned to continuous Drakon Find runtime",
                                {
                                    { "runtime_mode", runtimeMode },
                                    { "input_type", inputType },
                                    { "window_seconds", windowSeconds },
                                    { "duration_seconds", durationSeconds }
                                }
                            );

                            const bool shouldAcquireDrakonFindVideoCapture =
                                inputType == "video" &&
                                normalizeCaptureClipSeconds_(windowSeconds) > 10;
                            if (shouldAcquireDrakonFindVideoCapture) {
                                drakonFindCaptureRequestId = acquireDrakonFindVideoCapture_(
                                    searchId,
                                    camera.cameraId,
                                    modelInputFps,
                                    windowSeconds
                                );
                                if (drakonFindCaptureRequestId > 0) {
                                    drakonFindCaptureGuard.reset(&drakonFindCaptureRequestId);
                                }
                            }

                            CameraSession* session = getCameraSession(camera.cameraId);
                            if (!session && camera.cameraPayload.is_object()) {
                                postCameraEvent(
                                    "drakon_find_camera_progress",
                                    camera,
                                    "Starting temporary camera session for Drakon Find",
                                    {
                                        { "runtime_mode", runtimeMode },
                                        { "input_type", inputType },
                                        { "window_seconds", windowSeconds },
                                        { "duration_seconds", durationSeconds }
                                    }
                                );
                                nlohmann::json temporaryCameraPayload = camera.cameraPayload;
                                temporaryCameraPayload["drakon_find_temporary_session"] = true;
                                temporaryCameraPayload["hydrate_existing_segments"] = false;
                                try {
                                    temporaryCfg = buildCameraConfigFromPayload_(camera.cameraId, temporaryCameraPayload);
                                }
                                catch (...) {
                                    temporaryCfg.reset();
                                }
                                startCameraFromPayload_(camera.cameraId, temporaryCameraPayload);
                                session = getCameraSession(camera.cameraId);
                                if (session) {
                                    temporarySessionStarted = true;
                                    lastSegmentSource = "temporary_session";
                                    postCameraEvent(
                                        "drakon_find_camera_progress",
                                        camera,
                                        "Temporary camera session started for Drakon Find",
                                        {
                                            { "segment_source", lastSegmentSource },
                                            { "runtime_mode", runtimeMode },
                                            { "input_type", inputType },
                                            { "window_seconds", windowSeconds },
                                            { "duration_seconds", durationSeconds }
                                        }
                                    );
                                }
                            }

                            if (const auto newestClip = getNewestStoredSixtySecondClipForCameraDrakonFind_(camera.cameraId);
                                newestClip.has_value())
                            {
                                lastProcessedStoredClipPath = *newestClip;
                            }

                            if (!session && !camera.cameraPayload.is_object()) {
                                lastErrorForCamera = "camera session is not available on this EXE";
                                failedCameraCount.fetch_add(1);
                                postCameraEvent(
                                    "drakon_find_camera_failed",
                                    camera,
                                    "Camera session is not available on this EXE",
                                    buildRuntimeDetails("failed")
                                );
                                return;
                            }

                            while (running_ && !taskState->cancelRequested.load()) {
                                const auto nowSteady = std::chrono::steady_clock::now();
                                if (nowSteady >= searchDeadlineSteady) break;
                                const auto remainingSeconds = std::chrono::duration_cast<std::chrono::seconds>(
                                    searchDeadlineSteady - nowSteady
                                ).count();
                                if (remainingSeconds < windowSeconds) break;

                                EncodedVideoSegment segment;
                                std::string acquisitionError;
                                bool haveSegment = false;
                                std::string newestClipPath;
                                const bool preferOnDemandCapture =
                                    modelInputFps > 1 && camera.cameraPayload.is_object();
                                const auto storedClipWait = temporarySessionStarted
                                    ? std::chrono::seconds(windowSeconds + 20)
                                    : std::chrono::seconds(5);
                                const auto clipWaitDeadline = (std::min)(
                                    searchDeadlineSteady,
                                    nowSteady + storedClipWait
                                );

                                if (!preferOnDemandCapture &&
                                    waitForNewStoredClip(
                                        camera.cameraId,
                                        lastProcessedStoredClipPath,
                                        clipWaitDeadline,
                                        newestClipPath))
                                {
                                    haveSegment = buildStoredClipSegment(
                                        camera,
                                        newestClipPath,
                                        segment,
                                        acquisitionError
                                    );
                                    if (haveSegment) {
                                        lastProcessedStoredClipPath = newestClipPath;
                                        lastSegmentSource = temporarySessionStarted
                                            ? "stored_clip_temporary_session"
                                            : "stored_clip_running_session";
                                    }
                                }

                                if (!haveSegment && camera.cameraPayload.is_object()) {
                                    postCameraEvent(
                                        "drakon_find_camera_progress",
                                        camera,
                                        "Capturing a 60-second video window for Drakon Find",
                                        {
                                            { "runtime_mode", runtimeMode },
                                            { "input_type", inputType },
                                            { "window_seconds", windowSeconds },
                                            { "duration_seconds", durationSeconds }
                                        }
                                    );

                                    haveSegment = captureOnDemandVideoWindowDrakonFind_(
                                        camera.cameraPayload,
                                        camera.cameraId,
                                        windowSeconds,
                                        modelInputFps,
                                        taskState->cancelRequested,
                                        segment,
                                        acquisitionError
                                    );
                                    if (haveSegment) {
                                        segment.cameraName = camera.cameraName;
                                        lastSegmentSource = "on_demand_video_window";
                                    }
                                }

                                if (!haveSegment) {
                                    if (taskState->cancelRequested.load() || !running_) break;

                                    lastErrorForCamera = acquisitionError.empty()
                                        ? "failed to capture a 60-second video window"
                                        : acquisitionError;
                                    consecutiveWindowFailures += 1;
                                    postCameraEvent(
                                        "drakon_find_camera_progress",
                                        camera,
                                        "Unable to acquire the next 60-second window; retrying",
                                        {
                                            { "error", lastErrorForCamera },
                                            { "consecutive_failures", consecutiveWindowFailures },
                                            { "runtime_mode", runtimeMode },
                                            { "input_type", inputType },
                                            { "window_seconds", windowSeconds },
                                            { "duration_seconds", durationSeconds }
                                        }
                                    );
                                    if (consecutiveWindowFailures >= 3) break;
                                    std::this_thread::sleep_for(std::chrono::seconds(2));
                                    continue;
                                }

                                if (taskState->cancelRequested.load() || !running_) {
                                    cleanupTempSegmentFile(segment);
                                    break;
                                }

                                const std::string segmentIdentityKey = buildSegmentIdentityKey(segment);
                                if (!segmentIdentityKey.empty() &&
                                    !processedSegmentKeys.insert(segmentIdentityKey).second)
                                {
                                    cleanupTempSegmentFile(segment);
                                    continue;
                                }

                                consecutiveWindowFailures = 0;

                                int promptTokens = 0;
                                int outputTokens = 0;
                                int usedTokens = 0;
                                const DrakonFindInferenceResult inference = runDrakonFindVideoInference_(
                                    segment,
                                    searchPrompt,
                                    referenceImages,
                                    modelName,
                                    modelApiKey,
                                    modelInputFps,
                                    windowSeconds,
                                    promptTokens,
                                    outputTokens,
                                    usedTokens
                                );

                                totalPromptTokens.fetch_add(promptTokens);
                                totalOutputTokens.fetch_add(outputTokens);
                                totalTokens.fetch_add(usedTokens);
                                cameraPromptTokens += promptTokens;
                                cameraOutputTokens += outputTokens;
                                cameraUsedTokens += usedTokens;
                                analyzedWindowCount += 1;

                                const std::string safeSummary = inference.summary.empty()
                                    ? (inference.hasMatch
                                        ? std::string("Match visual identificado na janela de video.")
                                        : std::string("Sem match confiavel na janela de video."))
                                    : inference.summary;
                                lastSummary = safeSummary;
                                lastErrorForCamera.clear();

                                nlohmann::json windowDetails = {
                                    { "match", inference.hasMatch },
                                    { "confidence", inference.confidence },
                                    { "summary", safeSummary },
                                    { "runtime_mode", runtimeMode },
                                    { "input_type", inputType },
                                    { "window_seconds", windowSeconds },
                                    { "duration_seconds", durationSeconds },
                                    { "analyzed_window_count", analyzedWindowCount },
                                    { "camera_hit_count", cameraHitCount },
                                    { "prompt_tokens", promptTokens },
                                    { "output_tokens", outputTokens },
                                    { "total_tokens", usedTokens },
                                    { "segment_source", lastSegmentSource }
                                };
                                if (!segment.startTs.empty()) windowDetails["segment_start_ts"] = segment.startTs;
                                if (!segment.endTs.empty()) windowDetails["segment_end_ts"] = segment.endTs;
                                if (!inference.observedTraits.is_null()) windowDetails["observed_traits"] = inference.observedTraits;
                                if (!inference.detectionTimeInVideo.is_null() && !inference.detectionTimeInVideo.empty()) {
                                    windowDetails["detection_time_in_video"] = inference.detectionTimeInVideo;
                                }
                                if (!inference.raw.is_null() && !inference.raw.empty()) {
                                    windowDetails["model_output"] = inference.raw;
                                }

                                if (inference.hasMatch) {
                                    cameraHitCount += 1;
                                    windowDetails["camera_hit_count"] = cameraHitCount;

                                    const std::string detectionTimeHint =
                                        buildDetectionTimeHint(inference.detectionTimeInVideo);
                                    const std::string clipTimeHint =
                                        !detectionTimeHint.empty() ? detectionTimeHint : std::string("00:00");

                                    std::vector<std::uint8_t> matchedVideoBytes;
                                    if (!segment.sourceFilePath.empty()) {
                                        matchedVideoBytes = extractMp4ClipAtTime(
                                            segment.sourceFilePath,
                                            clipTimeHint,
                                            /*clipSeconds=*/10,
                                            detectionTimeHint.empty() ? 0 : 2
                                        );
                                    }

                                    std::string uploadedVideoKey;
                                    std::string uploadedVideoUrl;
                                    if (!matchedVideoBytes.empty() &&
                                        uploadDrakonFindHitMedia_(
                                            searchId,
                                            camera.cameraId,
                                            attemptCount,
                                            "video",
                                            "video/mp4",
                                            matchedVideoBytes,
                                            clipTimeHint,
                                            uploadedVideoKey,
                                            uploadedVideoUrl))
                                    {
                                        windowDetails["video_key"] = uploadedVideoKey;
                                        windowDetails["video_url"] = uploadedVideoUrl;
                                        windowDetails["clip_url"] = uploadedVideoUrl;
                                    }

                                    std::string representativeFrameDataUrl;
                                    if (buildRepresentativeFrameDataUrlForDrakonFind_(
                                        segment.sourceFilePath,
                                        clipTimeHint,
                                        representativeFrameDataUrl) &&
                                        !representativeFrameDataUrl.empty())
                                    {
                                        windowDetails["snapshot_image_data_url"] = representativeFrameDataUrl;
                                    }

                                    postCameraEvent("drakon_find_hit", camera, safeSummary, windowDetails);
                                }
                                else {
                                    postCameraEvent(
                                        "drakon_find_camera_progress",
                                        camera,
                                        "60-second video window analyzed without a confident match",
                                        windowDetails
                                    );
                                }

                                cleanupTempSegmentFile(segment);
                            }

                            stopTemporarySessionIfSafe(camera, temporarySessionStarted, temporaryCfg);

                            if (taskState->cancelRequested.load() || !running_) {
                                cancelledCameraCount.fetch_add(1);
                                postCameraEvent(
                                    "drakon_find_camera_cancelled",
                                    camera,
                                    analyzedWindowCount > 0
                                        ? "Camera search cancelled during the live video runtime"
                                        : "Camera search cancelled before a full 60-second window was analyzed",
                                    buildRuntimeDetails("cancelled")
                                );
                                return;
                            }

                            if (analyzedWindowCount <= 0) {
                                lastErrorForCamera = lastErrorForCamera.empty()
                                    ? "no 60-second video window could be analyzed for this camera"
                                    : lastErrorForCamera;
                                failedCameraCount.fetch_add(1);
                                postCameraEvent(
                                    "drakon_find_camera_failed",
                                    camera,
                                    "No 60-second video window could be analyzed for this camera",
                                    buildRuntimeDetails("failed")
                                );
                                return;
                            }

                            completedCameraCount.fetch_add(1);
                            if (cameraHitCount > 0) matchedCameraCount.fetch_add(1);

                            nlohmann::json completionDetails = buildRuntimeDetails("completed");
                            if (!lastSummary.empty()) completionDetails["summary"] = lastSummary;
                            postCameraEvent(
                                "drakon_find_camera_completed",
                                camera,
                                lastSummary.empty()
                                    ? "Configured duration finished for this camera."
                                    : lastSummary,
                                completionDetails
                            );
                        }
                        catch (const std::exception& e) {
                            logAgentException_(
                                sourceIdForCamera_(camera.cameraId),
                                "drakon_find",
                                "AgentCore::handleDrakonFindStartCommand_::cameraWorker",
                                "camera_runtime",
                                {
                                    { "search_id", searchId },
                                    { "target_id", targetId },
                                    { "camera_id", camera.cameraId },
                                    { "camera_name", camera.cameraName },
                                    { "runtime_mode", runtimeMode },
                                    { "input_type", inputType },
                                    { "attempt_count", attemptCount }
                                },
                                e
                            );
                            stopTemporarySessionIfSafe(camera, temporarySessionStarted, temporaryCfg);
                            lastErrorForCamera = e.what();
                            failedCameraCount.fetch_add(1);
                            postCameraEvent(
                                "drakon_find_camera_failed",
                                camera,
                                "Camera runtime failed on this EXE",
                                buildRuntimeDetails("failed")
                            );
                        }
                        catch (...) {
                            logAgentUnknownException_(
                                sourceIdForCamera_(camera.cameraId),
                                "drakon_find",
                                "AgentCore::handleDrakonFindStartCommand_::cameraWorker",
                                "camera_runtime",
                                {
                                    { "search_id", searchId },
                                    { "target_id", targetId },
                                    { "camera_id", camera.cameraId },
                                    { "camera_name", camera.cameraName },
                                    { "runtime_mode", runtimeMode },
                                    { "input_type", inputType },
                                    { "attempt_count", attemptCount }
                                }
                            );
                            stopTemporarySessionIfSafe(camera, temporarySessionStarted, temporaryCfg);
                            lastErrorForCamera = "unknown exception";
                            failedCameraCount.fetch_add(1);
                            postCameraEvent(
                                "drakon_find_camera_failed",
                                camera,
                                "Camera runtime failed on this EXE",
                                buildRuntimeDetails("failed")
                            );
                        }
                    });
                }

                for (auto& cameraWorker : cameraWorkers) {
                    if (cameraWorker.joinable()) {
                        cameraWorker.join();
                    }
                }

                const int processed = completedCameraCount.load();
                const int matches = matchedCameraCount.load();
                const int failures = failedCameraCount.load();
                const int cancelled = cancelledCameraCount.load();
                const bool wasCancelled = taskState->cancelRequested.load() || !running_;
                const bool allFailed = processed == 0 && failures > 0 && !wasCancelled;

                if (wasCancelled) {
                    postSearchEvent(
                        "drakon_find_search_cancelled",
                        "Drakon Find search cancelled",
                        {
                            { "processed_cameras", processed },
                            { "matched_cameras", matches },
                            { "failed_cameras", failures },
                            { "cancelled_cameras", cancelled },
                            { "runtime_mode", runtimeMode },
                            { "input_type", inputType },
                            { "window_seconds", windowSeconds },
                            { "duration_seconds", durationSeconds }
                        }
                    );
                }
                else if (allFailed) {
                    postSearchEvent(
                        "drakon_find_search_failed",
                        "Drakon Find search failed on all assigned cameras",
                        {
                            { "processed_cameras", processed },
                            { "matched_cameras", matches },
                            { "failed_cameras", failures },
                            { "cancelled_cameras", cancelled },
                            { "runtime_mode", runtimeMode },
                            { "input_type", inputType },
                            { "window_seconds", windowSeconds },
                            { "duration_seconds", durationSeconds }
                        }
                    );
                }
                else {
                    postSearchEvent(
                        "drakon_find_search_completed",
                        "Drakon Find search completed on this EXE",
                        {
                            { "processed_cameras", processed },
                            { "matched_cameras", matches },
                            { "failed_cameras", failures },
                            { "cancelled_cameras", cancelled },
                            { "runtime_mode", runtimeMode },
                            { "input_type", inputType },
                            { "window_seconds", windowSeconds },
                            { "duration_seconds", durationSeconds }
                        }
                    );
                }

                nlohmann::json result;
                result["search_id"] = searchId;
                result["status"] = wasCancelled ? "cancelled" : (allFailed ? "failed" : "completed");
                result["processed_cameras"] = processed;
                result["matched_cameras"] = matches;
                result["failed_cameras"] = failures;
                result["cancelled_cameras"] = cancelled;
                result["runtime_mode"] = runtimeMode;
                result["input_type"] = inputType;
                result["window_seconds"] = windowSeconds;
                result["duration_seconds"] = durationSeconds;
                result["prompt_tokens"] = totalPromptTokens.load();
                result["output_tokens"] = totalOutputTokens.load();
                result["total_tokens"] = totalTokens.load();
                if (commandId > 0) {
                    postCommandResult_(
                        commandId,
                        wasCancelled ? "completed" : (allFailed ? "failed" : "completed"),
                        result
                    );
                }
            }
            catch (const std::exception& e) {
                logAgentException_(
                    "agent",
                    "drakon_find",
                    "AgentCore::handleDrakonFindStartCommand_::searchWorker",
                    "search_runtime",
                    {
                        { "search_id", searchId },
                        { "target_id", targetId },
                        { "attempt_count", attemptCount },
                        { "runtime_mode", runtimeMode },
                        { "input_type", inputType }
                    },
                    e
                );
                for (auto& cameraWorker : cameraWorkers) {
                    if (cameraWorker.joinable()) {
                        cameraWorker.join();
                    }
                }
                postSearchEvent(
                    "drakon_find_search_failed",
                    "Drakon Find search crashed on the EXE",
                    { { "error", e.what() } }
                );
                if (commandId > 0) {
                    nlohmann::json err;
                    err["error"] = std::string("drakon_find_start exception: ") + e.what();
                    postCommandResult_(commandId, "failed", err);
                }
            }
            catch (...) {
                logAgentUnknownException_(
                    "agent",
                    "drakon_find",
                    "AgentCore::handleDrakonFindStartCommand_::searchWorker",
                    "search_runtime",
                    {
                        { "search_id", searchId },
                        { "target_id", targetId },
                        { "attempt_count", attemptCount },
                        { "runtime_mode", runtimeMode },
                        { "input_type", inputType }
                    }
                );
                for (auto& cameraWorker : cameraWorkers) {
                    if (cameraWorker.joinable()) {
                        cameraWorker.join();
                    }
                }
                postSearchEvent(
                    "drakon_find_search_failed",
                    "Drakon Find search crashed on the EXE",
                    { { "error", "unknown exception" } }
                );
                if (commandId > 0) {
                    nlohmann::json err;
                    err["error"] = "drakon_find_start unknown exception";
                    postCommandResult_(commandId, "failed", err);
                }
            }

            taskState->done = true;
        }
    );

    {
        std::lock_guard<std::mutex> lk(drakonFindMu_);
        drakonFindTasks_[searchId] = std::move(task);
    }
}

void AgentCore::handleCameraImportPreviewCommand_(
    int commandId,
    const nlohmann::json& payload)
{
    if (commandId <= 0) {
        Logger::instance().logDebug("agent", "handleCameraImportPreviewCommand_: missing command id");
        return;
    }

    auto fail = [&](const std::string& reason) {
        nlohmann::json err;
        err["error"] = reason;
        postCommandResult_(commandId, "failed", err);
    };

    try {
        if (!payload.contains("rows") || !payload["rows"].is_array()) {
            fail("rows is required");
            return;
        }

        const nlohmann::json& rowsJson = payload["rows"];
        if (rowsJson.empty()) {
            fail("rows is empty");
            return;
        }

        auto trimImport = [](const std::string& value) -> std::string {
            return trimAscii(value);
        };

        auto jsonStringOrImport = [&](const nlohmann::json& node, const char* key) -> std::string {
            if (!node.is_object() || !node.contains(key) || !node[key].is_string()) {
                return std::string();
            }
            return trimImport(node[key].get<std::string>());
        };

        auto jsonStringArrayOrImport = [&](const nlohmann::json& node, const char* key) {
            std::vector<std::string> values;
            if (!node.is_object() || !node.contains(key) || !node[key].is_array()) {
                return values;
            }
            for (const auto& item : node[key]) {
                if (!item.is_string()) continue;
                const std::string text = trimImport(item.get<std::string>());
                if (!text.empty()) {
                    values.push_back(text);
                }
            }
            return values;
        };

        auto toUpperImport = [](std::string value) -> std::string {
            for (auto& ch : value) {
                ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
            }
            return value;
        };

        auto normalizeConnectionMethod = [&](const std::string& value, bool& outDefaulted) {
            const std::string upper = toUpperImport(trimImport(value));
            if (upper == "HTTP" || upper == "ONVIF" || upper == "WEBCAM") {
                outDefaulted = false;
                return upper;
            }
            if (upper == "RTSP") {
                outDefaulted = false;
                return upper;
            }
            outDefaulted = true;
            return std::string("RTSP");
        };

        auto countryNameFromCode = [&](const std::string& code) {
            const std::string upper = toUpperImport(trimImport(code));
            static const std::unordered_map<std::string, std::string> kNames = {
                { "BR", "Brazil" },
                { "US", "United States" },
                { "CA", "Canada" },
                { "MX", "Mexico" },
                { "AR", "Argentina" },
                { "CL", "Chile" },
                { "CO", "Colombia" },
                { "PE", "Peru" },
                { "UY", "Uruguay" },
                { "PY", "Paraguay" },
                { "BO", "Bolivia" },
                { "PT", "Portugal" },
                { "ES", "Spain" },
                { "FR", "France" },
                { "DE", "Germany" },
                { "IT", "Italy" },
                { "GB", "United Kingdom" },
                { "IE", "Ireland" },
                { "AU", "Australia" },
                { "NZ", "New Zealand" },
                { "JP", "Japan" }
            };
            auto it = kNames.find(upper);
            if (it != kNames.end()) {
                return it->second;
            }
            return upper.empty() ? std::string("Imported placeholder country") : upper;
        };

        const std::string userCountryCode =
            toUpperImport(trimImport(payload.value("user_country_code", std::string("BR"))));

        std::map<int, nlohmann::json> sourceRowsByIndex;
        for (const auto& row : rowsJson) {
            if (!row.is_object()) continue;
            const int sourceIndex = row.value("source_index", -1);
            if (sourceIndex < 0) continue;
            sourceRowsByIndex[sourceIndex] = row;
        }
        if (sourceRowsByIndex.empty()) {
            fail("rows did not contain valid source_index values");
            return;
        }

        chatv2::LocalLlmRuntimeManager runtimeManager;
        if (!runtimeManager.ensureReady()) {
            fail("Local Qwen runtime unavailable: " + runtimeManager.lastError());
            return;
        }

        chatv2::LocalLlmClient llmClient;
        llmClient.setEndpointOverride(runtimeManager.baseUrl());

        auto buildCandidateFromModel = [&](const nlohmann::json& modelItem, const nlohmann::json& sourceRow) {
            const int sourceIndex = sourceRow.value("source_index", -1);
            const std::string sourceReference = sourceRow.value("source_reference", std::string());
            nlohmann::json candidate = nlohmann::json::object();
            candidate["source_index"] = sourceIndex;
            candidate["source_reference"] = sourceReference;
            candidate["source_sheet_name"] =
                sourceRow.contains("source_sheet_name") ? sourceRow["source_sheet_name"] : nlohmann::json();
            candidate["source_row_number"] =
                sourceRow.contains("source_row_number") ? sourceRow["source_row_number"] : nlohmann::json();
            candidate["source_values"] =
                sourceRow.contains("values") && sourceRow["values"].is_object()
                    ? sourceRow["values"]
                    : nlohmann::json::object();

            candidate["name"] = jsonStringOrImport(modelItem, "name");
            candidate["ip_address"] = jsonStringOrImport(modelItem, "ip_address");
            candidate["rtsp_port"] = jsonStringOrImport(modelItem, "rtsp_port");
            candidate["manufacturer"] = jsonStringOrImport(modelItem, "manufacturer");
            candidate["username"] = jsonStringOrImport(modelItem, "username");
            candidate["password"] = jsonStringOrImport(modelItem, "password");
            candidate["channel"] = jsonStringOrImport(modelItem, "channel");
            candidate["subtype"] = jsonStringOrImport(modelItem, "subtype");
            candidate["description"] = jsonStringOrImport(modelItem, "description");
            candidate["street"] = jsonStringOrImport(modelItem, "street");
            candidate["number"] = jsonStringOrImport(modelItem, "number");
            candidate["city"] = jsonStringOrImport(modelItem, "city");
            candidate["state"] = jsonStringOrImport(modelItem, "state");
            candidate["zip_code"] = jsonStringOrImport(modelItem, "zip_code");
            candidate["country"] = jsonStringOrImport(modelItem, "country");

            std::vector<std::string> defaultedFields = jsonStringArrayOrImport(modelItem, "defaulted_fields");
            std::vector<std::string> warnings = jsonStringArrayOrImport(modelItem, "warnings");

            bool connectionDefaulted = false;
            const std::string normalizedConnectionMethod = normalizeConnectionMethod(
                jsonStringOrImport(modelItem, "connection_method"),
                connectionDefaulted);
            candidate["connection_method"] = normalizedConnectionMethod;
            if (connectionDefaulted) {
                defaultedFields.push_back("connection_method");
            }

            if (candidate["rtsp_port"].get<std::string>().empty()) {
                candidate["rtsp_port"] = "554";
                defaultedFields.push_back("rtsp_port");
            }

            if (candidate["name"].get<std::string>().empty()) {
                const std::string ipValue = candidate["ip_address"].get<std::string>();
                if (!ipValue.empty()) {
                    candidate["name"] = "Imported camera " + ipValue;
                }
                else {
                    candidate["name"] = "Imported camera " + std::to_string(sourceIndex + 1);
                }
                defaultedFields.push_back("name");
            }

            bool addressDefaulted = false;
            auto ensureAddressField = [&](const char* key, const std::string& value) {
                if (!candidate[key].is_string() || candidate[key].get<std::string>().empty()) {
                    candidate[key] = value;
                    defaultedFields.push_back(key);
                    addressDefaulted = true;
                }
            };
            ensureAddressField("street", "Imported placeholder street");
            ensureAddressField("number", std::to_string(1000 + sourceIndex + 1));
            ensureAddressField("city", "Imported placeholder city " + std::to_string(sourceIndex + 1));
            ensureAddressField("state", "Imported placeholder state");
            ensureAddressField("zip_code", "00000-" + std::to_string(100 + sourceIndex + 1));
            ensureAddressField("country", countryNameFromCode(userCountryCode));
            candidate["address_was_defaulted"] = addressDefaulted;
            if (addressDefaulted) {
                warnings.push_back(
                    "Address was missing or incomplete, so a placeholder address was generated."
                );
            }

            nlohmann::json missingFields = nlohmann::json::array();
            if (candidate["ip_address"].get<std::string>().empty()) {
                missingFields.push_back("ip_address");
            }
            if (candidate["username"].get<std::string>().empty()) {
                missingFields.push_back("username");
            }
            if (candidate["password"].get<std::string>().empty()) {
                missingFields.push_back("password");
            }
            if (candidate["manufacturer"].get<std::string>().empty()) {
                missingFields.push_back("manufacturer");
            }

            std::sort(defaultedFields.begin(), defaultedFields.end());
            defaultedFields.erase(
                std::unique(defaultedFields.begin(), defaultedFields.end()),
                defaultedFields.end());
            std::sort(warnings.begin(), warnings.end());
            warnings.erase(
                std::unique(warnings.begin(), warnings.end()),
                warnings.end());

            candidate["missing_fields"] = missingFields;
            candidate["defaulted_fields"] = defaultedFields;
            candidate["warnings"] = warnings;
            candidate["can_create"] = missingFields.empty();
            return candidate;
        };

        auto buildFallbackCandidate = [&](const nlohmann::json& sourceRow, const std::string& warning) {
            nlohmann::json item = nlohmann::json::object();
            item["warnings"] = nlohmann::json::array({ warning });
            return buildCandidateFromModel(item, sourceRow);
        };

        std::map<int, nlohmann::json> candidatesByIndex;
        const std::size_t chunkSize = 12;
        std::vector<int> sourceIndices;
        sourceIndices.reserve(sourceRowsByIndex.size());
        for (const auto& entry : sourceRowsByIndex) {
            sourceIndices.push_back(entry.first);
        }

        nlohmann::json globalWarnings = nlohmann::json::array();
        if (payload.contains("global_warnings") && payload["global_warnings"].is_array()) {
            for (const auto& warning : payload["global_warnings"]) {
                if (!warning.is_string()) continue;
                const std::string text = trimImport(warning.get<std::string>());
                if (!text.empty()) {
                    globalWarnings.push_back(text);
                }
            }
        }

        for (std::size_t offset = 0; offset < sourceIndices.size(); offset += chunkSize) {
            const std::size_t limit = (std::min)(sourceIndices.size(), offset + chunkSize);
            nlohmann::json chunkRows = nlohmann::json::array();
            for (std::size_t index = offset; index < limit; ++index) {
                chunkRows.push_back(sourceRowsByIndex[sourceIndices[index]]);
            }

            std::ostringstream systemPrompt;
            systemPrompt
                << "You normalize heterogeneous camera import rows into canonical CCTV camera records.\n"
                << "Return valid JSON only.\n"
                << "Never invent ip_address, username, password, or manufacturer if they are not present.\n"
                << "You may infer name from context and default rtsp_port to 554 when an IP camera row exists.\n"
                << "Default connection_method to RTSP unless the row explicitly indicates HTTP or ONVIF.\n"
                << "If an RTSP/HTTP URL is present, extract ip_address, port, username, and password when visible.\n"
                << "Address fields are optional. If the row does not contain an address, leave the address fields empty.\n"
                << "Output schema:\n"
                << "{\n"
                << "  \"candidates\": [\n"
                << "    {\n"
                << "      \"source_index\": 0,\n"
                << "      \"name\": \"\",\n"
                << "      \"ip_address\": \"\",\n"
                << "      \"rtsp_port\": \"\",\n"
                << "      \"manufacturer\": \"\",\n"
                << "      \"username\": \"\",\n"
                << "      \"password\": \"\",\n"
                << "      \"channel\": \"\",\n"
                << "      \"subtype\": \"\",\n"
                << "      \"connection_method\": \"RTSP\",\n"
                << "      \"description\": \"\",\n"
                << "      \"street\": \"\",\n"
                << "      \"number\": \"\",\n"
                << "      \"city\": \"\",\n"
                << "      \"state\": \"\",\n"
                << "      \"zip_code\": \"\",\n"
                << "      \"country\": \"\",\n"
                << "      \"defaulted_fields\": [],\n"
                << "      \"warnings\": []\n"
                << "    }\n"
                << "  ]\n"
                << "}\n";

            std::ostringstream userPrompt;
            userPrompt
                << "Normalize the following camera import rows.\n"
                << "Rows may come from Excel, Google Sheets exports, CSV, JSON, or free text.\n"
                << "Keep one candidate per input row and preserve source_index.\n"
                << "If a row is not a camera, return empty fields and add a warning.\n"
                << "Rows JSON:\n"
                << chunkRows.dump(2);

            const auto outcome = llmClient.completeText(
                "camera_import_preview",
                systemPrompt.str(),
                userPrompt.str(),
                0.1,
                2200,
                60000,
                1,
                true
            );

            if (!outcome.ok || trimImport(outcome.content).empty()) {
                globalWarnings.push_back(
                    "One or more row groups could not be normalized by the local model. Empty preview rows were returned for those items."
                );
                for (std::size_t index = offset; index < limit; ++index) {
                    const int sourceIndex = sourceIndices[index];
                    candidatesByIndex[sourceIndex] = buildFallbackCandidate(
                        sourceRowsByIndex[sourceIndex],
                        "Local AI extraction failed for this row group."
                    );
                }
                continue;
            }

            std::string jsonSlice = outcome.content;
            if (!tryExtractJsonObjectSlice(jsonSlice, jsonSlice)) {
                globalWarnings.push_back(
                    "The local model returned malformed JSON for one row group. Empty preview rows were returned for those items."
                );
                for (std::size_t index = offset; index < limit; ++index) {
                    const int sourceIndex = sourceIndices[index];
                    candidatesByIndex[sourceIndex] = buildFallbackCandidate(
                        sourceRowsByIndex[sourceIndex],
                        "Local AI returned malformed JSON for this row group."
                    );
                }
                continue;
            }

            const nlohmann::json parsed = nlohmann::json::parse(jsonSlice, nullptr, false);
            if (!parsed.is_object() || !parsed.contains("candidates") || !parsed["candidates"].is_array()) {
                globalWarnings.push_back(
                    "The local model returned an unexpected object for one row group. Empty preview rows were returned for those items."
                );
                for (std::size_t index = offset; index < limit; ++index) {
                    const int sourceIndex = sourceIndices[index];
                    candidatesByIndex[sourceIndex] = buildFallbackCandidate(
                        sourceRowsByIndex[sourceIndex],
                        "Local AI returned an unexpected schema for this row group."
                    );
                }
                continue;
            }

            std::unordered_set<int> seenInChunk;
            for (const auto& modelItem : parsed["candidates"]) {
                if (!modelItem.is_object()) continue;
                const int sourceIndex = modelItem.value("source_index", -1);
                auto sourceIt = sourceRowsByIndex.find(sourceIndex);
                if (sourceIndex < 0 || sourceIt == sourceRowsByIndex.end()) {
                    continue;
                }
                candidatesByIndex[sourceIndex] = buildCandidateFromModel(modelItem, sourceIt->second);
                seenInChunk.insert(sourceIndex);
            }

            for (std::size_t index = offset; index < limit; ++index) {
                const int sourceIndex = sourceIndices[index];
                if (seenInChunk.count(sourceIndex)) continue;
                candidatesByIndex[sourceIndex] = buildFallbackCandidate(
                    sourceRowsByIndex[sourceIndex],
                    "The local AI did not return a candidate for this row."
                );
            }
        }

        nlohmann::json candidates = nlohmann::json::array();
        nlohmann::json missingFieldSummary = nlohmann::json::object();
        int readyCount = 0;
        int incompleteCount = 0;
        int defaultedAddressCount = 0;

        for (const auto& entry : sourceRowsByIndex) {
            const int sourceIndex = entry.first;
            auto candidateIt = candidatesByIndex.find(sourceIndex);
            if (candidateIt == candidatesByIndex.end()) {
                candidateIt = candidatesByIndex.emplace(
                    sourceIndex,
                    buildFallbackCandidate(entry.second, "No preview candidate was generated for this row.")
                ).first;
            }

            const nlohmann::json& candidate = candidateIt->second;
            candidates.push_back(candidate);
            if (candidate.value("can_create", false)) {
                readyCount += 1;
            }
            else {
                incompleteCount += 1;
            }
            if (candidate.value("address_was_defaulted", false)) {
                defaultedAddressCount += 1;
            }
            if (candidate.contains("missing_fields") && candidate["missing_fields"].is_array()) {
                for (const auto& missing : candidate["missing_fields"]) {
                    if (!missing.is_string()) continue;
                    const std::string key = missing.get<std::string>();
                    if (key.empty()) continue;
                    if (!missingFieldSummary.contains(key) || !missingFieldSummary[key].is_number_integer()) {
                        missingFieldSummary[key] = 0;
                    }
                    missingFieldSummary[key] = missingFieldSummary[key].get<int>() + 1;
                }
            }
        }

        nlohmann::json preview = nlohmann::json::object();
        preview["file_name"] = payload.value("file_name", std::string());
        preview["file_extension"] = payload.value("file_extension", std::string());
        preview["source_format"] = payload.value("source_format", std::string("unknown"));
        preview["total_rows_detected"] = payload.value("total_rows_detected", static_cast<int>(sourceRowsByIndex.size()));
        preview["rows_sent_to_llm"] = static_cast<int>(sourceRowsByIndex.size());
        preview["ready_count"] = readyCount;
        preview["incomplete_count"] = incompleteCount;
        preview["defaulted_address_count"] = defaultedAddressCount;
        preview["skipped_count"] = 0;
        preview["global_warnings"] = globalWarnings;
        preview["missing_field_summary"] = missingFieldSummary;
        preview["candidates"] = candidates;

        nlohmann::json result = nlohmann::json::object();
        result["preview"] = preview;
        postCommandResult_(commandId, "completed", result);
    }
    catch (const std::exception& e) {
        fail(std::string("camera_import_preview failed: ") + e.what());
    }
    catch (...) {
        fail("camera_import_preview failed with unknown error");
    }
}

void AgentCore::handleRefreshThumbnailCommand_(
    int commandId,
    const nlohmann::json& payload)
{
    if (commandId <= 0) {
        Logger::instance().logDebug("agent", "handleRefreshThumbnailCommand_: missing command id");
        return;
    }

    auto fail = [&](const std::string& reason) {
        nlohmann::json err;
        err["error"] = reason;
        postCommandResult_(commandId, "failed", err);
    };

    try {
        const int cameraId = payload.value("camera_id", -1);
        if (cameraId <= 0) {
            fail("camera_id is required");
            return;
        }

        int warmupSeconds = 4;
        int targetSecond = 3;
        int maxCaptureSeconds = 8;
        bool requireSnapshot = true;

        if (payload.contains("snapshot_strategy") && payload["snapshot_strategy"].is_object()) {
            const auto& strategy = payload["snapshot_strategy"];
            warmupSeconds = jsonIntOrPromptEnhance(strategy, "warmup_seconds", warmupSeconds);
            targetSecond = jsonIntOrPromptEnhance(strategy, "target_second", targetSecond);
            maxCaptureSeconds =
                jsonIntOrPromptEnhance(strategy, "max_capture_seconds", maxCaptureSeconds);
            if (strategy.contains("require_snapshot") && strategy["require_snapshot"].is_boolean()) {
                requireSnapshot = strategy["require_snapshot"].get<bool>();
            }
        }

        if (warmupSeconds < 2) warmupSeconds = 2;
        if (maxCaptureSeconds < warmupSeconds) maxCaptureSeconds = warmupSeconds;
        if (maxCaptureSeconds < 2) maxCaptureSeconds = 2;
        if (targetSecond < 0) targetSecond = 0;
        if (targetSecond >= maxCaptureSeconds) targetSecond = (std::max)(0, maxCaptureSeconds - 1);

        std::string snapshotDataUrl;
        std::string snapshotTsUtcIso;
        std::string snapshotSource;

        {
            CameraSession* session = getCameraSession(cameraId);
            if (session) {
                snapshotDataUrl = trimCopyPromptEnhance(session->getLastJobStillJpegBase64());
                snapshotTsUtcIso = trimCopyPromptEnhance(session->getLastJobStillTsUtcIso());
                if (!snapshotDataUrl.empty()) {
                    if (snapshotDataUrl.rfind("data:image", 0) != 0) {
                        snapshotDataUrl = "data:image/jpeg;base64," + stripDataUrlPrefix(snapshotDataUrl);
                    }
                    snapshotSource = "running_session";
                }
            }
        }

        if (snapshotDataUrl.empty()) {
            if (!payload.contains("camera_payload") || !payload["camera_payload"].is_object()) {
                fail("snapshot required, but camera_payload is missing");
                return;
            }

            const auto& cameraPayload = payload["camera_payload"];
            const int webcamIndex = jsonIntOrPromptEnhance(cameraPayload, "webcam_index", -1);
            std::string connectionMethod;
            if (cameraPayload.contains("connection_method") &&
                cameraPayload["connection_method"].is_string())
            {
                connectionMethod = toLowerCopyPromptEnhance(
                    trimCopyPromptEnhance(cameraPayload["connection_method"].get<std::string>())
                );
            }
            const bool preferWebcam = (webcamIndex >= 0) || connectionMethod == "webcam";

            cv::Mat capturedFrame;
            std::string captureError;
            bool captured = false;

            if (preferWebcam && webcamIndex >= 0) {
                captured = captureStableWebcamSnapshotPromptEnhance(
                    webcamIndex,
                    targetSecond,
                    maxCaptureSeconds,
                    capturedFrame,
                    captureError
                );
                if (captured) {
                    snapshotSource = "on_demand_webcam";
                }
            }

            if (!captured) {
                captured = captureStableRtspSnapshotPromptEnhance(
                    cameraPayload,
                    targetSecond,
                    maxCaptureSeconds,
                    capturedFrame,
                    captureError
                );
                if (captured) {
                    snapshotSource = "on_demand_rtsp";
                }
            }

            if (!captured || capturedFrame.empty()) {
                fail(
                    "snapshot capture failed: " +
                    (captureError.empty() ? std::string("no valid frame captured") : captureError)
                );
                return;
            }

            if (!encodeJpegDataUrlForPromptEnhance(capturedFrame, snapshotDataUrl)) {
                fail("failed to encode snapshot");
                return;
            }

            snapshotTsUtcIso = nowUtcIso8601PromptEnhance();
        }

        if (snapshotDataUrl.empty() && requireSnapshot) {
            fail("snapshot is empty");
            return;
        }

        if (snapshotTsUtcIso.empty()) {
            snapshotTsUtcIso = nowUtcIso8601PromptEnhance();
        }
        if (snapshotSource.empty()) {
            snapshotSource = "unknown";
        }

        sendThumbnail(std::to_string(cameraId), snapshotDataUrl);

        nlohmann::json result;
        result["camera_id"] = cameraId;
        result["snapshot_source"] = snapshotSource;
        result["snapshot_ts_utc_iso"] = snapshotTsUtcIso;
        result["thumbnail_refresh_requested"] = true;

        postCommandResult_(commandId, "completed", result);
    }
    catch (const std::exception& e) {
        fail(std::string("refresh_thumbnail failed: ") + e.what());
    }
    catch (...) {
        fail("refresh_thumbnail failed with unknown error");
    }
}

void AgentCore::handlePromptEnhanceCommand_(int commandId, const nlohmann::json& payload)
{
    if (commandId <= 0) {
        Logger::instance().logDebug("agent", "handlePromptEnhanceCommand_: missing command id");
        return;
    }

    auto fail = [&](const std::string& reason) {
        nlohmann::json err;
        err["error"] = reason;
        postCommandResult_(commandId, "failed", err);
    };

    try {
        const int cameraId = payload.value("camera_id", -1);
        if (cameraId <= 0) {
            fail("camera_id is required");
            return;
        }

        std::string promptCore = payload.value("prompt_core", std::string());
        std::string alertCondition = payload.value("alert_condition", std::string());
        std::string negativeCondition = payload.value("negative_condition", std::string());
        std::string languageHint = payload.value("user_language", std::string("pt-BR"));
        std::string modelName = payload.value("model_name", std::string("gpt-5.1"));
        std::string modelApiKey = payload.value("model_api_key", std::string());
        std::string cameraName = payload.value("camera_name", std::string());
        std::string cameraDescription = payload.value("camera_description", std::string());
        const std::vector<PromptEnhanceRegion_> overlayRegions =
            parsePromptEnhanceOverlayRegions_(payload);

        promptCore = trimCopyPromptEnhance(promptCore);
        alertCondition = trimCopyPromptEnhance(alertCondition);
        negativeCondition = trimCopyPromptEnhance(negativeCondition);
        languageHint = trimCopyPromptEnhance(languageHint);
        modelName = trimCopyPromptEnhance(modelName);
        modelApiKey = trimCopyPromptEnhance(modelApiKey);
        cameraName = trimCopyPromptEnhance(cameraName);
        cameraDescription = trimCopyPromptEnhance(cameraDescription);

        if (promptCore.empty()) {
            fail("prompt_core is required");
            return;
        }
        if (alertCondition.empty()) {
            fail("alert_condition is required");
            return;
        }
        if (modelApiKey.empty()) {
            fail("model_api_key is required");
            return;
        }
        if (modelName.empty()) {
            modelName = "gpt-5.1";
        }
        if (languageHint.empty()) {
            languageHint = "pt-BR";
        }

        int warmupSeconds = 6;
        int targetSecond = 5;
        int maxCaptureSeconds = 12;
        bool requireSnapshot = true;

        if (payload.contains("snapshot_strategy") && payload["snapshot_strategy"].is_object()) {
            const auto& strategy = payload["snapshot_strategy"];
            warmupSeconds = jsonIntOrPromptEnhance(strategy, "warmup_seconds", warmupSeconds);
            targetSecond = jsonIntOrPromptEnhance(strategy, "target_second", targetSecond);
            maxCaptureSeconds = jsonIntOrPromptEnhance(strategy, "max_capture_seconds", maxCaptureSeconds);
            if (strategy.contains("require_snapshot") && strategy["require_snapshot"].is_boolean()) {
                requireSnapshot = strategy["require_snapshot"].get<bool>();
            }
        }

        if (warmupSeconds < 2) warmupSeconds = 2;
        if (maxCaptureSeconds < warmupSeconds) maxCaptureSeconds = warmupSeconds;
        if (maxCaptureSeconds < 2) maxCaptureSeconds = 2;
        if (targetSecond < 0) targetSecond = 0;
        if (targetSecond >= maxCaptureSeconds) targetSecond = (std::max)(0, maxCaptureSeconds - 1);

        std::string snapshotDataUrl;
        std::string snapshotTsUtcIso;
        std::string snapshotSource;

        {
            CameraSession* session = getCameraSession(cameraId);
            if (session) {
                snapshotDataUrl = trimCopyPromptEnhance(session->getLastJobStillJpegBase64());
                snapshotTsUtcIso = trimCopyPromptEnhance(session->getLastJobStillTsUtcIso());
                if (!snapshotDataUrl.empty()) {
                    if (snapshotDataUrl.rfind("data:image", 0) != 0) {
                        snapshotDataUrl = "data:image/jpeg;base64," + stripDataUrlPrefix(snapshotDataUrl);
                    }
                    snapshotSource = "running_session";
                }
            }
        }

        if (snapshotDataUrl.empty()) {
            if (!payload.contains("camera_payload") || !payload["camera_payload"].is_object()) {
                fail("snapshot required (fallback A), but camera_payload is missing");
                return;
            }

            const auto& cameraPayload = payload["camera_payload"];
            if (cameraName.empty() && cameraPayload.contains("name") && cameraPayload["name"].is_string()) {
                cameraName = trimCopyPromptEnhance(cameraPayload["name"].get<std::string>());
            }
            if (cameraDescription.empty() &&
                cameraPayload.contains("description") &&
                cameraPayload["description"].is_string())
            {
                cameraDescription = trimCopyPromptEnhance(cameraPayload["description"].get<std::string>());
            }

            const int webcamIndex = jsonIntOrPromptEnhance(cameraPayload, "webcam_index", -1);
            std::string connectionMethod;
            if (cameraPayload.contains("connection_method") && cameraPayload["connection_method"].is_string()) {
                connectionMethod = toLowerCopyPromptEnhance(
                    trimCopyPromptEnhance(cameraPayload["connection_method"].get<std::string>())
                );
            }
            const bool preferWebcam = (webcamIndex >= 0) || connectionMethod == "webcam";

            cv::Mat capturedFrame;
            std::string captureError;
            bool captured = false;

            if (preferWebcam && webcamIndex >= 0) {
                captured = captureStableWebcamSnapshotPromptEnhance(
                    webcamIndex,
                    targetSecond,
                    maxCaptureSeconds,
                    capturedFrame,
                    captureError
                );
                if (captured) {
                    snapshotSource = "on_demand_webcam";
                }
            }

            if (!captured) {
                captured = captureStableRtspSnapshotPromptEnhance(
                    cameraPayload,
                    targetSecond,
                    maxCaptureSeconds,
                    capturedFrame,
                    captureError
                );
                if (captured) {
                    snapshotSource = "on_demand_rtsp";
                }
            }

            if (!captured || capturedFrame.empty()) {
                fail(
                    "snapshot required (fallback A), capture failed: " +
                    (captureError.empty() ? std::string("no valid frame captured") : captureError)
                );
                return;
            }

            if (!encodeJpegDataUrlForPromptEnhance(capturedFrame, snapshotDataUrl)) {
                fail("snapshot required (fallback A), failed to encode snapshot");
                return;
            }

            snapshotTsUtcIso = nowUtcIso8601PromptEnhance();
        }

        if (snapshotDataUrl.empty() && requireSnapshot) {
            fail("snapshot required (fallback A), but snapshot is empty");
            return;
        }

        if (snapshotTsUtcIso.empty()) {
            snapshotTsUtcIso = nowUtcIso8601PromptEnhance();
        }
        if (snapshotSource.empty()) {
            snapshotSource = "unknown";
        }

        int overlayRegionsDrawn = 0;
        if (!overlayRegions.empty()) {
            cv::Mat overlayFrame;
            std::string overlayErr;
            if (!decodePromptEnhanceSnapshotToMat_(snapshotDataUrl, overlayFrame, &overlayErr)) {
                fail(
                    "snapshot required (fallback A), failed to decode snapshot for polygon overlay: " +
                    (overlayErr.empty() ? std::string("invalid image data") : overlayErr)
                );
                return;
            }

            if (!drawPromptEnhanceRegionsOnFrame_(overlayFrame, overlayRegions, overlayRegionsDrawn)) {
                fail("snapshot required (fallback A), failed to draw polygon overlay");
                return;
            }

            if (overlayRegionsDrawn > 0) {
                if (!encodeJpegDataUrlForPromptEnhance(overlayFrame, snapshotDataUrl)) {
                    fail("snapshot required (fallback A), failed to encode snapshot with polygon overlay");
                    return;
                }
                snapshotSource += "+polygon_overlay";
                Logger::instance().logDebug(
                    "agent",
                    "handlePromptEnhanceCommand_: overlay regions drawn=" +
                    std::to_string(overlayRegionsDrawn) +
                    " camera_id=" + std::to_string(cameraId)
                );
            }
        }

        std::ostringstream prompt;
        prompt << "You are a CCTV prompt enhancement assistant.\n";
        prompt << "Your task is to improve the user's detection specification.\n\n";

        prompt << "INPUT FIELDS:\n";
        prompt << "1) prompt_core\n";
        prompt << "2) alert_condition\n";
        prompt << "3) negative_condition (optional)\n\n";

        prompt << "CURRENT VALUES:\n";
        prompt << "prompt_core:\n" << promptCore << "\n\n";
        prompt << "alert_condition:\n" << alertCondition << "\n\n";
        prompt << "negative_condition:\n"
               << (negativeCondition.empty() ? "(empty)" : negativeCondition) << "\n\n";

        if (!cameraName.empty() || !cameraDescription.empty()) {
            prompt << "CAMERA CONTEXT:\n";
            if (!cameraName.empty()) {
                prompt << "camera_name: " << cameraName << "\n";
            }
            if (!cameraDescription.empty()) {
                prompt << "camera_description: " << cameraDescription << "\n";
            }
            prompt << "\n";
        }

        prompt << "IMAGE CONTEXT:\n";
        prompt << "- You will receive ONE snapshot from the camera.\n";
        prompt << "- Use the visible context to reduce false positives.\n\n";
        if (overlayRegionsDrawn > 0) {
            prompt << "REGION OVERLAY CONTEXT:\n";
            prompt << "- Polygon overlays with labels are drawn directly on the snapshot.\n";
            prompt << "- Treat each polygon label as a named area of interest.\n";
            prompt << "- Use those labels when refining prompt_core / alert_condition / negative_condition.\n\n";
        }

        prompt << "MANDATORY RULES:\n";
        prompt << "- Respond in the same language as the user inputs.\n";
        prompt << "- Keep JSON field names in English.\n";
        prompt << "- Produce binary and testable conditions.\n";
        prompt << "- Avoid vague expressions.\n";
        prompt << "- Do not invent objects/areas not clearly visible.\n";
        prompt << "- Use snapshot context to reduce false positives.\n";
        prompt << "- If negative_condition is empty, you may propose one.\n";
        prompt << "- Output must be valid JSON only. No markdown.\n";
        prompt << "- prompt_template and alert_condition must be non-empty.\n\n";

        prompt << "OUTPUT FORMAT (EXACT KEYS):\n";
        prompt << "{\n";
        prompt << "  \"prompt_template\": \"...\",\n";
        prompt << "  \"alert_condition\": \"...\",\n";
        prompt << "  \"negative_condition\": \"...\"\n";
        prompt << "}\n\n";

        prompt << "Language hint from user: " << languageHint << "\n";

        nlohmann::json content = nlohmann::json::array();
        content.push_back({ { "type", "text" }, { "text", prompt.str() } });
        content.push_back(
            makeOpenAIImageContentFromBareJpeg(stripDataUrlPrefix(snapshotDataUrl), modelName)
        );

        nlohmann::json body = {
            { "model", modelName },
            { "messages", nlohmann::json::array({
                {
                    { "role", "user" },
                    { "content", content }
                }
            })}
        };
        applyOpenAITemperatureField_(body, modelName, 0.1);
        applyOpenAITokenLimitField_(body, modelName, 1400);

        std::string rawResp;
        try {
            rawResp = postOpenAIChatCompletionsWithCoreLease_(
                modelApiKey,
                body,
                []() { MaybeNotifyFirstRetry(); },
                false,
                {},
                "prompt_enhance"
            );
        }
        catch (const std::exception& e) {
            fail(std::string("OpenAI enhancement request failed: ") + e.what());
            return;
        }

        nlohmann::json respJson = nlohmann::json::parse(rawResp, nullptr, false);
        if (respJson.is_discarded() || !respJson.is_object()) {
            fail("OpenAI enhancement returned invalid JSON response");
            return;
        }

        std::string text = extractOpenAITextFromResponse(respJson);
        if (text.empty()) {
            fail("OpenAI enhancement returned empty text");
            return;
        }

        std::string jsonSlice;
        if (!tryExtractJsonObjectSlice(text, jsonSlice)) {
            fail("OpenAI enhancement did not return a JSON object");
            return;
        }

        nlohmann::json enhanced = nlohmann::json::parse(jsonSlice, nullptr, false);
        if (!enhanced.is_object()) {
            fail("OpenAI enhancement returned malformed JSON object");
            return;
        }

        auto getTextField = [&](const char* key) -> std::string {
            if (enhanced.contains(key) && enhanced[key].is_string()) {
                return trimCopyPromptEnhance(enhanced[key].get<std::string>());
            }
            return std::string();
        };

        std::string enhancedPrompt = getTextField("prompt_template");
        if (enhancedPrompt.empty()) {
            enhancedPrompt = getTextField("prompt_core");
        }
        if (enhancedPrompt.empty()) {
            enhancedPrompt = getTextField("prompt");
        }

        std::string enhancedAlert = getTextField("alert_condition");
        std::string enhancedNegative = getTextField("negative_condition");

        if (enhancedPrompt.empty() || enhancedAlert.empty()) {
            fail("OpenAI enhancement returned empty required fields");
            return;
        }

        nlohmann::json result;
        result["suggestion"] = {
            { "prompt_template", enhancedPrompt },
            { "alert_condition", enhancedAlert },
            { "negative_condition", enhancedNegative }
        };
        result["model_name"] = modelName;
        result["snapshot_source"] = snapshotSource;
        result["snapshot_ts_utc_iso"] = snapshotTsUtcIso;
        result["fallback_option"] = "A";

        postCommandResult_(commandId, "completed", result);
    }
    catch (const std::exception& e) {
        fail(std::string("prompt_enhance failed: ") + e.what());
    }
    catch (...) {
        fail("prompt_enhance failed with unknown error");
    }
}

void AgentCore::handleAgentDesignCommand_(int commandId, const nlohmann::json& payload)
{
    if (commandId <= 0) {
        Logger::instance().logDebug("agent", "handleAgentDesignCommand_: missing command id");
        return;
    }

    auto fail = [&](const std::string& reason) {
        nlohmann::json err;
        err["error"] = reason;
        postCommandResult_(commandId, "failed", err);
    };

    try {
        const int cameraId = payload.value("camera_id", -1);
        std::string goalSummary = payload.value("goal_summary", std::string());
        std::string languageHint = payload.value("user_language", std::string("pt-BR"));
        std::string modelName = payload.value("model_name", std::string("gpt-5.1"));
        std::string modelApiKey = payload.value("model_api_key", std::string());
        std::string cameraName = payload.value("camera_name", std::string());
        std::string cameraDescription = payload.value("camera_description", std::string());
        const nlohmann::json agentPatch =
            payload.contains("agent_patch") && payload["agent_patch"].is_object()
                ? payload["agent_patch"]
                : nlohmann::json::object();
        const nlohmann::json faceTargets =
            payload.contains("face_targets") && payload["face_targets"].is_array()
                ? payload["face_targets"]
                : nlohmann::json::array();
        const nlohmann::json drakonFindTargets =
            payload.contains("drakon_find_targets") && payload["drakon_find_targets"].is_array()
                ? payload["drakon_find_targets"]
                : nlohmann::json::array();
        const nlohmann::json designContext =
            payload.contains("design_context") && payload["design_context"].is_object()
                ? payload["design_context"]
                : nlohmann::json::object();

        goalSummary = trimCopyPromptEnhance(goalSummary);
        languageHint = trimCopyPromptEnhance(languageHint);
        modelName = trimCopyPromptEnhance(modelName);
        modelApiKey = trimCopyPromptEnhance(modelApiKey);
        cameraName = trimCopyPromptEnhance(cameraName);
        cameraDescription = trimCopyPromptEnhance(cameraDescription);

        if (goalSummary.empty()) {
            fail("goal_summary is required");
            return;
        }
        if (modelApiKey.empty()) {
            fail("model_api_key is required");
            return;
        }
        if (modelName.empty()) {
            modelName = "gpt-5.1";
        }
        if (languageHint.empty()) {
            languageHint = "pt-BR";
        }

        auto jsonTextField = [](const nlohmann::json& node, const char* key) -> std::string {
            if (!node.is_object() || !node.contains(key) || !node[key].is_string()) {
                return std::string();
            }
            return trimCopyPromptEnhance(node[key].get<std::string>());
        };

        auto jsonBoolField = [&](const nlohmann::json& node, const char* key, bool fallback) -> bool {
            if (!node.is_object() || !node.contains(key)) {
                return fallback;
            }
            const auto& value = node[key];
            if (value.is_boolean()) {
                return value.get<bool>();
            }
            if (value.is_number_integer()) {
                return value.get<int>() != 0;
            }
            if (value.is_string()) {
                const std::string lower =
                    toLowerCopyPromptEnhance(trimCopyPromptEnhance(value.get<std::string>()));
                if (lower == "1" || lower == "true" || lower == "yes" || lower == "on") {
                    return true;
                }
                if (lower == "0" || lower == "false" || lower == "no" || lower == "off") {
                    return false;
                }
            }
            return fallback;
        };

        auto jsonIntField = [&](const nlohmann::json& node, const char* key, int fallback) -> int {
            if (!node.is_object() || !node.contains(key)) {
                return fallback;
            }
            const auto& value = node[key];
            if (value.is_number_integer()) {
                return value.get<int>();
            }
            if (value.is_number()) {
                return static_cast<int>(value.get<double>());
            }
            if (value.is_string()) {
                try {
                    return std::stoi(trimCopyPromptEnhance(value.get<std::string>()));
                }
                catch (...) {
                }
            }
            return fallback;
        };

        auto normalizeInputType = [](std::string value) {
            value = toLowerCopyPromptEnhance(trimCopyPromptEnhance(std::move(value)));
            return value == "image" ? std::string("image") : std::string("video");
        };

        auto normalizeVideoPackagingMode = [](std::string value) {
            value = toLowerCopyPromptEnhance(trimCopyPromptEnhance(std::move(value)));
            if (value == "frame_sequence" ||
                value == "frame-sequence" ||
                value == "frames" ||
                value == "full_frame" ||
                value == "full-frame" ||
                value == "high_resolution" ||
                value == "high-resolution" ||
                value == "high resolution") {
                return std::string("frame_sequence");
            }
            if (value == "mosaic_3x3" ||
                value == "mosaic-3x3" ||
                value == "mosaic" ||
                value == "3x3" ||
                value == "compact_resolution" ||
                value == "compact-resolution" ||
                value == "compact resolution") {
                // Deprecated: 3x3 mosaics underperform for detail-heavy chat video analysis.
                return std::string("frame_sequence");
            }
            return std::string("frame_sequence");
        };

        auto normalizeInferenceModel = [](std::string value) {
            value = toLowerCopyPromptEnhance(trimCopyPromptEnhance(std::move(value)));
            if (value == "ultra+" || value == "ultra-plus" || value == "ultraplus") {
                return std::string("ultra_plus");
            }
            if (value == "core" ||
                value == "light" ||
                value == "ultra" ||
                value == "ultra_plus" ||
                value == "legacy" ||
                value == "pro") {
                return value;
            }
            return std::string("ultra");
        };

        auto normalizeRunEvery = [&](const nlohmann::json& node) {
            const int requested = jsonIntField(node, "run_every", 60);
            return requested <= 10 ? 10 : 60;
        };

        auto normalizeRunningResolution = [&](const nlohmann::json& node) {
            const int requested = jsonIntField(node, "running_resolution", 640);
            return requested == 1024 ? 1024 : 640;
        };

        auto normalizeModelFps = [&](const nlohmann::json& node, const std::string& inputType) {
            int requested = jsonIntField(node, "model_fps", 1);
            if (requested < 1) requested = 1;
            if (requested > 10) requested = 10;
            if (inputType != "video") {
                return 1;
            }
            return requested;
        };

        auto clamp01 = [](double value) {
            if (value < 0.0) return 0.0;
            if (value > 1.0) return 1.0;
            return value;
        };

        int warmupSeconds = 6;
        int targetSecond = 5;
        int maxCaptureSeconds = 12;
        bool requireSnapshot = cameraId > 0;
        bool preferRunningSessionSnapshot = true;

        if (payload.contains("snapshot_strategy") && payload["snapshot_strategy"].is_object()) {
            const auto& strategy = payload["snapshot_strategy"];
            warmupSeconds = jsonIntOrPromptEnhance(strategy, "warmup_seconds", warmupSeconds);
            targetSecond = jsonIntOrPromptEnhance(strategy, "target_second", targetSecond);
            maxCaptureSeconds = jsonIntOrPromptEnhance(strategy, "max_capture_seconds", maxCaptureSeconds);
            if (strategy.contains("require_snapshot") && strategy["require_snapshot"].is_boolean()) {
                requireSnapshot = strategy["require_snapshot"].get<bool>();
            }
            if (strategy.contains("prefer_running_session_snapshot")) {
                preferRunningSessionSnapshot = jsonBoolField(
                    nlohmann::json::object({
                        { "value", strategy["prefer_running_session_snapshot"] },
                    }),
                    "value",
                    true);
            }
        }

        if (warmupSeconds < 2) warmupSeconds = 2;
        if (maxCaptureSeconds < warmupSeconds) maxCaptureSeconds = warmupSeconds;
        if (maxCaptureSeconds < 2) maxCaptureSeconds = 2;
        if (targetSecond < 0) targetSecond = 0;
        if (targetSecond >= maxCaptureSeconds) targetSecond = (std::max)(0, maxCaptureSeconds - 1);

        std::string snapshotDataUrl;
        std::string snapshotTsUtcIso;
        std::string snapshotSource;

        if (cameraId > 0 && preferRunningSessionSnapshot) {
            CameraSession* session = getCameraSession(cameraId);
            if (session) {
                snapshotDataUrl = trimCopyPromptEnhance(session->getLastJobStillJpegBase64());
                snapshotTsUtcIso = trimCopyPromptEnhance(session->getLastJobStillTsUtcIso());
                if (!snapshotDataUrl.empty()) {
                    if (snapshotDataUrl.rfind("data:image", 0) != 0) {
                        snapshotDataUrl = "data:image/jpeg;base64," + stripDataUrlPrefix(snapshotDataUrl);
                    }
                    snapshotSource = "running_session";
                }
            }
        }

        // If a fresh snapshot is optional, only reuse an already-running session snapshot.
        // Avoid blocking the design command on an on-demand capture path that can consume most
        // of the backend wait window and trigger avoidable timeouts.
        if (snapshotDataUrl.empty() && cameraId > 0 && requireSnapshot) {
            if (!payload.contains("camera_payload") || !payload["camera_payload"].is_object()) {
                if (requireSnapshot) {
                    fail("snapshot required, but camera_payload is missing");
                    return;
                }
            }
            else {
                const auto& cameraPayload = payload["camera_payload"];
                if (cameraName.empty() && cameraPayload.contains("name") && cameraPayload["name"].is_string()) {
                    cameraName = trimCopyPromptEnhance(cameraPayload["name"].get<std::string>());
                }
                if (cameraDescription.empty() &&
                    cameraPayload.contains("description") &&
                    cameraPayload["description"].is_string())
                {
                    cameraDescription = trimCopyPromptEnhance(cameraPayload["description"].get<std::string>());
                }

                const int webcamIndex = jsonIntOrPromptEnhance(cameraPayload, "webcam_index", -1);
                std::string connectionMethod;
                if (cameraPayload.contains("connection_method") && cameraPayload["connection_method"].is_string()) {
                    connectionMethod = toLowerCopyPromptEnhance(
                        trimCopyPromptEnhance(cameraPayload["connection_method"].get<std::string>())
                    );
                }
                const bool preferWebcam = (webcamIndex >= 0) || connectionMethod == "webcam";

                cv::Mat capturedFrame;
                std::string captureError;
                bool captured = false;

                if (preferWebcam && webcamIndex >= 0) {
                    captured = captureStableWebcamSnapshotPromptEnhance(
                        webcamIndex,
                        targetSecond,
                        maxCaptureSeconds,
                        capturedFrame,
                        captureError
                    );
                    if (captured) {
                        snapshotSource = "on_demand_webcam";
                    }
                }

                if (!captured) {
                    captured = captureStableRtspSnapshotPromptEnhance(
                        cameraPayload,
                        targetSecond,
                        maxCaptureSeconds,
                        capturedFrame,
                        captureError
                    );
                    if (captured) {
                        snapshotSource = "on_demand_rtsp";
                    }
                }

                if (!captured || capturedFrame.empty()) {
                    if (requireSnapshot) {
                        fail(
                            "snapshot required, capture failed: " +
                            (captureError.empty() ? std::string("no valid frame captured") : captureError)
                        );
                        return;
                    }
                }
                else {
                    if (!encodeJpegDataUrlForPromptEnhance(capturedFrame, snapshotDataUrl)) {
                        if (requireSnapshot) {
                            fail("snapshot required, failed to encode snapshot");
                            return;
                        }
                    }
                    else {
                        snapshotTsUtcIso = nowUtcIso8601PromptEnhance();
                    }
                }
            }
        }

        if (snapshotDataUrl.empty() && requireSnapshot) {
            fail("snapshot required, but snapshot is empty");
            return;
        }

        if (snapshotTsUtcIso.empty()) {
            snapshotTsUtcIso = nowUtcIso8601PromptEnhance();
        }
        if (snapshotSource.empty()) {
            snapshotSource = snapshotDataUrl.empty() ? "none" : "unknown";
        }

        auto sanitizeAnalysisRegions = [&](
            const nlohmann::json& rawRegions,
            const std::string& fallbackPrompt,
            const std::string& fallbackAlert,
            const std::string& fallbackNegative,
            bool allowPolygonOutput)
        {
            nlohmann::json normalized = nlohmann::json::array();
            if (!rawRegions.is_array()) {
                return normalized;
            }

            int regionIndex = 0;
            for (const auto& row : rawRegions) {
                if (!row.is_object()) {
                    continue;
                }

                bool fullFrame = jsonBoolField(row, "full_frame", false);
                if (!row.contains("full_frame") && row.contains("fullFrame")) {
                    fullFrame = jsonBoolField(
                        nlohmann::json::object({ { "value", row["fullFrame"] } }),
                        "value",
                        false);
                }

                const nlohmann::json* polygonNode = nullptr;
                if (row.contains("polygon_norm") && row["polygon_norm"].is_array()) {
                    polygonNode = &row["polygon_norm"];
                }
                else if (row.contains("polygonNorm") && row["polygonNorm"].is_array()) {
                    polygonNode = &row["polygonNorm"];
                }

                nlohmann::json polygon = nlohmann::json::array();
                if (allowPolygonOutput && polygonNode != nullptr) {
                    for (const auto& point : *polygonNode) {
                        if (!point.is_object()) {
                            continue;
                        }
                        const double x =
                            point.contains("x") && point["x"].is_number()
                                ? point["x"].get<double>()
                                : 0.0;
                        const double y =
                            point.contains("y") && point["y"].is_number()
                                ? point["y"].get<double>()
                                : 0.0;
                        polygon.push_back({
                            { "x", clamp01(x) },
                            { "y", clamp01(y) },
                        });
                    }
                }

                if (polygon.size() < 3) {
                    fullFrame = true;
                    polygon = nlohmann::json::array();
                }

                std::string regionId = jsonTextField(row, "region_id");
                if (regionId.empty()) {
                    regionId = jsonTextField(row, "regionId");
                }
                if (regionId.empty()) {
                    regionId = "region-" + std::to_string(regionIndex + 1);
                }

                std::string label = jsonTextField(row, "label");
                if (label.empty()) {
                    label = "Region " + std::to_string(regionIndex + 1);
                }

                std::string promptCore = jsonTextField(row, "prompt_core");
                if (promptCore.empty()) {
                    promptCore = jsonTextField(row, "prompt_template");
                }
                if (promptCore.empty()) {
                    promptCore = fallbackPrompt;
                }

                std::string regionAlert = jsonTextField(row, "alert_condition");
                if (regionAlert.empty()) {
                    regionAlert = fallbackAlert;
                }
                std::string regionNegative = jsonTextField(row, "negative_condition");
                if (regionNegative.empty()) {
                    regionNegative = fallbackNegative;
                }

                int drawRefWidth = jsonIntField(row, "draw_ref_width", 1920);
                if (drawRefWidth <= 0) drawRefWidth = 1920;
                int drawRefHeight = jsonIntField(row, "draw_ref_height", 1080);
                if (drawRefHeight <= 0) drawRefHeight = 1080;

                normalized.push_back({
                    { "region_id", regionId },
                    { "label", label },
                    { "description", jsonTextField(row, "description") },
                    { "enabled", jsonBoolField(row, "enabled", true) },
                    { "full_frame", fullFrame },
                    { "polygon_norm", polygon },
                    { "draw_ref_width", drawRefWidth },
                    { "draw_ref_height", drawRefHeight },
                    { "context_padding_pct", 0 },
                    { "prompt_core", promptCore },
                    { "alert_condition", regionAlert },
                    { "negative_condition", regionNegative },
                    { "face_target_ids", nlohmann::json::array() },
                    { "negative_image_ids", nlohmann::json::array() },
                });

                ++regionIndex;
                if (regionIndex >= 6) {
                    break;
                }
            }

            return normalized;
        };

        std::ostringstream prompt;
        prompt << "You design CCTV camera agents from a user's goal, optional explicit preferences, optional camera context, optional snapshot context, and optional known identity or search targets.\n";
        prompt << "The user wants a complete agent configuration that can be created directly in the app.\n\n";
        prompt << "PRIMARY GOAL:\n" << goalSummary << "\n\n";

        if (!cameraName.empty() || !cameraDescription.empty()) {
            prompt << "CAMERA CONTEXT:\n";
            if (!cameraName.empty()) {
                prompt << "camera_name: " << cameraName << "\n";
            }
            if (!cameraDescription.empty()) {
                prompt << "camera_description: " << cameraDescription << "\n";
            }
            prompt << "\n";
        }

        if (agentPatch.is_object() && !agentPatch.empty()) {
            prompt << "EXPLICIT USER PREFERENCES (preserve these when compatible):\n";
            prompt << agentPatch.dump(2) << "\n\n";
        }

        if (designContext.is_object() && !designContext.empty()) {
            prompt << "STRUCTURED EXECUTION CONTEXT:\n";
            prompt << designContext.dump(2) << "\n";
            prompt << "- Respect alert_policy.\n";
            prompt << "- If alert_policy is \"never\", design this as an analysis-only agent that keeps alert_condition false and focuses on structured evidence.\n";
            prompt << "- If alert_policy is \"final_decision_only\", only let alert_condition become true when this step is clearly the decision layer.\n";
            prompt << "- If output_contract is present, make prompt_template instruct the model to return that contract as compact JSON with no markdown.\n";
            prompt << "- If knowledge_inputs or pipeline semantics are present, instruct the downstream agent to use PIPELINE_INPUTS as the primary source when relevant.\n";
            prompt << "- Align the behavior with the step role when the context says collector, validator, or decision.\n\n";
        }

        if (faceTargets.is_array() && !faceTargets.empty()) {
            prompt << "KNOWN FACE TARGETS AVAILABLE TO THE USER:\n";
            prompt << faceTargets.dump(2) << "\n";
            prompt << "- If the goal clearly references one of these identities, tailor the design for that identity.\n";
            prompt << "- Do not invent new face identities.\n\n";
        }

        if (drakonFindTargets.is_array() && !drakonFindTargets.empty()) {
            prompt << "KNOWN DRAKON FIND TARGETS AVAILABLE TO THE USER:\n";
            prompt << drakonFindTargets.dump(2) << "\n";
            prompt << "- If the goal clearly references one of these targets, use its semantics in the design.\n";
            prompt << "- Do not invent target details that are not present here.\n\n";
        }

        if (!snapshotDataUrl.empty()) {
            prompt << "VISUAL CONTEXT:\n";
            prompt << "- You will receive one current snapshot from the selected camera.\n";
            prompt << "- Use the visible scene to reduce false positives.\n";
            prompt << "- Only propose polygons in analysis_regions when the user's goal clearly refers to a specific visible area.\n\n";
        }
        else {
            prompt << "VISUAL CONTEXT:\n";
            prompt << "- No snapshot is available for this design.\n";
            prompt << "- Do not invent analysis_regions without visual evidence. Return analysis_regions as an empty array.\n\n";
        }

        prompt << "DESIGN RULES:\n";
        prompt << "- Respond in the same language as the user's goal.\n";
        prompt << "- Output JSON field names in English.\n";
        prompt << "- prompt_template and alert_condition must be non-empty.\n";
        prompt << "- Infer a concrete alert_condition even if the user only described what they want to detect.\n";
        prompt << "- Keep negative_condition empty only if it truly adds no value; otherwise use it to reduce false positives.\n";
        prompt << "- Prefer precise, testable alert and negative conditions.\n";
        prompt << "- Choose stable defaults when the user did not specify execution settings.\n";
        prompt << "- Valid input_type values: video, image.\n";
        prompt << "- Valid video_packaging_mode values: mosaic_2x2, frame_sequence.\n";
        prompt << "- Do not choose mosaic_3x3; it is deprecated because it weakens temporal/detail fidelity.\n";
        prompt << "- Valid inference_model values: ultra, ultra_plus, light, core, legacy, pro.\n";
        prompt << "- model_fps must be 1-5 when input_type=video; use 1 otherwise.\n";
        prompt << "- run_every should normally be 10 or 60 seconds.\n";
        prompt << "- running_resolution should be 640 or 1024.\n";
        prompt << "- only_capture_on_motion and use_temporal_context must be booleans.\n";
        prompt << "- analysis_regions must be an array. When used, each polygon point must be normalized between 0 and 1.\n";
        prompt << "- Use 3-8 polygon points per region when a polygon is required.\n";
        prompt << "- Do not output markdown, comments, or code fences.\n";
        prompt << "- Return RAW JSON only.\n\n";

        prompt << "OUTPUT FORMAT (EXACT KEYS):\n";
        prompt << "{\n";
        prompt << "  \"display_name\": \"...\",\n";
        prompt << "  \"summary\": \"...\",\n";
        prompt << "  \"prompt_template\": \"...\",\n";
        prompt << "  \"alert_condition\": \"...\",\n";
        prompt << "  \"negative_condition\": \"...\",\n";
        prompt << "  \"input_type\": \"video\",\n";
        prompt << "  \"video_packaging_mode\": \"frame_sequence\",\n";
        prompt << "  \"inference_model\": \"ultra\",\n";
        prompt << "  \"model_fps\": 1,\n";
        prompt << "  \"run_every\": 60,\n";
        prompt << "  \"running_resolution\": 640,\n";
        prompt << "  \"only_capture_on_motion\": true,\n";
        prompt << "  \"use_temporal_context\": true,\n";
        prompt << "  \"analysis_regions\": [\n";
        prompt << "    {\n";
        prompt << "      \"region_id\": \"gate-area\",\n";
        prompt << "      \"label\": \"Gate area\",\n";
        prompt << "      \"description\": \"...\",\n";
        prompt << "      \"enabled\": true,\n";
        prompt << "      \"full_frame\": false,\n";
        prompt << "      \"polygon_norm\": [\n";
        prompt << "        { \"x\": 0.10, \"y\": 0.20 },\n";
        prompt << "        { \"x\": 0.50, \"y\": 0.20 },\n";
        prompt << "        { \"x\": 0.55, \"y\": 0.75 },\n";
        prompt << "        { \"x\": 0.08, \"y\": 0.75 }\n";
        prompt << "      ],\n";
        prompt << "      \"draw_ref_width\": 1920,\n";
        prompt << "      \"draw_ref_height\": 1080,\n";
        prompt << "      \"prompt_core\": \"...\",\n";
        prompt << "      \"alert_condition\": \"...\",\n";
        prompt << "      \"negative_condition\": \"...\"\n";
        prompt << "    }\n";
        prompt << "  ]\n";
        prompt << "}\n\n";
        prompt << "Language hint from user: " << languageHint << "\n";

        nlohmann::json content = nlohmann::json::array();
        content.push_back({ { "type", "text" }, { "text", prompt.str() } });
        if (!snapshotDataUrl.empty()) {
            content.push_back(
                makeOpenAIImageContentFromBareJpeg(stripDataUrlPrefix(snapshotDataUrl), modelName)
            );
        }

        nlohmann::json body = {
            { "model", modelName },
            { "messages", nlohmann::json::array({
                {
                    { "role", "user" },
                    { "content", content }
                }
            })}
        };
        applyOpenAITemperatureField_(body, modelName, 0.1);

        const bool useResponsesTransport = shouldUseOpenAIResponsesTransportForModel_(modelName);
        const int baseRequestedLimit = 1800;
        const int firstEffectiveLimit = resolveOpenAITokenLimitForModel_(modelName, baseRequestedLimit);
        const int secondEffectiveLimit = (std::min)(3200, firstEffectiveLimit + 900);

        std::string rawResp;
        OpenAITextObjectResponse_ parsedResponse;
        std::string postError;

        auto postAndParse = [&](int requestedLimit, int attemptNo) -> bool {
            nlohmann::json reqBody = body;
            applyOpenAITokenLimitField_(reqBody, modelName, requestedLimit);

            try {
                if (useResponsesTransport) {
                    rawResp = postOpenAIResponsesWithCoreLease_(
                        modelApiKey,
                        reqBody,
                        []() { MaybeNotifyFirstRetry(); },
                        false,
                        {},
                        "agent_design"
                    );
                }
                else {
                    rawResp = postOpenAIChatCompletionsWithCoreLease_(
                        modelApiKey,
                        reqBody,
                        []() { MaybeNotifyFirstRetry(); },
                        false,
                        {},
                        "agent_design"
                    );
                }
            }
            catch (const std::exception& e) {
                postError = e.what();
                return false;
            }

            parsedResponse = extractOpenAITextObjectResponse_(rawResp);
            Logger::instance().logDebugNoEscalation(
                "agent",
                buildOpenAIResponseLogBlock_(
                    "handleAgentDesignCommand_: rawResp (attempt=" + std::to_string(attemptNo) + ")",
                    rawResp,
                    parsedResponse)
            );
            return true;
        };

        if (!postAndParse(firstEffectiveLimit, 1)) {
            fail(std::string("OpenAI agent design request failed: ") + postError);
            return;
        }

        if (shouldRetryOpenAITextObjectResponseForLength_(parsedResponse) &&
            secondEffectiveLimit > firstEffectiveLimit)
        {
            Logger::instance().logDebug(
                "agent",
                "handleAgentDesignCommand_: finish_reason=length with incomplete JSON; retrying once with higher token limit " +
                std::to_string(secondEffectiveLimit));
            if (!postAndParse(secondEffectiveLimit, 2)) {
                fail(std::string("OpenAI agent design request failed: ") + postError);
                return;
            }
        }

        if (shouldRetryOpenAITextObjectResponseForLength_(parsedResponse)) {
            fail("OpenAI agent design returned finish_reason=length before completing a valid JSON object");
            return;
        }
        if (!parsedResponse.hasValidResponseJson) {
            fail("OpenAI agent design returned invalid JSON response");
            return;
        }
        if (parsedResponse.text.empty()) {
            fail("OpenAI agent design returned empty text");
            return;
        }
        if (!parsedResponse.hasJsonObjectSlice) {
            fail("OpenAI agent design did not return a JSON object");
            return;
        }
        if (!parsedResponse.hasValidJsonObject) {
            fail("OpenAI agent design returned malformed JSON object");
            return;
        }

        const nlohmann::json designed = parsedResponse.jsonObject;
        std::string displayName = jsonTextField(designed, "display_name");
        if (displayName.empty()) {
            displayName = jsonTextField(agentPatch, "display_name");
        }
        if (displayName.empty()) {
            displayName =
                goalSummary.size() <= 80
                    ? goalSummary
                    : trimCopyPromptEnhance(goalSummary.substr(0, 77)) + "...";
        }

        const std::string promptTemplate = jsonTextField(designed, "prompt_template");
        const std::string alertCondition = jsonTextField(designed, "alert_condition");
        const std::string negativeCondition = jsonTextField(designed, "negative_condition");
        if (promptTemplate.empty() || alertCondition.empty()) {
            fail("OpenAI agent design returned empty required fields");
            return;
        }

        std::string alertPolicy;
        if (designContext.is_object() &&
            designContext.contains("alert_policy") &&
            designContext["alert_policy"].is_string()) {
            alertPolicy = toLowerCopyPromptEnhance(
                trimCopyPromptEnhance(designContext["alert_policy"].get<std::string>())
            );
        }
        const std::string effectiveAlertCondition =
            alertPolicy == "never"
                ? std::string("Never set alert_condition=true. This step is analysis-only and must only return structured evidence.")
                : alertCondition;

        const std::string inputType = normalizeInputType(jsonTextField(designed, "input_type"));
        const std::string videoPackagingMode =
            normalizeVideoPackagingMode(jsonTextField(designed, "video_packaging_mode"));
        const std::string inferenceModel =
            normalizeInferenceModel(jsonTextField(designed, "inference_model"));

        nlohmann::json result;
        result["design"] = {
            { "display_name", displayName },
            { "summary", jsonTextField(designed, "summary") },
            { "prompt_template", promptTemplate },
            { "alert_condition", effectiveAlertCondition },
            { "negative_condition", negativeCondition },
            { "input_type", inputType },
            { "video_packaging_mode", videoPackagingMode },
            { "inference_model", inferenceModel },
            { "model_fps", normalizeModelFps(designed, inputType) },
            { "run_every", normalizeRunEvery(designed) },
            { "running_resolution", normalizeRunningResolution(designed) },
            { "only_capture_on_motion", jsonBoolField(designed, "only_capture_on_motion", true) },
            { "use_temporal_context", jsonBoolField(designed, "use_temporal_context", true) },
            { "analysis_regions", sanitizeAnalysisRegions(
                designed.value("analysis_regions", nlohmann::json::array()),
                promptTemplate,
                alertCondition,
                negativeCondition,
                !snapshotDataUrl.empty()) },
        };
        result["model_name"] = modelName;
        result["snapshot_source"] = snapshotSource;
        result["snapshot_ts_utc_iso"] = snapshotTsUtcIso;

        postCommandResult_(commandId, "completed", result);
    }
    catch (const std::exception& e) {
        fail(std::string("agent_design failed: ") + e.what());
    }
    catch (...) {
        fail("agent_design failed with unknown error");
    }
}

bool AgentCore::compileTemporalPlanWithModel_(
    const std::string& compileModelName,
    const std::string& compileApiKey,
    const nlohmann::json& compileInput,
    nlohmann::json& outEnvelope,
    const std::string& runtimeLogId,
    std::string* outFailureReason)
{
    outEnvelope = nlohmann::json::object();
    if (outFailureReason) *outFailureReason = "";

    auto logCompile = [&](const std::string& msg) {
        const std::string& logId = runtimeLogId.empty() ? std::string("agent") : runtimeLogId;
        Logger::instance().logDebug(logId, msg);
    };

    auto failWithReason = [&](const std::string& reason, const std::string& msg) -> bool {
        if (outFailureReason) *outFailureReason = reason;
        logCompile(msg);
        return false;
    };

    if (trimAscii(compileApiKey).empty()) {
        return failWithReason(
            "missing_api_key",
            "compileTemporalPlanWithModel_: missing compile api key"
        );
    }

    try {
        const std::string safeCompileModelName =
            compileModelName.empty() ? std::string("gpt-5.1") : compileModelName;
        nlohmann::json body = {
            { "model", safeCompileModelName },
            { "messages", nlohmann::json::array({
                {
                    { "role", "system" },
                    { "content", temporal::compilerSystemPrompt() }
                },
                {
                    { "role", "user" },
                    { "content", temporal::compilerUserPrompt(compileInput) }
                }
            })}
        };
        applyOpenAITemperatureField_(body, safeCompileModelName, 0.0);
        const bool useResponsesTransport =
            shouldUseOpenAIResponsesTransportForModel_(safeCompileModelName);
        if (useResponsesTransport) {
            body["response_format"] = {
                { "type", "json_object" }
            };
        }
        const int firstEffectiveLimit =
            resolveOpenAITokenLimitForModel_(safeCompileModelName, 4000);
        const int secondEffectiveLimit =
            (std::max)(8000, firstEffectiveLimit);

        std::string rawResp;
        OpenAITextObjectResponse_ parsedResponse;
        auto postAndParse = [&](int requestedLimit, int attemptNo) -> bool {
            nlohmann::json reqBody = body;
            applyOpenAITokenLimitField_(reqBody, safeCompileModelName, requestedLimit);

            rawResp = useResponsesTransport
                ? postOpenAIResponsesWithCoreLease_(
                    compileApiKey,
                    reqBody,
                    []() { MaybeNotifyFirstRetry(); },
                    false,
                    {},
                    "compile_temporal_plan",
                    runtimeLogId
                )
                : postOpenAIChatCompletionsWithCoreLease_(
                    compileApiKey,
                    reqBody,
                    []() { MaybeNotifyFirstRetry(); },
                    false,
                    {},
                    "compile_temporal_plan",
                    runtimeLogId
                );

            parsedResponse = extractOpenAITextObjectResponse_(rawResp);
            logCompile(
                "compileTemporalPlanWithModel_: response model=" +
                safeCompileModelName +
                " attempt=" + std::to_string(attemptNo) +
                " finish_reason=" +
                (parsedResponse.finishReason.empty()
                    ? std::string("<empty>")
                    : parsedResponse.finishReason) +
                " message_content_len=" + std::to_string(parsedResponse.text.size()) +
                " raw_response=" + truncateForLog_(rawResp, 2500)
            );
            if (!parsedResponse.hasValidResponseJson) {
                return failWithReason(
                    "invalid_raw_response_json",
                    "compileTemporalPlanWithModel_: invalid raw response JSON"
                );
            }
            return true;
        };

        if (!postAndParse(firstEffectiveLimit, 1)) {
            return false;
        }

        if (shouldRetryOpenAITextObjectResponseForLength_(parsedResponse) &&
            secondEffectiveLimit > firstEffectiveLimit)
        {
            logCompile(
                "compileTemporalPlanWithModel_: finish_reason=length with incomplete JSON; retrying once with higher token limit " +
                std::to_string(secondEffectiveLimit)
            );
            if (!postAndParse(secondEffectiveLimit, 2)) {
                return false;
            }
        }

        if (shouldRetryOpenAITextObjectResponseForLength_(parsedResponse)) {
            return failWithReason(
                "finish_reason_length",
                "compileTemporalPlanWithModel_: finish_reason=length before completing a valid JSON object"
            );
        }

        std::string text = parsedResponse.text;
        logCompile(
            "compileTemporalPlanWithModel_: extracted_text model=" +
            safeCompileModelName +
            " finish_reason=" +
            (parsedResponse.finishReason.empty()
                ? std::string("<empty>")
                : parsedResponse.finishReason) +
            " text_len=" + std::to_string(text.size()) +
            " text_preview=" + truncateForLog_(text, 1200)
        );
        if (text.empty()) {
            return failWithReason(
                "empty_text",
                "compileTemporalPlanWithModel_: empty model text"
            );
        }

        if (!parsedResponse.hasJsonObjectSlice) {
            return failWithReason(
                "no_json",
                "compileTemporalPlanWithModel_: no JSON object in model text"
            );
        }

        if (!parsedResponse.hasValidJsonObject) {
            return failWithReason(
                "malformed_envelope_json",
                "compileTemporalPlanWithModel_: malformed envelope JSON"
            );
        }
        outEnvelope = parsedResponse.jsonObject;
        return true;
    }
    catch (const std::exception& e) {
        return failWithReason(
            "exception",
            std::string("compileTemporalPlanWithModel_ exception: ") + e.what()
        );
    }
    catch (...) {
        return failWithReason(
            "unknown_exception",
            "compileTemporalPlanWithModel_ unknown exception"
        );
    }
}

void AgentCore::postTemporalCompileResultEvent_(
    const std::string& sourceType,
    int sourceId,
    const nlohmann::json& envelope,
    const std::string& compileModel,
    bool persistPlanCache)
{
    if (sourceType.empty() || sourceId <= 0) return;
    if (sourceType != "camera_algorithm" && sourceType != "job_step_agent") return;

    const nlohmann::json canonicalEnvelope = temporal::canonicalizePlanEnvelope(envelope);
    nlohmann::json plan = temporal::extractPlan(canonicalEnvelope);
    nlohmann::json details = {
        { "source_type", sourceType },
        { "source_id", sourceId },
        { "compile_status", canonicalEnvelope.is_object() ? canonicalEnvelope.value("compile_status", std::string("ok")) : "ok" },
        { "compile_confidence", canonicalEnvelope.is_object() ? canonicalEnvelope.value("compile_confidence", 0.0) : 0.0 },
        { "compile_model", compileModel },
        { "compiled_at", temporal::nowIso() },
        { "persist_plan_cache", persistPlanCache },
        { "plan_hash", plan.is_object() ? plan.value("plan_hash", std::string()) : std::string() },
        { "plan_version", plan.is_object() ? plan.value("schema_version", std::string("temporal-plan/1.0")) : std::string("temporal-plan/1.0") },
        { "plan_envelope", canonicalEnvelope }
    };
    postAgentEvent("temporal_compile_result", std::nullopt, "", "", details);
}

void AgentCore::pruneChatTemporalSessions_()
{
    std::lock_guard<std::mutex> lock(chatTemporalMu_);
    const auto now = std::chrono::steady_clock::now();
    const auto ttl = std::chrono::minutes(30);
    for (auto it = chatTemporalBySession_.begin(); it != chatTemporalBySession_.end();) {
        if (it->second.touchedAt.time_since_epoch().count() == 0 ||
            (now - it->second.touchedAt) > ttl) {
            it = chatTemporalBySession_.erase(it);
        }
        else {
            ++it;
        }
    }
}

bool AgentCore::ensureTemporalPlanForRuntime(
    const std::string& sourceType,
    int sourceId,
    const std::string& promptCore,
    const std::string& alertCondition,
    const std::string& negativeCondition,
    const std::string& inputType,
    const std::string& language,
    const std::string& modelFamily,
    const std::string& compileApiKey,
    nlohmann::json& inOutPlanEnvelope,
    bool persistResult,
    const std::string& runtimeLogId)
{
    const std::string schemaVersion = "temporal-plan/1.0";
    const std::string promptHash =
        temporal::computePromptRevisionHash(promptCore, alertCondition);
    const std::string mergedTemporalPrompt =
        temporal::lower(temporal::trim(promptCore + " " + alertCondition + " " + negativeCondition));
    const std::string compileModel = temporal::compileModelForFamily(modelFamily);
    const TemporalRuntimeGuardConfig_& runtimeGuardConfig = temporalRuntimeGuardConfig_();
    const bool runtimeGuardSelected =
        temporalRuntimeGuardApplies_(runtimeGuardConfig, sourceType, sourceId);
    const bool runtimeGuardEnforced =
        runtimeGuardConfig.failClosedEnabled && runtimeGuardSelected && !runtimeGuardConfig.shadowOnly;
    const bool runtimeGuardShadow =
        runtimeGuardConfig.failClosedEnabled && !runtimeGuardEnforced;

    auto logTemporal = [&](const std::string& msg) {
        const std::string& logId = runtimeLogId.empty() ? std::string("agent") : runtimeLogId;
        Logger::instance().logDebug(logId, msg);
    };
    auto emitRuntimeGuardDecision = [&](const std::string& stageTag,
                                        const std::string& reason,
                                        bool enforced,
                                        const std::string& modelTag) {
        const std::string mode = enforced ? "enforced" : "shadow";
        logTemporal(
            "ensureTemporalPlanForRuntime: fail_closed_" + mode +
            " source_type=" + sourceType +
            " source_id=" + std::to_string(sourceId) +
            " stage=" + stageTag +
            " reason=" + reason +
            " prompt_hash=" + promptHash
        );
        if (persistResult) {
            postTemporalCompileResultEvent_(
                sourceType,
                sourceId,
                makeTemporalRuntimeGuardEnvelope_(
                    enforced ? "runtime_guard_blocked" : "runtime_guard_shadow",
                    mode,
                    stageTag,
                    reason,
                    promptHash,
                    promptCore,
                    alertCondition,
                    negativeCondition,
                    inputType,
                    language
                ),
                modelTag.empty() ? std::string("temporal_guard") : modelTag,
                false
            );
        }
    };

    auto envelopeMatchesPromptRevision = [&](const nlohmann::json& env) -> bool {
        return temporal::planMatchesPromptRevision(env, promptCore, alertCondition);
    };
    auto envelopeHasUnsafeThreatShortcut = [&](const nlohmann::json& env) -> bool {
        return temporal::looksLikeThreatEvidencePrompt(mergedTemporalPrompt) &&
               temporal::planHasUnsafeLocalAlertShortcutForThreatPrompt(temporal::extractPlan(env));
    };
    auto compilerSelectedLegacy = [&](const nlohmann::json& env) -> bool {
        return temporal::compileStatusValue(env, std::string()) == "not_temporal";
    };
    auto annotateCompilerEnvelope = [&](nlohmann::json& env) {
        if (!env.is_object()) env = nlohmann::json::object();
        const std::string compileStatus = temporal::compileStatusValue(env, "ok");
        env["compile_status"] = compileStatus.empty() ? std::string("ok") : compileStatus;
        env["prompt_fingerprint"] = temporal::makePromptFingerprint(
            promptCore,
            alertCondition,
            negativeCondition,
            inputType,
            language
        );
        if (compileStatus == "ok") {
            nlohmann::json plan = temporal::extractPlan(env);
            if (!plan.is_object()) plan = nlohmann::json::object();
            plan["plan_hash"] = promptHash;
            plan["schema_version"] = schemaVersion;
            plan["prompt_fingerprint"] = env["prompt_fingerprint"];
            nlohmann::json executionContext = {
                { "source_type", sourceType },
                { "source_id", sourceId },
                { "timezone", machineTimezoneForBackend_.empty() ? std::string("UTC") : machineTimezoneForBackend_ }
            };
            const std::string fixedTimeTimezoneHint =
                temporal::canonicalFixedLocalTimezone(
                    machineTimezoneForBackend_.empty() ? std::string("UTC") : machineTimezoneForBackend_);
            if (!fixedTimeTimezoneHint.empty()) {
                executionContext["fixed_time_timezone_hint"] = fixedTimeTimezoneHint;
            }
            plan["execution_context"] = std::move(executionContext);
            env["plan_json"] = std::move(plan);
        } else {
            env.erase("plan_json");
        }
        env = temporal::canonicalizePlanEnvelope(env);
    };

    if (temporal::decisionCacheable(inOutPlanEnvelope) && envelopeMatchesPromptRevision(inOutPlanEnvelope)) {
        nlohmann::json canonicalEnvelope = inOutPlanEnvelope;
        annotateCompilerEnvelope(canonicalEnvelope);
        std::string cachedDecisionReason;
        const bool cachedDecisionOk = temporal::validateCompilerDecisionConsistency(
            canonicalEnvelope,
            &cachedDecisionReason
        );
        if (temporal::compileStatusValue(canonicalEnvelope, std::string()) == "ok" &&
            envelopeHasUnsafeThreatShortcut(canonicalEnvelope))
        {
            logTemporal(
                "ensureTemporalPlanForRuntime: rejecting cached temporal plan with unsafe threat shortcut source_type=" +
                sourceType + " source_id=" + std::to_string(sourceId) +
                " plan_hash=" + promptHash
            );
            inOutPlanEnvelope = nlohmann::json::object();
        }
        else if (!cachedDecisionOk) {
            if (runtimeGuardEnforced) {
                emitRuntimeGuardDecision("cached_plan", cachedDecisionReason, true, "cached_plan");
            } else if (runtimeGuardShadow) {
                emitRuntimeGuardDecision("cached_plan", cachedDecisionReason, false, "cached_plan");
            }
            inOutPlanEnvelope = nlohmann::json::object();
        }
        else {
            const bool changed = canonicalEnvelope != inOutPlanEnvelope;
            inOutPlanEnvelope = canonicalEnvelope;
            if (changed) {
                logTemporal(
                    "ensureTemporalPlanForRuntime: canonicalized cached temporal plan source_type=" +
                    sourceType + " source_id=" + std::to_string(sourceId) +
                    " plan_hash=" + promptHash
                );
                if (persistResult) {
                    postTemporalCompileResultEvent_(
                        sourceType,
                        sourceId,
                        inOutPlanEnvelope,
                        compilerSelectedLegacy(inOutPlanEnvelope)
                            ? "cached_not_temporal"
                            : "canonicalized_cached_plan"
                    );
                }
            }
            if (compilerSelectedLegacy(inOutPlanEnvelope)) {
                logTemporal(
                    "ensureTemporalPlanForRuntime: cached compiler decision selected legacy source_type=" +
                    sourceType + " source_id=" + std::to_string(sourceId) +
                    " prompt_hash=" + promptHash
                );
                return false;
            }
            return temporal::planUsable(inOutPlanEnvelope);
        }
    }

    const nlohmann::json in = temporal::compileInput(
        promptCore,
        promptCore,
        alertCondition,
        negativeCondition,
        inputType,
        language,
        sourceType,
        sourceId,
        machineTimezoneForBackend_.empty() ? "UTC" : machineTimezoneForBackend_
    );

    nlohmann::json envelope = nlohmann::json::object();
    std::string compileFailureReason;
    logTemporal(
        "ensureTemporalPlanForRuntime: compile request source_type=" + sourceType +
        " source_id=" + std::to_string(sourceId) +
        " compile_model=" + compileModel +
        " model_family=" + modelFamily +
        " prompt_hash=" + promptHash +
        " input_type=" + inputType +
        " prompt_core_clean=" + truncateForLog_(trimAscii(promptCore), 1200) +
        " alert_condition=" + truncateForLog_(trimAscii(alertCondition), 800) +
        " negative_condition=" + truncateForLog_(trimAscii(negativeCondition), 800)
    );
    const bool compiled = compileTemporalPlanWithModel_(
        compileModel,
        compileApiKey,
        in,
        envelope,
        runtimeLogId,
        &compileFailureReason
    );

    if (compiled) {
        annotateCompilerEnvelope(envelope);
    }

    std::string invalidReason;
    bool compilerDecisionUsable =
        compiled && temporal::validateCompilerDecisionConsistency(envelope, &invalidReason);
    const std::string compiledStatus =
        compiled ? temporal::compileStatusValue(envelope, std::string()) : std::string();
    if (compiled &&
        compilerDecisionUsable &&
        compiledStatus == "ok" &&
        envelopeHasUnsafeThreatShortcut(envelope))
    {
        invalidReason = "threat_prompt_requires_explicit_threat_evidence";
        compilerDecisionUsable = false;
    }
    if (compiled &&
        compilerDecisionUsable &&
        compiledStatus != "ok" &&
        compiledStatus != "not_temporal")
    {
        invalidReason = "compile_status_" + compiledStatus;
        compilerDecisionUsable = false;
    }
    if (compiled && !compilerDecisionUsable) {
        logTemporal(
            "ensureTemporalPlanForRuntime: compiled envelope rejected source_type=" + sourceType +
            " source_id=" + std::to_string(sourceId) +
            " compile_model=" + compileModel +
            " prompt_hash=" + promptHash +
            " reason=" + (invalidReason.empty() ? std::string("<empty>") : invalidReason) +
            " envelope_preview=" + truncateForLog_(envelope.dump(), 2500)
        );
    }

    if (!compiled || !compilerDecisionUsable) {
        const std::string fallbackReason =
            !compiled
                ? (compileFailureReason.empty() ? std::string("parse_failed") : compileFailureReason)
                : std::string("invalid_compiler_decision:") +
                    (invalidReason.empty() ? std::string("unknown") : invalidReason);
        if (compiled && persistResult) {
            postTemporalCompileResultEvent_(sourceType, sourceId, envelope, compileModel, false);
        }
        if (runtimeGuardEnforced && !runtimeGuardConfig.allowSafeFallback) {
            emitRuntimeGuardDecision("legacy_fallback_blocked", fallbackReason, true, compileModel);
        } else if (runtimeGuardShadow) {
            emitRuntimeGuardDecision("legacy_fallback", fallbackReason, false, compileModel);
        }
        logTemporal(
            "ensureTemporalPlanForRuntime: using legacy path source_type=" + sourceType +
            " source_id=" + std::to_string(sourceId) +
            " compile_model=" + compileModel +
            " prompt_hash=" + promptHash +
            " reason=" + fallbackReason
        );
        inOutPlanEnvelope = nlohmann::json::object();
        return false;
    }

    inOutPlanEnvelope = envelope;

    if (compilerSelectedLegacy(inOutPlanEnvelope)) {
        if (persistResult) {
            postTemporalCompileResultEvent_(sourceType, sourceId, inOutPlanEnvelope, compileModel);
        }
        logTemporal(
            "ensureTemporalPlanForRuntime: compiler selected legacy path source_type=" + sourceType +
            " source_id=" + std::to_string(sourceId) +
            " prompt_hash=" + promptHash
        );
        return false;
    }

    if (persistResult) {
        postTemporalCompileResultEvent_(sourceType, sourceId, inOutPlanEnvelope, compileModel);
    }
    return temporal::planUsable(inOutPlanEnvelope);
}

std::vector<VideoHit> AgentCore::analyzeVideosWithGemini_(
    const std::vector<EncodedVideoSegment>& videos,
    const std::string& userQuestion,
    bool stopOnFirstHit,
    const std::string& uploadedImageBase64,
    const std::string& modelTier,
    const std::string& geminiApiKey,
    int& outPromptTokens,
    int& outOutputTokens,
    int& outTotalTokens,
    std::string& outModelAnswer)
{
    std::vector<VideoHit> allHits;
    if (videos.empty()) {
        outPromptTokens = outOutputTokens = outTotalTokens = 0;
        outModelAnswer.clear();
        return allHits;
    }

    outPromptTokens = outOutputTokens = outTotalTokens = 0;
    outModelAnswer.clear();

    // Spawn at most 8 workers, but never more than the number of videos.
    const int kMaxThreads = 8;
    const int numWorkers = std::min<int>((int)videos.size(), kMaxThreads);

    std::mutex hitsMutex;

    std::atomic<size_t> nextIndex{ 0 };
    std::atomic<bool> stopEarly{ false };

    std::atomic<int> totalPrompt{ 0 };
    std::atomic<int> totalOutput{ 0 };
    std::atomic<int> totalTotal{ 0 };

    auto worker = [&]() {
        for (;;) {
            if (stopOnFirstHit && stopEarly.load(std::memory_order_acquire)) {
                break;
            }

            size_t idx = nextIndex.fetch_add(1, std::memory_order_acq_rel);
            if (idx >= videos.size()) break;

            try {
                int batchPrompt = 0, batchOutput = 0, batchTotal = 0;

                auto hit = callGeminiVisionVideoSegment_(
                    videos[idx],
                    userQuestion,
                    uploadedImageBase64,
                    modelTier,
                    geminiApiKey,
                    batchPrompt,
                    batchOutput,
                    batchTotal
                );

                hit.segmentIndex = idx;

                totalPrompt.fetch_add(batchPrompt, std::memory_order_relaxed);
                totalOutput.fetch_add(batchOutput, std::memory_order_relaxed);
                totalTotal.fetch_add(batchTotal, std::memory_order_relaxed);

                // Keep the latest non-empty model answer (thread-safe).
                if (!hit.answer.empty()) {
                    std::lock_guard<std::mutex> lock(hitsMutex);
                    outModelAnswer = hit.answer;
                }

                if (!hit.hasMatch) {
                    continue;
                }

                if (stopOnFirstHit) {
                    bool expected = false;
                    if (stopEarly.compare_exchange_strong(
                        expected, true,
                        std::memory_order_acq_rel,
                        std::memory_order_acquire))
                    {
                        std::lock_guard<std::mutex> lock(hitsMutex);
                        allHits.push_back(hit);
                        if (!hit.answer.empty()) {
                            outModelAnswer = hit.answer;
                        }
                    }
                    break;
                }
                else {
                    std::lock_guard<std::mutex> lock(hitsMutex);
                    allHits.push_back(hit);
                }
            }
            catch (const std::exception& e) {
                Logger::instance().logDebug(
                    "agent",
                    std::string("analyzeVideosWithGemini_ worker exception idx=") +
                    std::to_string(idx) + ": " + e.what()
                );
                // continue; do not kill the process
            }
            catch (...) {
                Logger::instance().logDebug(
                    "agent",
                    std::string("analyzeVideosWithGemini_ worker unknown exception idx=") +
                    std::to_string(idx)
                );
                // continue; do not kill the process
            }
        }
        };

    std::vector<std::thread> threads;
    threads.reserve(numWorkers);
    for (int i = 0; i < numWorkers; ++i) {
        threads.emplace_back(worker);
    }
    for (auto& t : threads) {
        if (t.joinable()) t.join();
    }

    outPromptTokens = totalPrompt.load(std::memory_order_relaxed);
    outOutputTokens = totalOutput.load(std::memory_order_relaxed);
    outTotalTokens = totalTotal.load(std::memory_order_relaxed);

    Logger::instance().logDebug(
        "agent",
        "analyzeVideosWithGemini_: videos=" + std::to_string(videos.size()) +
        " workers=" + std::to_string(numWorkers) +
        " total hits=" + std::to_string(allHits.size())
    );

    return allHits;
}


std::vector<VideoHit> AgentCore::analyzeVideosWithOpenAI_(
    const std::vector<EncodedVideoSegment>& videos,
    const std::string& userQuestion,
    bool stopOnFirstHit,
    const std::string& uploadedImageBase64,
    const std::string& openAiModelName,
    const std::string& openAiApiKey,
    int modelInputFps,
    int runningResolution,
    int& outPromptTokens,
    int& outOutputTokens,
    int& outTotalTokens,
    std::string& outModelAnswer,
    bool requestCoreChatPriority,
    const std::function<bool()>& shouldAbort)
{
    std::vector<VideoHit> allHits;
    if (videos.empty()) {
        outPromptTokens = outOutputTokens = outTotalTokens = 0;
        outModelAnswer.clear();
        return allHits;
    }

    outPromptTokens = outOutputTokens = outTotalTokens = 0;
    outModelAnswer.clear();

    const int kMaxThreads = 8;
    const std::string effectiveModelName =
        openAiModelName.empty() ? std::string("gpt-5-mini") : openAiModelName;
    const bool useCoreModel = isZAiCoreModelName_(effectiveModelName);
    const int numWorkers = std::min<int>((int)videos.size(), useCoreModel ? 1 : kMaxThreads);

    std::mutex hitsMutex;
    std::atomic<size_t> nextIndex{ 0 };
    std::atomic<bool> stopEarly{ false };
    std::atomic<bool> aborted{ false };

    std::atomic<int> totalPrompt{ 0 };
    std::atomic<int> totalOutput{ 0 };
    std::atomic<int> totalTotal{ 0 };

    auto worker = [&]() {
        for (;;) {
            if (aborted.load(std::memory_order_acquire)) {
                break;
            }
            if (shouldAbort && shouldAbort()) {
                aborted.store(true, std::memory_order_release);
                break;
            }
            if (stopOnFirstHit && stopEarly.load(std::memory_order_acquire)) {
                break;
            }

            size_t idx = nextIndex.fetch_add(1, std::memory_order_acq_rel);
            if (idx >= videos.size()) break;

            try {
                int batchPrompt = 0, batchOutput = 0, batchTotal = 0;

                auto hit = callOpenAIVisionVideoSegment_(
                    videos[idx],
                    userQuestion,
                    uploadedImageBase64,
                    std::vector<FaceReferenceImage>{},
                    std::vector<NegativeReferenceImage>{},
                    std::string(),
                    std::string(),
                    openAiModelName,
                    openAiApiKey,
                    modelInputFps,
                    /*expectedWindowSeconds*/ 0,
                    runningResolution,
                    std::string(kPreferredChatVideoPackagingMode_),
                    batchPrompt,
                    batchOutput,
                    batchTotal,
                    requestCoreChatPriority,
                    shouldAbort
                );

                hit.segmentIndex = idx;

                totalPrompt.fetch_add(batchPrompt, std::memory_order_relaxed);
                totalOutput.fetch_add(batchOutput, std::memory_order_relaxed);
                totalTotal.fetch_add(batchTotal, std::memory_order_relaxed);

                if (!hit.answer.empty()) {
                    std::lock_guard<std::mutex> lock(hitsMutex);
                    outModelAnswer = hit.answer;
                }

                if (!hit.hasMatch) {
                    continue;
                }

                if (stopOnFirstHit) {
                    bool expected = false;
                    if (stopEarly.compare_exchange_strong(
                        expected, true,
                        std::memory_order_acq_rel,
                        std::memory_order_acquire))
                    {
                        std::lock_guard<std::mutex> lock(hitsMutex);
                        allHits.push_back(hit);
                        if (!hit.answer.empty()) {
                            outModelAnswer = hit.answer;
                        }
                    }
                    break;
                }
                else {
                    std::lock_guard<std::mutex> lock(hitsMutex);
                    allHits.push_back(hit);
                }
            }
            catch (const CoreModelLeaseAborted&) {
                aborted.store(true, std::memory_order_release);
                break;
            }
            catch (const std::exception& e) {
                Logger::instance().logDebug(
                    "agent",
                    std::string("analyzeVideosWithOpenAI_ worker exception idx=") +
                    std::to_string(idx) + ": " + e.what()
                );
            }
            catch (...) {
                Logger::instance().logDebug(
                    "agent",
                    std::string("analyzeVideosWithOpenAI_ worker unknown exception idx=") +
                    std::to_string(idx)
                );
            }
        }
    };

    std::vector<std::thread> threads;
    threads.reserve(numWorkers);
    for (int i = 0; i < numWorkers; ++i) {
        threads.emplace_back(worker);
    }
    for (auto& t : threads) {
        if (t.joinable()) t.join();
    }

    outPromptTokens = totalPrompt.load(std::memory_order_relaxed);
    outOutputTokens = totalOutput.load(std::memory_order_relaxed);
    outTotalTokens = totalTotal.load(std::memory_order_relaxed);

    Logger::instance().logDebug(
        "agent",
        "analyzeVideosWithOpenAI_: videos=" + std::to_string(videos.size()) +
        " workers=" + std::to_string(numWorkers) +
        " total hits=" + std::to_string(allHits.size()) +
        " model=" + effectiveModelName +
        " fps=" + std::to_string(modelInputFps) +
        " running_resolution=" + std::to_string(runningResolution)
    );

    return allHits;
}

std::vector<std::size_t> AgentCore::buildChatTemporalExecutionOrder_(
    const std::vector<EncodedVideoSegment>& videos,
    const nlohmann::json& routerResult) const
{
    std::vector<std::size_t> orderedIndices;
    if (videos.empty()) {
        return orderedIndices;
    }

    std::unordered_map<int, std::vector<std::size_t>> lanesByCamera;
    for (std::size_t idx = 0; idx < videos.size(); ++idx) {
        lanesByCamera[videos[idx].cameraId].push_back(idx);
    }

    for (auto& lane : lanesByCamera) {
        auto& indices = lane.second;
        std::sort(
            indices.begin(),
            indices.end(),
            [&](std::size_t lhs, std::size_t rhs) {
                const EncodedVideoSegment& a = videos[lhs];
                const EncodedVideoSegment& b = videos[rhs];
                if (a.startTs != b.startTs) return a.startTs < b.startTs;
                if (a.endTs != b.endTs) return a.endTs < b.endTs;
                if (a.sourceFilePath != b.sourceFilePath) {
                    return a.sourceFilePath < b.sourceFilePath;
                }
                return lhs < rhs;
            });
    }

    std::vector<int> orderedCameraIds;
    std::unordered_set<int> seenCameraIds;
    if (routerResult.is_object() &&
        routerResult.contains("camera_ids") &&
        routerResult["camera_ids"].is_array())
    {
        for (const auto& item : routerResult["camera_ids"]) {
            if (!item.is_number_integer()) continue;
            const int cameraId = item.get<int>();
            if (seenCameraIds.find(cameraId) != seenCameraIds.end()) continue;
            if (lanesByCamera.find(cameraId) == lanesByCamera.end()) continue;
            orderedCameraIds.push_back(cameraId);
            seenCameraIds.insert(cameraId);
        }
    }

    std::vector<int> remainingCameraIds;
    remainingCameraIds.reserve(lanesByCamera.size());
    for (const auto& lane : lanesByCamera) {
        if (seenCameraIds.find(lane.first) != seenCameraIds.end()) continue;
        remainingCameraIds.push_back(lane.first);
    }
    std::sort(
        remainingCameraIds.begin(),
        remainingCameraIds.end(),
        [](int lhs, int rhs) {
            const bool lhsUnknown = lhs <= 0;
            const bool rhsUnknown = rhs <= 0;
            if (lhsUnknown != rhsUnknown) return !lhsUnknown;
            return lhs < rhs;
        });

    orderedCameraIds.insert(
        orderedCameraIds.end(),
        remainingCameraIds.begin(),
        remainingCameraIds.end());

    for (const int cameraId : orderedCameraIds) {
        auto itLane = lanesByCamera.find(cameraId);
        if (itLane == lanesByCamera.end()) continue;
        orderedIndices.insert(
            orderedIndices.end(),
            itLane->second.begin(),
            itLane->second.end());
    }

    return orderedIndices;
}

AgentCore::ChatTemporalVideoAnalysisResult AgentCore::analyzeVideosWithOpenAISequentialTemporalChat_(
    const std::vector<EncodedVideoSegment>& videos,
    const nlohmann::json& routerResult,
    const std::string& userQuestionBase,
    const std::string& uploadedImageBase64,
    const std::string& openAiModelName,
    const std::string& openAiApiKey,
    int modelInputFps,
    int runningResolution,
    int chatSessionId,
    ChatTemporalState& chatTemporalState,
    bool requestCoreChatPriority,
    const std::function<bool()>& shouldAbort)
{
    ChatTemporalVideoAnalysisResult result;
    if (videos.empty()) {
        return result;
    }
    temporal::ensureState(chatTemporalState.state);
    ensureChatTemporalVisualState_(chatTemporalState.visualState);

    const std::vector<std::size_t> orderedIndices =
        buildChatTemporalExecutionOrder_(videos, routerResult);
    if (orderedIndices.empty()) {
        return result;
    }
    for (const std::size_t orderedIndex : orderedIndices) {
        if (orderedIndex >= videos.size()) continue;
        const EncodedVideoSegment& segment = videos[orderedIndex];
        if (segment.uploadAnalysisSegment && segment.uploadPlannedSampleCount > 0) {
            result.plannedSampleCount += segment.uploadPlannedSampleCount;
        }
    }
    const std::string effectiveModelName =
        openAiModelName.empty() ? std::string("gpt-5-mini") : openAiModelName;

    auto persistTemporalState = [&]() {
        chatTemporalState.touchedAt = std::chrono::steady_clock::now();
        if (chatTemporalState.planEnvelope.contains("plan_hash") &&
            chatTemporalState.planEnvelope["plan_hash"].is_string())
        {
            chatTemporalState.promptHash =
                chatTemporalState.planEnvelope["plan_hash"].get<std::string>();
        }
        if (chatSessionId > 0) {
            {
                std::lock_guard<std::mutex> lock(chatTemporalMu_);
                chatTemporalBySession_[chatSessionId] = chatTemporalState;
            }
            (void)persistChatTemporalState_(chatSessionId, chatTemporalState);
        }
    };

    Logger::instance().logDebug(
        "agent",
        "analyzeVideosWithOpenAISequentialTemporalChat_: videos=" +
        std::to_string(videos.size()) +
        " ordered_rounds=" + std::to_string(orderedIndices.size()) +
        " model=" + effectiveModelName +
        " fps=" + std::to_string(modelInputFps) +
        " running_resolution=" + std::to_string(runningResolution)
    );

    std::size_t executedRounds = 0;
    for (std::size_t executionPos = 0; executionPos < orderedIndices.size(); ++executionPos) {
        if (shouldAbort && shouldAbort()) {
            result.aborted = true;
            break;
        }

        const std::size_t segmentIndex = orderedIndices[executionPos];
        const EncodedVideoSegment& segment = videos[segmentIndex];
        const std::string nowIsoForInference = temporal::nowIso();
        const std::string temporalDecisionNowIso =
            temporal::decisionAnchorUtc(nowIsoForInference, segment.endTs);
        nlohmann::json temporalInput = temporal::buildInferenceInput(
            chatTemporalState.planEnvelope,
            chatTemporalState.state,
            segment.cameraId,
            temporalDecisionNowIso,
            segment.startTs,
            segment.endTs
        );

        Logger::instance().logDebug(
            "agent",
            "analyzeVideosWithOpenAISequentialTemporalChat_: round=" +
            std::to_string(executionPos + 1) + "/" + std::to_string(orderedIndices.size()) +
            " camera_id=" + std::to_string(segment.cameraId) +
            " segment_start=" + segment.startTs +
            " segment_end=" + segment.endTs +
            " now_utc=" +
            temporalInput.value("time_context", nlohmann::json::object()).value("now_utc", "") +
            " payload=" + temporalInput.dump()
        );

        const std::string roundPrompt =
            userQuestionBase + temporal::runtimePromptAppendix(temporalInput);

        int batchPrompt = 0;
        int batchOutput = 0;
        int batchTotal = 0;
        VideoHit hit = callOpenAIVisionVideoSegment_(
            segment,
            roundPrompt,
            uploadedImageBase64,
            std::vector<FaceReferenceImage>{},
            std::vector<NegativeReferenceImage>{},
            std::string(),
            std::string(),
            effectiveModelName,
            openAiApiKey,
            modelInputFps,
            /*expectedWindowSeconds*/ 0,
            runningResolution,
            std::string(kPreferredChatVideoPackagingMode_),
            batchPrompt,
            batchOutput,
            batchTotal,
            requestCoreChatPriority,
            shouldAbort
        );

        hit.segmentIndex = segmentIndex;

        result.promptTokens += batchPrompt;
        result.outputTokens += batchOutput;
        result.totalTokens += batchTotal;
        if (!hit.answer.empty()) {
            result.modelAnswer = hit.answer;
        }
        if (hit.analysisFailed) {
            result.failureReason = trimAscii(hit.analysisFailureReason);
            if (result.failureReason.empty()) {
                result.failureReason = "uploaded_video_chunk_analysis_failed";
            }
            result.aborted = true;
            Logger::instance().logDebug(
                "agent",
                "analyzeVideosWithOpenAISequentialTemporalChat_: aborting at round=" +
                    std::to_string(executionPos + 1) +
                    " failure_reason=" + result.failureReason);
            break;
        }
        if (segment.uploadAnalysisSegment && segment.uploadPlannedSampleCount > 0) {
            result.processedSampleCount += segment.uploadPlannedSampleCount;
        }

        const std::string roundEndTs =
            trimAscii(hit.segmentEndTs).empty() ? segment.endTs : hit.segmentEndTs;
        const std::string roundDecisionNow =
            temporal::decisionAnchorUtc(nowIsoForInference, roundEndTs);

        (void)applyChatIdentityContinuityRound_(
            hit,
            chatTemporalState.planEnvelope,
            roundDecisionNow,
            /*allowTemporalObservations=*/true,
            chatTemporalState.state,
            chatTemporalState.visualState,
            "agent",
            "analyzeVideosWithOpenAISequentialTemporalChat_");

        const temporal::EvalResult eval = temporal::evaluate(
            chatTemporalState.state,
            chatTemporalState.planEnvelope,
            roundDecisionNow
        );
        if (eval.alert) result.temporalAlert = true;
        if (eval.report) result.temporalReport = true;
        if (eval.operatorResults.is_array() && !eval.operatorResults.empty()) {
            result.temporalOperatorResults = eval.operatorResults;
        }
        if (!eval.summary.empty()) {
            result.temporalSummary = eval.summary;
        }

        persistTemporalState();
        ++executedRounds;
        result.allHits.push_back(hit);

        if (hit.hasMatch) {
            result.visibleHits.push_back(std::move(hit));
        }
    }

    Logger::instance().logDebug(
        "agent",
        "analyzeVideosWithOpenAISequentialTemporalChat_: completed rounds=" +
        std::to_string(executedRounds) + "/" + std::to_string(orderedIndices.size()) +
        " visible_hits=" + std::to_string(result.visibleHits.size()) +
        " all_hits=" + std::to_string(result.allHits.size()) +
        " planned_samples=" + std::to_string(result.plannedSampleCount) +
        " processed_samples=" + std::to_string(result.processedSampleCount) +
        " failure_reason=" + trimAscii(result.failureReason) +
        " aborted=" + std::string(result.aborted ? "true" : "false")
    );

    return result;
}

AgentCore::ChatTemporalVideoAnalysisResult AgentCore::analyzeVideosWithOpenAISequentialIdentityChat_(
    const std::vector<EncodedVideoSegment>& videos,
    const nlohmann::json& routerResult,
    const std::string& userQuestionBase,
    const std::string& uploadedImageBase64,
    const std::string& openAiModelName,
    const std::string& openAiApiKey,
    int modelInputFps,
    int runningResolution,
    int chatSessionId,
    ChatTemporalState& chatTemporalState,
    bool requestCoreChatPriority,
    const std::function<bool()>& shouldAbort)
{
    ChatTemporalVideoAnalysisResult result;
    if (videos.empty()) {
        return result;
    }

    temporal::ensureState(chatTemporalState.state);
    ensureChatTemporalVisualState_(chatTemporalState.visualState);

    const std::vector<std::size_t> orderedIndices =
        buildChatTemporalExecutionOrder_(videos, routerResult);
    if (orderedIndices.empty()) {
        return result;
    }
    for (const std::size_t orderedIndex : orderedIndices) {
        if (orderedIndex >= videos.size()) continue;
        const EncodedVideoSegment& segment = videos[orderedIndex];
        if (segment.uploadAnalysisSegment && segment.uploadPlannedSampleCount > 0) {
            result.plannedSampleCount += segment.uploadPlannedSampleCount;
        }
    }

    const std::string effectiveModelName =
        openAiModelName.empty() ? std::string("gpt-5-mini") : openAiModelName;

    auto persistIdentityState = [&]() {
        chatTemporalState.touchedAt = std::chrono::steady_clock::now();
        if (chatSessionId > 0) {
            {
                std::lock_guard<std::mutex> lock(chatTemporalMu_);
                chatTemporalBySession_[chatSessionId] = chatTemporalState;
            }
            (void)persistChatTemporalState_(chatSessionId, chatTemporalState);
        }
    };

    Logger::instance().logDebug(
        "agent",
        "analyzeVideosWithOpenAISequentialIdentityChat_: videos=" +
            std::to_string(videos.size()) +
            " ordered_rounds=" + std::to_string(orderedIndices.size()) +
            " model=" + effectiveModelName +
            " fps=" + std::to_string(modelInputFps) +
            " running_resolution=" + std::to_string(runningResolution));

    std::size_t executedRounds = 0;
    for (std::size_t executionPos = 0; executionPos < orderedIndices.size(); ++executionPos) {
        if (shouldAbort && shouldAbort()) {
            result.aborted = true;
            break;
        }

        const std::size_t segmentIndex = orderedIndices[executionPos];
        const EncodedVideoSegment& segment = videos[segmentIndex];

        std::string roundPrompt = userQuestionBase;
        const std::string identityMemoryAppendix =
            buildDirectChatIdentityMemoryPromptAppendix_(chatTemporalState.state);
        if (!identityMemoryAppendix.empty()) {
            roundPrompt += identityMemoryAppendix;
        }

        int batchPrompt = 0;
        int batchOutput = 0;
        int batchTotal = 0;
        VideoHit hit = callOpenAIVisionVideoSegment_(
            segment,
            roundPrompt,
            uploadedImageBase64,
            std::vector<FaceReferenceImage>{},
            std::vector<NegativeReferenceImage>{},
            std::string(),
            std::string(),
            effectiveModelName,
            openAiApiKey,
            modelInputFps,
            /*expectedWindowSeconds*/ 0,
            runningResolution,
            std::string(kPreferredChatVideoPackagingMode_),
            batchPrompt,
            batchOutput,
            batchTotal,
            requestCoreChatPriority,
            shouldAbort
        );

        hit.segmentIndex = segmentIndex;

        result.promptTokens += batchPrompt;
        result.outputTokens += batchOutput;
        result.totalTokens += batchTotal;
        if (!hit.answer.empty()) {
            result.modelAnswer = hit.answer;
        }
        if (hit.analysisFailed) {
            result.failureReason = trimAscii(hit.analysisFailureReason);
            if (result.failureReason.empty()) {
                result.failureReason = "uploaded_video_chunk_analysis_failed";
            }
            result.aborted = true;
            Logger::instance().logDebug(
                "agent",
                "analyzeVideosWithOpenAISequentialIdentityChat_: aborting at round=" +
                    std::to_string(executionPos + 1) +
                    " failure_reason=" + result.failureReason);
            break;
        }
        if (segment.uploadAnalysisSegment && segment.uploadPlannedSampleCount > 0) {
            result.processedSampleCount += segment.uploadPlannedSampleCount;
        }

        const std::string identityDecisionNowIso =
            temporal::decisionAnchorUtc(temporal::nowIso(), hit.segmentEndTs);
        (void)applyChatIdentityContinuityRound_(
            hit,
            nlohmann::json::object(),
            identityDecisionNowIso,
            /*allowTemporalObservations=*/false,
            chatTemporalState.state,
            chatTemporalState.visualState,
            "agent",
            "analyzeVideosWithOpenAISequentialIdentityChat_");

        persistIdentityState();
        ++executedRounds;
        result.allHits.push_back(hit);

        if (hit.hasMatch) {
            result.visibleHits.push_back(std::move(hit));
        }
    }

    Logger::instance().logDebug(
        "agent",
        "analyzeVideosWithOpenAISequentialIdentityChat_: completed rounds=" +
            std::to_string(executedRounds) + "/" + std::to_string(orderedIndices.size()) +
            " visible_hits=" + std::to_string(result.visibleHits.size()) +
            " all_hits=" + std::to_string(result.allHits.size()) +
            " planned_samples=" + std::to_string(result.plannedSampleCount) +
            " processed_samples=" + std::to_string(result.processedSampleCount) +
            " failure_reason=" + trimAscii(result.failureReason) +
            " aborted=" + std::string(result.aborted ? "true" : "false"));

    return result;
}










